  total_score     numeric,
  max_score       numeric,
  violations      int not null default 0,
  created_at      timestamptz not null default now(),
  unique (token),
  unique (application_id, exam_id)
);

-- ---------- RLS: admissions staff only (public pages use the server) ----------
do $$
declare t text;
begin
  foreach t in array array['admission_leads','lead_activities','admission_events','admission_bookings','admission_sequences',
                           'lead_sequence_runs','admission_templates','application_documents','admission_payments','admission_capacity',
                           'admission_costs','entrance_attempts'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_admissions', t);
    execute format('create policy %I on public.%I for all using (tenant_id = public.my_tenant_id() and public.is_admissions()) with check (tenant_id = public.my_tenant_id() and public.is_admissions())', t || '_admissions', t);
  end loop;
end $$;
alter table public.admission_sequence_steps enable row level security;
drop policy if exists admission_sequence_steps_admissions on public.admission_sequence_steps;
create policy admission_sequence_steps_admissions on public.admission_sequence_steps for all using (
  exists (select 1 from public.admission_sequences s where s.id = admission_sequence_steps.sequence_id and s.tenant_id = public.my_tenant_id() and public.is_admissions())
) with check (
  exists (select 1 from public.admission_sequences s where s.id = admission_sequence_steps.sequence_id and s.tenant_id = public.my_tenant_id() and public.is_admissions()));

-- Payments and entrance results are written only by the server (verified with the provider / marked by the engine).
drop policy if exists admission_payments_admissions on public.admission_payments;
drop policy if exists admission_payments_read on public.admission_payments;
create policy admission_payments_read on public.admission_payments for select using (tenant_id = public.my_tenant_id() and public.is_admissions());
drop policy if exists entrance_attempts_admissions on public.entrance_attempts;
drop policy if exists entrance_attempts_read on public.entrance_attempts;
create policy entrance_attempts_read on public.entrance_attempts for select using (tenant_id = public.my_tenant_id() and public.is_admissions());

insert into storage.buckets (id, name, public) values ('admissions', 'admissions', false) on conflict (id) do nothing;

-- ===== 20260101003000_review_fixes.sql =====
-- =========================================================================
-- EduClass Fusion: fixes from the full-spec review.
--  * The lead webhook key lived in tenant_settings, which every account in a
--    school (students and parents included) can read. It moves to
--    admission_secrets, which only the server can read.
--  * book_admission_event(): public tour / open-day booking checks capacity
--    and inserts in one locked step, so two families cannot both take the
--    last seats.
-- Apply AFTER 20260101002900. Idempotent.
-- =========================================================================

create table if not exists public.admission_secrets (
  tenant_id         uuid primary key references public.tenants(id) on delete cascade,
  lead_webhook_key  text unique,
  updated_at        timestamptz not null default now()
);
alter table public.admission_secrets enable row level security;
-- No policies: only the service role (server) reads or writes this table.
revoke all on public.admission_secrets from anon, authenticated;

do $$
begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'tenant_settings' and column_name = 'lead_webhook_key') then
    insert into public.admission_secrets (tenant_id, lead_webhook_key)
      select tenant_id, lead_webhook_key from public.tenant_settings where lead_webhook_key is not null
      on conflict (tenant_id) do update set lead_webhook_key = excluded.lead_webhook_key;
    alter table public.tenant_settings drop column lead_webhook_key;
  end if;
end $$;

-- Atomic booking (p_staff: staff may book unpublished or past sessions). Returns the booking token, or raises 'full' / 'not available' / 'already booked'.
create or replace function public.book_admission_event(p_event uuid, p_lead uuid, p_name text, p_phone text, p_email text, p_party int, p_staff boolean default false)
returns text language plpgsql security definer set search_path = public as $$
declare
  e public.admission_events;
  taken int;
  tok text;
begin
  select * into e from public.admission_events where id = p_event for update;
  if e.id is null or (not p_staff and (not e.published or e.starts_at < now())) then raise exception 'not available'; end if;
  if exists (select 1 from public.admission_bookings where event_id = p_event and status <> 'cancelled' and phone = p_phone) then raise exception 'already booked'; end if;
  select coalesce(sum(party_size), 0) into taken from public.admission_bookings where event_id = p_event and status <> 'cancelled';
  if taken + p_party > e.capacity then raise exception 'full'; end if;
  insert into public.admission_bookings (tenant_id, event_id, lead_id, name, phone, email, party_size)
    values (e.tenant_id, p_event, p_lead, p_name, p_phone, p_email, p_party) returning token into tok;
  return tok;
end $$;
revoke all on function public.book_admission_event(uuid, uuid, text, text, text, int, boolean) from public, anon, authenticated;
grant execute on function public.book_admission_event(uuid, uuid, text, text, text, int, boolean) to service_role;
grant all on public.admission_secrets to service_role;

-- ===== 20260101003100_community_crm.sql =====
-- =========================================================================
-- EduClass Fusion: parent and community CRM (phase 3).
--  * crm_interactions: calls, meetings, visits and notes with families,
--    alumni and partners (the timeline behind the 360° family profile).
--  * tickets / ticket_messages: complaints and requests with SLAs,
--    assignment, escalation and a satisfaction rating when resolved.
--  * surveys / survey_invites / survey_responses: NPS and other surveys
--    answered from a private link; anonymous surveys keep no link to the
--    family.
--  * family_segments: saved family filters for campaigns.
--  * reenrolment_rounds / reenrolment_responses: "Will your child return
--    next session?" with reasons.
--  * referral_rewards: a reward per referred family that enrols.
--  * alumni: former students, from graduation or self-registration.
--  * crm_campaigns: email/SMS/WhatsApp campaigns and newsletters.
--  * crm_partners: vendors, suppliers, sponsors and partner organisations.
-- School admins and principals manage all of it. Any staff member can log a
-- ticket and works the tickets they raised or are assigned; the bursar also
-- sees vendors and referral rewards. Parents act only through the server.
-- Apply AFTER 20260101003000. Idempotent.
-- =========================================================================

alter table public.guardians add column if not exists marketing_opt_out boolean not null default false;
alter table public.guardians add column if not exists unsubscribe_token text;
update public.guardians set unsubscribe_token = encode(gen_random_bytes(16), 'hex') where unsubscribe_token is null;
alter table public.guardians alter column unsubscribe_token set default encode(gen_random_bytes(16), 'hex');
create unique index if not exists guardians_unsubscribe_token on public.guardians(unsubscribe_token);

alter table public.tenant_settings add column if not exists ticket_sla jsonb not null default '{}'::jsonb;   -- { "<priority>": { "respond": hours, "resolve": hours } }
alter table public.tenant_settings add column if not exists referral_reward_kind text not null default 'fee_discount';
alter table public.tenant_settings drop constraint if exists tenant_settings_referral_reward_kind_check;
alter table public.tenant_settings add constraint tenant_settings_referral_reward_kind_check check (referral_reward_kind in ('fee_discount','wallet_credit','gift','cash'));
alter table public.tenant_settings add column if not exists referral_reward_amount numeric(14,2) not null default 0;

create or replace function public.is_bursar_or_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_role(array['school_admin','principal','platform_admin','bursar']);
$$;
grant execute on function public.is_bursar_or_admin() to authenticated;

-- ---------- alumni and partners (interactions point at them) ----------
create table if not exists public.alumni (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null references public.tenants(id) on delete cascade,
  student_id        uuid references public.students(id) on delete set null,
  full_name         text not null check (length(full_name) between 2 and 160),
  graduation_year   int check (graduation_year between 1900 and 2200),
  last_class        text,
  email             text,
  phone             text,
  occupation        text,
  employer          text,
  further_study     text,             -- university / college and course
  city              text,
  country           text,
  linkedin          text,
  mentor            boolean not null default false,   -- happy to mentor current students
  consent_contact   boolean not null default true,
  status            text not null default 'active' check (status in ('pending','active','archived')),
  source            text not null default 'graduated' check (source in ('graduated','self','import','staff')),
  notes             text,
  update_token      text not null default encode(gen_random_bytes(16), 'hex'),   -- private self-update link
  unsubscribe_token text not null default encode(gen_random_bytes(16), 'hex'),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (update_token),
  unique (unsubscribe_token)
);
create unique index if not exists alumni_student on public.alumni(tenant_id, student_id) where student_id is not null;
create index if not exists alumni_year on public.alumni(tenant_id, graduation_year);

create table if not exists public.crm_partners (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  name            text not null check (length(name) between 2 and 160),
  kind            text not null default 'vendor' check (kind in ('vendor','supplier','partner','sponsor','ngo','government','media','other')),
  category        text,               -- e.g. "uniforms", "catering", "ICT"
  status          text not null default 'active' check (status in ('prospect','active','inactive')),
  contact_name    text,
  email           text,
  phone           text,
  website         text,
  address         text,
  contract_start  date,
  contract_end    date,
  contract_value  numeric(14,2),
  rating          int check (rating between 1 and 5),
  tags            text[] not null default '{}',
  notes           text,
  created_by      uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index if not exists crm_partners_kind on public.crm_partners(tenant_id, kind);

-- ---------- interactions ----------
create table if not exists public.crm_interactions (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  guardian_id  uuid references public.guardians(id) on delete cascade,
  student_id   uuid references public.students(id) on delete set null,
  alumni_id    uuid references public.alumni(id) on delete cascade,
  partner_id   uuid references public.crm_partners(id) on delete cascade,
  kind         text not null default 'note' check (kind in ('note','call','meeting','email','sms','whatsapp','visit','retention','other')),
  body         text not null check (length(body) between 1 and 4000),
  occurred_at  timestamptz not null default now(),
  follow_up_at timestamptz,
  actor_id     uuid references public.users(id) on delete set null,
  created_at   timestamptz not null default now(),
  check (num_nonnulls(guardian_id, alumni_id, partner_id) = 1)
);
create index if not exists crm_interactions_guardian on public.crm_interactions(guardian_id, occurred_at desc);
create index if not exists crm_interactions_alumni on public.crm_interactions(alumni_id, occurred_at desc);
create index if not exists crm_interactions_partner on public.crm_interactions(partner_id, occurred_at desc);

-- ---------- tickets ----------
create table if not exists public.tickets (
  id                  uuid primary key default gen_random_uuid(),
  tenant_id           uuid not null references public.tenants(id) on delete cascade,
  ticket_no           text not null,
  guardian_id         uuid references public.guardians(id) on delete set null,
  student_id          uuid references public.students(id) on delete set null,
  kind                text not null default 'complaint' check (kind in ('complaint','request','enquiry','feedback')),
  category            text not null default 'other' check (category in ('academic','fees','transport','safety','bullying','facilities','food','health','staff','communication','admissions','other')),
  priority            text not null default 'normal' check (priority in ('low','normal','high','urgent')),
  channel             text not null default 'portal' check (channel in ('portal','phone','email','walk_in','whatsapp','survey')),
  subject             text not null check (length(subject) between 2 and 160),
  body                text not null check (length(body) between 1 and 5000),
  status              text not null default 'open' check (status in ('open','in_progress','waiting','resolved','closed')),
  assigned_to         uuid references public.users(id) on delete set null,
  respond_due_at      timestamptz,
  resolve_due_at      timestamptz,
  first_response_at   timestamptz,
  resolved_at         timestamptz,
  closed_at           timestamptz,
  escalation_level    int not null default 0 check (escalation_level between 0 and 2),   -- 1 = response overdue, 2 = resolution overdue
  escalated_at        timestamptz,
  satisfaction        int check (satisfaction between 1 and 5),
  satisfaction_note   text,
  token               text not null default encode(gen_random_bytes(16), 'hex'),          -- lets the family rate the outcome from a link
  created_by          uuid references public.users(id) on delete set null,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (tenant_id, ticket_no),
  unique (token)
);
create index if not exists tickets_open on public.tickets(tenant_id, status, resolve_due_at) where status not in ('resolved','closed');
create index if not exists tickets_guardian on public.tickets(guardian_id, created_at desc);
create index if not exists tickets_assigned on public.tickets(tenant_id, assigned_to) where status not in ('resolved','closed');

create table if not exists public.ticket_messages (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  ticket_id   uuid not null references public.tickets(id) on delete cascade,
  author      text not null check (author in ('staff','family','system')),
  author_id   uuid references public.users(id) on delete set null,
  body        text not null check (length(body) between 1 and 5000),
  internal    boolean not null default false,     -- staff-only note, never shown to the family
  created_at  timestamptz not null default now()
);
create index if not exists ticket_messages_ticket on public.ticket_messages(ticket_id, created_at);

-- ---------- surveys ----------
create table if not exists public.surveys (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  title        text not null check (length(title) between 2 and 160),
  intro        text,
  questions    jsonb not null default '[]'::jsonb,    -- [{ id, type: nps|rating|choice|text, label, options?, required? }]
  audience     jsonb not null default '{}'::jsonb,    -- { class_group_ids?, segment_id? }
  anonymous    boolean not null default false,
  status       text not null default 'draft' check (status in ('draft','open','closed')),
  closes_at    timestamptz,
  sent_at      timestamptz,
  created_by   uuid references public.users(id) on delete set null,
  created_at   timestamptz not null default now()
);

create table if not exists public.survey_invites (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  survey_id     uuid not null references public.surveys(id) on delete cascade,
  guardian_id   uuid not null references public.guardians(id) on delete cascade,
  token         text not null default encode(gen_random_bytes(16), 'hex'),
  sent_at       timestamptz not null default now(),
  reminded_at   timestamptz,
  responded_at  timestamptz,
  unique (survey_id, guardian_id),
  unique (token)
);

create table if not exists public.survey_responses (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  survey_id    uuid not null references public.surveys(id) on delete cascade,
  guardian_id  uuid references public.guardians(id) on delete set null,   -- null when the survey is anonymous
  nps          int check (nps between 0 and 10),
  answers      jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now()
);
create index if not exists survey_responses_survey on public.survey_responses(survey_id);
create index if not exists survey_responses_guardian on public.survey_responses(guardian_id, created_at desc);

-- ---------- segments ----------
create table if not exists public.family_segments (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  name        text not null check (length(name) between 2 and 80),
  rules       jsonb not null default '{}'::jsonb,
  created_by  uuid references public.users(id) on delete set null,
  created_at  timestamptz not null default now(),
  unique (tenant_id, name)
);

-- ---------- re-enrolment ----------
create table if not exists public.reenrolment_rounds (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  title            text not null check (length(title) between 2 and 120),      -- e.g. "2027/2028 session"
  message          text,
  class_group_ids  uuid[] not null default '{}',     -- empty = every class
  deadline         date,
  status           text not null default 'open' check (status in ('draft','open','closed')),
  created_by       uuid references public.users(id) on delete set null,
  created_at       timestamptz not null default now()
);

create table if not exists public.reenrolment_responses (
  round_id      uuid not null references public.reenrolment_rounds(id) on delete cascade,
  student_id    uuid not null references public.students(id) on delete cascade,
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  guardian_id   uuid references public.guardians(id) on delete set null,
  intent        text not null check (intent in ('returning','not_returning','undecided')),
  reason        text check (reason in ('fees','relocation','academics','distance','another_school','dissatisfied','graduating','other')),
  note          text,
  responded_at  timestamptz not null default now(),
  primary key (round_id, student_id)
);

-- ---------- referral rewards ----------
create table if not exists public.referral_rewards (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  guardian_id  uuid not null references public.guardians(id) on delete cascade,
  lead_id      uuid references public.admission_leads(id) on delete set null,
  kind         text not null default 'fee_discount' check (kind in ('fee_discount','wallet_credit','gift','cash')),
  amount       numeric(14,2) not null default 0 check (amount >= 0),
  status       text not null default 'pending' check (status in ('pending','approved','issued','cancelled')),
  note         text,
  approved_by  uuid references public.users(id) on delete set null,
  issued_at    timestamptz,
  created_at   timestamptz not null default now()
);
create unique index if not exists referral_rewards_lead on public.referral_rewards(lead_id) where lead_id is not null;

-- A referred family that enrols earns the referrer the school's standard reward, once.
create or replace function public.referral_reward_on_enrol()
returns trigger language plpgsql security definer set search_path = public as $$
declare s record;
begin
  if new.stage = 'enrolled' and new.referred_by is not null and (tg_op = 'INSERT' or old.stage is distinct from 'enrolled') then
    select referral_reward_kind, referral_reward_amount into s from public.tenant_settings where tenant_id = new.tenant_id;
    if s is not null and coalesce(s.referral_reward_amount, 0) > 0 then
      insert into public.referral_rewards (tenant_id, guardian_id, lead_id, kind, amount)
        values (new.tenant_id, new.referred_by, new.id, s.referral_reward_kind, s.referral_reward_amount)
        on conflict (lead_id) where lead_id is not null do nothing;
    end if;
  end if;
  return new;
end $$;
drop trigger if exists admission_leads_referral_reward on public.admission_leads;
create trigger admission_leads_referral_reward after insert or update of stage on public.admission_leads
  for each row execute function public.referral_reward_on_enrol();

-- ---------- campaigns and newsletters ----------
create table if not exists public.crm_campaigns (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  name          text not null check (length(name) between 2 and 120),
  kind          text not null default 'campaign' check (kind in ('campaign','newsletter')),
  subject       text not null check (length(subject) between 2 and 160),
  body          text not null default '',
  blocks        jsonb not null default '[]'::jsonb,       -- newsletter sections: [{ heading, text, image_url, link_url, link_label }]
  channels      text[] not null default '{email}',
  audience      jsonb not null default '{"type":"parents"}'::jsonb,
  status        text not null default 'draft' check (status in ('draft','scheduled','sending','sent','cancelled')),
  scheduled_at  timestamptz,
  sent_at       timestamptz,
  recipients    int not null default 0,
  created_by    uuid references public.users(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index if not exists crm_campaigns_due on public.crm_campaigns(scheduled_at) where status = 'scheduled';

-- Attendance per student over a window, for retention flags (server only).
create or replace function public.attendance_rates(p_tenant uuid, p_since date)
returns table (student_id uuid, present int, total int) language sql stable security definer set search_path = public as $$
  select a.student_id, count(*) filter (where a.status in ('present','late'))::int, count(*)::int
  from public.class_attendance a where a.tenant_id = p_tenant and a.date >= p_since group by a.student_id;
$$;
revoke all on function public.attendance_rates(uuid, date) from public, anon, authenticated;
grant execute on function public.attendance_rates(uuid, date) to service_role;

-- ---------- RLS ----------
do $$
declare t text;
begin
  foreach t in array array['alumni','surveys','survey_invites','survey_responses','family_segments','reenrolment_rounds',
                           'reenrolment_responses','crm_campaigns'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_admin', t);
    execute format('create policy %I on public.%I for all using (tenant_id = public.my_tenant_id() and public.is_school_admin()) with check (tenant_id = public.my_tenant_id() and public.is_school_admin())', t || '_admin', t);
  end loop;
  foreach t in array array['crm_partners','referral_rewards'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_admin', t);
    execute format('create policy %I on public.%I for all using (tenant_id = public.my_tenant_id() and public.is_bursar_or_admin()) with check (tenant_id = public.my_tenant_id() and public.is_bursar_or_admin())', t || '_admin', t);
  end loop;
end $$;

-- Responses and invites are written by the server (from the family's private link).
drop policy if exists survey_responses_admin on public.survey_responses;
drop policy if exists survey_responses_read on public.survey_responses;
create policy survey_responses_read on public.survey_responses for select using (tenant_id = public.my_tenant_id() and public.is_school_admin());
drop policy if exists survey_invites_admin on public.survey_invites;
drop policy if exists survey_invites_read on public.survey_invites;
create policy survey_invites_read on public.survey_invites for select using (tenant_id = public.my_tenant_id() and public.is_school_admin());

-- Interactions: admins see every one; other staff log and see their own.
alter table public.crm_interactions enable row level security;
drop policy if exists crm_interactions_admin on public.crm_interactions;
create policy crm_interactions_admin on public.crm_interactions for all
  using (tenant_id = public.my_tenant_id() and public.is_school_admin())
  with check (tenant_id = public.my_tenant_id() and public.is_school_admin());
drop policy if exists crm_interactions_own on public.crm_interactions;
create policy crm_interactions_own on public.crm_interactions for all
  using (tenant_id = public.my_tenant_id() and public.is_staff() and actor_id = auth.uid())
  with check (tenant_id = public.my_tenant_id() and public.is_staff() and actor_id = auth.uid() and alumni_id is null and partner_id is null);

-- Tickets: admins see all; other staff see the ones they raised or are assigned.
-- New tickets are numbered by the server, so inserts go through the API.
alter table public.tickets enable row level security;
drop policy if exists tickets_read on public.tickets;
create policy tickets_read on public.tickets for select using (
  tenant_id = public.my_tenant_id() and (public.is_school_admin() or (public.is_staff() and (assigned_to = auth.uid() or created_by = auth.uid()))));
drop policy if exists tickets_update on public.tickets;
create policy tickets_update on public.tickets for update using (
  tenant_id = public.my_tenant_id() and (public.is_school_admin() or (public.is_staff() and assigned_to = auth.uid())))
  with check (tenant_id = public.my_tenant_id());
drop policy if exists tickets_delete on public.tickets;
create policy tickets_delete on public.tickets for delete using (tenant_id = public.my_tenant_id() and public.is_school_admin());

-- Only admins may reassign a ticket; the assignee may not hand it to someone else or change its number.
create or replace function public.tickets_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or public.is_school_admin() then return new; end if;
  if new.assigned_to is distinct from old.assigned_to or new.ticket_no <> old.ticket_no or new.tenant_id <> old.tenant_id
     or new.guardian_id is distinct from old.guardian_id or new.token <> old.token then
    raise exception 'only a school admin can reassign or re-file a ticket';
  end if;
  return new;
end $$;
drop trigger if exists tickets_guard on public.tickets;
create trigger tickets_guard before update on public.tickets for each row execute function public.tickets_guard();

alter table public.ticket_messages enable row level security;
drop policy if exists ticket_messages_rw on public.ticket_messages;
create policy ticket_messages_rw on public.ticket_messages for select using (
  tenant_id = public.my_tenant_id() and exists (select 1 from public.tickets t where t.id = ticket_messages.ticket_id));
drop policy if exists ticket_messages_insert on public.ticket_messages;
create policy ticket_messages_insert on public.ticket_messages for insert with check (
  tenant_id = public.my_tenant_id() and author = 'staff' and author_id = auth.uid()
  and exists (select 1 from public.tickets t where t.id = ticket_messages.ticket_id and t.tenant_id = public.my_tenant_id()
              and (public.is_school_admin() or t.assigned_to = auth.uid() or t.created_by = auth.uid())));

grant all on public.alumni, public.crm_partners, public.crm_interactions, public.tickets, public.ticket_messages, public.surveys,
  public.survey_invites, public.survey_responses, public.family_segments, public.reenrolment_rounds, public.reenrolment_responses,
  public.referral_rewards, public.crm_campaigns to service_role;

-- ===== 20260101003200_core_security.sql =====
-- =========================================================================
-- EduClass Fusion: core platform and security (phase 4).
--  * Roles: counsellor (pastoral staff) and alumni (former students; they
--    sign in to their own alumni page and see no school data).
--  * school_sections (Nursery, Primary, Secondary, Sixth form …) with a
--    curriculum framework each; classes belong to a section and may use a
--    different framework (mixed setups).
--  * Currency stored as an ISO code (NGN, GBP, USD …).
--  * data_changes: a record of every create, edit and delete in the
--    school's data, with who did it and what changed. Admins only.
--  * Password rules (length, character mix, expiry) and session rules (idle
--    time-out, maximum session length, sign out other devices).
--  * Staff access restrictions by network (IP allow-list) and/or approved
--    devices, enforced in the database through short-lived access grants.
--  * Single sign-on policy (Google Workspace, Microsoft 365) and phone
--    sign-in codes.
--  * Consent records for children's data (NDPA / GDPR) and a privacy notice.
-- Apply AFTER 20260101003100. Idempotent.
-- =========================================================================

-- ---------- roles ----------
alter table public.users drop constraint if exists users_role_check;
alter table public.users add constraint users_role_check check (role in (
  'student','teacher','school_admin','it_admin','parent','platform_admin',
  'principal','bursar','librarian','hr_manager','qa_officer','gate_officer',
  'transport_officer','hostel_warden','nurse','admissions_officer','cashier',
  'counsellor','alumni'
));
create or replace function public.is_staff()
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_role(array['teacher','school_admin','it_admin','platform_admin','principal',
    'bursar','librarian','hr_manager','qa_officer','gate_officer','transport_officer',
    'hostel_warden','nurse','admissions_officer','cashier','counsellor']);
$$;
-- Second factor rules never apply to families or alumni.
create or replace function public.mfa_ok(p_setting text, p_role text, p_extra text[])
returns boolean language sql stable set search_path = public as $$
  select case
    when coalesce(p_setting, 'off') = 'off' then true
    when p_role in ('student','parent','alumni') then true
    when public.session_aal() = 'aal2' then true
    when p_setting = 'admins' then not ((array[p_role] || coalesce(p_extra, '{}'))
      && array['school_admin','principal','it_admin','bursar','hr_manager','platform_admin'])
    else false
  end;
$$;
-- Counsellors read health records alongside the nurse.
drop policy if exists medical_read on public.medical_profiles;
create policy medical_read on public.medical_profiles for select using (
  tenant_id = public.my_tenant_id() and (public.has_role(array['nurse','school_admin','principal','platform_admin','hostel_warden','counsellor'])
    or public.teaches_student(student_id) or public.is_guardian_of(student_id)));
drop policy if exists sickbay_read on public.sickbay_visits;
create policy sickbay_read on public.sickbay_visits for select using (
  tenant_id = public.my_tenant_id() and (public.has_role(array['nurse','school_admin','principal','platform_admin','hostel_warden','counsellor'])
    or public.is_guardian_of(student_id)));

alter table public.alumni add column if not exists user_id uuid unique references public.users(id) on delete set null;

-- ---------- settings ----------
update public.tenant_settings set currency = 'NGN' where currency is null or currency !~ '^[A-Z]{3}$';
alter table public.tenant_settings drop constraint if exists tenant_settings_currency_check;
alter table public.tenant_settings add constraint tenant_settings_currency_check check (currency ~ '^[A-Z]{3}$');
alter table public.tenant_settings add column if not exists curriculum text;
alter table public.tenant_settings add column if not exists password_min_length int not null default 8;
alter table public.tenant_settings add column if not exists password_require_mixed_case boolean not null default false;
alter table public.tenant_settings add column if not exists password_require_number boolean not null default true;
alter table public.tenant_settings add column if not exists password_require_symbol boolean not null default false;
alter table public.tenant_settings add column if not exists password_max_age_days int not null default 0;
alter table public.tenant_settings add column if not exists password_policy_scope text not null default 'staff';
alter table public.tenant_settings add column if not exists session_idle_minutes int not null default 0;
alter table public.tenant_settings add column if not exists session_max_hours int not null default 0;
alter table public.tenant_settings add column if not exists staff_access_mode text not null default 'off';
alter table public.tenant_settings add column if not exists staff_access_roles text not null default 'except_admins';
alter table public.tenant_settings add column if not exists staff_ip_allowlist text[] not null default '{}';
alter table public.tenant_settings add column if not exists sso_policy text not null default 'optional';
alter table public.tenant_settings add column if not exists sso_domains text[] not null default '{}';
alter table public.tenant_settings add column if not exists sso_auto_join boolean not null default false;
alter table public.tenant_settings add column if not exists allow_phone_login boolean not null default true;
alter table public.tenant_settings add column if not exists privacy_notice text;
alter table public.tenant_settings add column if not exists privacy_notice_version int not null default 1;
alter table public.tenant_settings add column if not exists audit_retention_days int not null default 730;
do $$
begin
  alter table public.tenant_settings drop constraint if exists tenant_settings_security_check;
  alter table public.tenant_settings add constraint tenant_settings_security_check check (
    password_min_length between 8 and 64 and password_max_age_days between 0 and 730
    and password_policy_scope in ('staff','all')
    and (session_idle_minutes = 0 or session_idle_minutes between 5 and 720)
    and (session_max_hours = 0 or session_max_hours between 1 and 720)
    and staff_access_mode in ('off','ip','device','ip_or_device')
    and staff_access_roles in ('all_staff','except_admins')
    and sso_policy in ('optional','required_staff')
    and audit_retention_days between 30 and 3650);
end $$;

alter table public.users add column if not exists password_changed_at timestamptz;
update public.users set password_changed_at = now() where password_changed_at is null;
alter table public.users alter column password_changed_at set default now();

-- Users cannot move their own password clock; only the server sets it after a change.
create or replace function public.users_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return new; end if; -- service role / SQL editor
  if new.tenant_id is distinct from old.tenant_id then
    raise exception 'tenant_id cannot be changed';
  end if;
  if new.password_changed_at is distinct from old.password_changed_at then
    raise exception 'password_changed_at is set by the server';
  end if;
  if (new.role is distinct from old.role or new.extra_roles is distinct from old.extra_roles
      or new.active is distinct from old.active) then
    if new.id = auth.uid() then
      raise exception 'you cannot change your own role or status';
    end if;
    if not public.is_school_admin() then
      raise exception 'only school admins can change roles';
    end if;
    if new.role = 'platform_admin' or 'platform_admin' = any(new.extra_roles) then
      raise exception 'platform_admin cannot be granted from a tenant';
    end if;
  end if;
  return new;
end $$;

-- ---------- sections and curriculum ----------
create table if not exists public.school_sections (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  name          text not null check (length(name) between 1 and 60),
  kind          text not null default 'other' check (kind in ('nursery','primary','secondary','sixth_form','other')),
  curriculum    text,                          -- framework key, e.g. 'nigeria_ube', 'uk_eyfs', 'igcse'
  head_user_id  uuid references public.users(id) on delete set null,
  position      int not null default 0,
  created_at    timestamptz not null default now(),
  unique (tenant_id, name)
);
alter table public.class_groups add column if not exists section_id uuid references public.school_sections(id) on delete set null;
alter table public.class_groups add column if not exists curriculum text;     -- overrides the section's framework
create index if not exists class_groups_section on public.class_groups(section_id);
alter table public.school_sections enable row level security;
drop policy if exists school_sections_read on public.school_sections;
create policy school_sections_read on public.school_sections for select using (tenant_id = public.my_tenant_id());
drop policy if exists school_sections_admin on public.school_sections;
create policy school_sections_admin on public.school_sections for all using (tenant_id = public.my_tenant_id() and public.is_school_admin())
  with check (tenant_id = public.my_tenant_id() and public.is_school_admin());

-- ---------- access restrictions, sessions, sign-in codes ----------
create table if not exists public.staff_devices (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  user_id      uuid not null references public.users(id) on delete cascade,
  device_hash  text not null,
  label        text,
  user_agent   text,
  last_ip      text,
  status       text not null default 'pending' check (status in ('pending','approved','revoked')),
  approved_by  uuid references public.users(id) on delete set null,
  approved_at  timestamptz,
  last_seen_at timestamptz not null default now(),
  created_at   timestamptz not null default now(),
  unique (user_id, device_hash)
);
alter table public.staff_devices enable row level security;
drop policy if exists staff_devices_admin on public.staff_devices;
create policy staff_devices_admin on public.staff_devices for all using (tenant_id = public.my_tenant_id() and public.is_school_admin())
  with check (tenant_id = public.my_tenant_id() and public.is_school_admin());
drop policy if exists staff_devices_own on public.staff_devices;
create policy staff_devices_own on public.staff_devices for select using (user_id = auth.uid());

-- Written by the server after it has checked the request's network and device.
create table if not exists public.access_grants (
  user_id     uuid not null references public.users(id) on delete cascade,
  session_id  uuid not null,
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  ip          text,
  expires_at  timestamptz not null,
  primary key (user_id, session_id)
);
alter table public.access_grants enable row level security;
revoke all on public.access_grants from anon, authenticated;

create table if not exists public.phone_login_codes (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references public.users(id) on delete cascade,
  phone       text not null,
  code_hash   text not null,
  attempts    int not null default 0,
  ip          text,
  expires_at  timestamptz not null,
  used_at     timestamptz,
  created_at  timestamptz not null default now()
);
create index if not exists phone_login_codes_phone on public.phone_login_codes(phone, created_at desc);
alter table public.phone_login_codes enable row level security;
revoke all on public.phone_login_codes from anon, authenticated;

-- The current session's id and sign-in method, from the access token.
create or replace function public.session_id()
returns uuid language sql stable set search_path = public as $$
  select nullif(auth.jwt() ->> 'session_id', '')::uuid;
$$;
create or replace function public.session_used_sso()
returns boolean language sql stable set search_path = public as $$
  select exists (select 1 from jsonb_array_elements(case when jsonb_typeof(auth.jwt() -> 'amr') = 'array' then auth.jwt() -> 'amr' else '[]'::jsonb end) e
                 where e ->> 'method' in ('oauth','sso/saml'));
$$;

-- Why this session may not use the school's data right now, or null when it may.
create or replace function public.session_block(p_user public.users, p_s public.tenant_settings)
returns text language plpgsql stable security definer set search_path = public, auth as $$
declare
  staff boolean := p_user.role not in ('student','parent','alumni');
  admin boolean := (array[p_user.role] || coalesce(p_user.extra_roles, '{}')) && array['school_admin','principal','platform_admin'];
  started timestamptz;
begin
  if p_s.tenant_id is null then return null; end if;
  if coalesce(p_s.password_max_age_days, 0) > 0 and (staff or p_s.password_policy_scope = 'all')
     and coalesce(p_user.password_changed_at, 'epoch'::timestamptz) < now() - make_interval(days => p_s.password_max_age_days) then
    return 'password_expired';
  end if;
  if staff and p_s.sso_policy = 'required_staff' and not public.session_used_sso() then
    return 'sso_required';
  end if;
  if coalesce(p_s.session_max_hours, 0) > 0 and staff then
    begin
      select s.created_at into started from auth.sessions s where s.id = public.session_id();
    exception when others then
      started := now();   -- sign-in records unreadable: never lock a whole school out over it
    end;
    if started is null or started < now() - make_interval(hours => p_s.session_max_hours) then return 'session_expired'; end if;
  end if;
  if staff and coalesce(p_s.staff_access_mode, 'off') <> 'off' and not (p_s.staff_access_roles = 'except_admins' and admin) then
    if not exists (select 1 from public.access_grants g where g.user_id = p_user.id and g.session_id = public.session_id() and g.expires_at > now()) then
      return 'access_restricted';
    end if;
  end if;
  return null;
end $$;

-- The caller's school. Empty when the school is suspended, the user is
-- deactivated or an alumnus, a required second factor is missing, or a
-- password, sign-on, session or network rule blocks this session.
create or replace function public.my_tenant_id()
returns uuid language sql stable security definer set search_path = public as $$
  select u.tenant_id
  from public.users u
  join public.tenants t on t.id = u.tenant_id
  left join public.tenant_settings s on s.tenant_id = u.tenant_id
  where u.id = auth.uid() and t.status = 'active' and u.active and u.role <> 'alumni'
    and public.mfa_ok(s.require_mfa, u.role, u.extra_roles)
    and public.session_block(u, s) is null;
$$;

create or replace function public.my_account_state()
returns jsonb language sql stable security definer set search_path = public as $$
  select case
    when u.id is null then jsonb_build_object('state', 'no_profile')
    when t.status <> 'active' then jsonb_build_object('state', t.status, 'school', t.name, 'message', t.status_message)
    when not u.active then jsonb_build_object('state', 'deactivated', 'school', t.name)
    when u.role = 'alumni' then jsonb_build_object('state', 'alumni', 'school', t.name)
    when not public.mfa_ok(s.require_mfa, u.role, u.extra_roles) then jsonb_build_object('state', 'mfa_required', 'school', t.name)
    when public.session_block(u, s) is not null then jsonb_build_object('state', public.session_block(u, s), 'school', t.name)
    else jsonb_build_object('state', 'active')
  end
  from (select auth.uid() as uid) me
  left join public.users u on u.id = me.uid
  left join public.tenants t on t.id = u.tenant_id
  left join public.tenant_settings s on s.tenant_id = u.tenant_id;
$$;
grant execute on function public.my_account_state(), public.session_id(), public.session_used_sso() to authenticated;
revoke all on function public.session_block(public.users, public.tenant_settings) from public, anon, authenticated;

-- Families and alumni see staff names; alumni themselves are not listed to others.
drop policy if exists users_self_select on public.users;
create policy users_self_select on public.users for select using (
  (id = auth.uid() and public.my_tenant_id() is not null)
  or (tenant_id = public.my_tenant_id() and (public.is_staff() or role not in ('student','parent','alumni')))
);

-- Signed-in devices for the caller, and signing them out.
create or replace function public.my_sessions()
returns table (id uuid, created_at timestamptz, updated_at timestamptz, user_agent text, ip text, current boolean)
language plpgsql stable security definer set search_path = public, auth as $$
begin
  return query select s.id, s.created_at, s.updated_at, s.user_agent::text, host(s.ip)::text, s.id = public.session_id()
    from auth.sessions s where s.user_id = auth.uid() order by s.updated_at desc nulls last;
end $$;
create or replace function public.end_my_sessions(p_session uuid default null, p_others boolean default false)
returns int language plpgsql security definer set search_path = public, auth as $$
declare n int;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  delete from auth.sessions s where s.user_id = auth.uid()
    and ((p_session is not null and s.id = p_session) or (p_others and s.id is distinct from public.session_id()));
  get diagnostics n = row_count;
  return n;
end $$;
-- An admin signs a member of their school out everywhere.
create or replace function public.end_user_sessions(p_user uuid)
returns int language plpgsql security definer set search_path = public, auth as $$
declare n int;
begin
  if not public.is_school_admin() or not exists (select 1 from public.users where id = p_user and tenant_id = public.my_tenant_id()) then
    raise exception 'not allowed';
  end if;
  delete from auth.sessions where user_id = p_user;
  get diagnostics n = row_count;
  delete from public.access_grants where user_id = p_user;
  return n;
end $$;
grant execute on function public.my_sessions(), public.end_my_sessions(uuid, boolean), public.end_user_sessions(uuid) to authenticated;

-- ---------- consent ----------
create table if not exists public.consent_purposes (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  key          text not null check (key ~ '^[a-z0-9_]{2,40}$'),
  title        text not null check (length(title) between 2 and 120),
  description  text not null default '',
  per_child    boolean not null default true,      -- asked for each child, or once per family
  required     boolean not null default false,     -- needed to provide the service (recorded, not optional)
  version      int not null default 1,
  active       boolean not null default true,
  position     int not null default 0,
  updated_at   timestamptz not null default now(),
  unique (tenant_id, key)
);
create table if not exists public.consent_records (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  purpose_id   uuid not null references public.consent_purposes(id) on delete cascade,
  version      int not null,
  guardian_id  uuid references public.guardians(id) on delete set null,
  student_id   uuid references public.students(id) on delete cascade,
  granted      boolean not null,
  method       text not null default 'portal' check (method in ('portal','link','paper','staff','email')),
  recorded_by  uuid references public.users(id) on delete set null,
  note         text,
  ip           text,
  user_agent   text,
  created_at   timestamptz not null default now()
);
create index if not exists consent_records_lookup on public.consent_records(tenant_id, purpose_id, student_id, guardian_id, created_at desc);
alter table public.consent_purposes enable row level security;
alter table public.consent_records enable row level security;
drop policy if exists consent_purposes_read on public.consent_purposes;
create policy consent_purposes_read on public.consent_purposes for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists consent_purposes_admin on public.consent_purposes;
create policy consent_purposes_admin on public.consent_purposes for all using (tenant_id = public.my_tenant_id() and public.is_school_admin())
  with check (tenant_id = public.my_tenant_id() and public.is_school_admin());
-- Staff read consents (e.g. photo permission before posting); records are added, never edited.
drop policy if exists consent_records_read on public.consent_records;
create policy consent_records_read on public.consent_records for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists consent_records_admin on public.consent_records;
create policy consent_records_admin on public.consent_records for insert with check (
  tenant_id = public.my_tenant_id() and public.is_school_admin() and recorded_by = auth.uid() and method in ('paper','staff','email'));

-- ---------- change history ----------
create table if not exists public.data_changes (
  id          bigint generated always as identity primary key,
  tenant_id   uuid not null,
  table_name  text not null,
  row_id      text,
  op          text not null check (op in ('insert','update','delete')),
  actor_id    uuid,
  actor       text not null default 'system',     -- user, guardian:<id>, public, system
  changes     jsonb not null default '{}'::jsonb,
  at          timestamptz not null default now()
);
create index if not exists data_changes_tenant_at on public.data_changes(tenant_id, at desc);
create index if not exists data_changes_row on public.data_changes(tenant_id, table_name, row_id);
create index if not exists data_changes_actor on public.data_changes(tenant_id, actor_id, at desc);
alter table public.data_changes enable row level security;
drop policy if exists data_changes_admin on public.data_changes;
create policy data_changes_admin on public.data_changes for select using (tenant_id = public.my_tenant_id() and public.is_school_admin());
revoke insert, update, delete on public.data_changes from anon, authenticated;

create or replace function public.log_data_change()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  o jsonb := case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end;
  n jsonb := case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end;
  src jsonb := coalesce(n, o);
  tid uuid := nullif(src ->> 'tenant_id', '')::uuid;
  diff jsonb := '{}'::jsonb;
  k text;
  claims jsonb := coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb;
  hdr jsonb := coalesce(nullif(current_setting('request.headers', true), ''), '{}')::jsonb;
  who uuid := auth.uid();
  label text := 'user';
  secret text[] := array['token','portal_token','pay_token','access_token','unsubscribe_token','update_token','card_code','code_hash',
    'secret','lead_webhook_key','offer_signature','p256dh','auth','endpoint','device_hash','referral_code'];
  noise text[] := array['updated_at','last_seen_at','last_message_at','staff_unread','guardian_unread','last_contact_at'];
  v jsonb;
begin
  if tid is null or tid::text = coalesce(current_setting('app.purging_tenant', true), '') then return null; end if;
  if not exists (select 1 from public.tenants where id = tid) then return null; end if;   -- the school itself is being deleted
  if who is null then
    -- The server acts for a person: it says who in a header, trusted only from the service role.
    if claims ->> 'role' = 'service_role' and coalesce(hdr ->> 'x-actor', '') <> '' then
      label := left(hdr ->> 'x-actor', 80);
      if label ~ '^user:[0-9a-f-]{36}$' then who := substr(label, 6)::uuid; label := 'user'; end if;
    else
      label := 'system';
    end if;
  end if;
  if tg_op = 'UPDATE' then
    for k in select jsonb_object_keys(n) loop
      if k = any(noise) or (n -> k) is not distinct from (o -> k) then continue; end if;
      diff := diff || jsonb_build_object(k, jsonb_build_array(o -> k, n -> k));
    end loop;
    if diff = '{}'::jsonb then return null; end if;
  else
    diff := src;
  end if;
  for k in select jsonb_object_keys(diff) loop
    if k = any(secret) then diff := jsonb_set(diff, array[k], '"[hidden]"'::jsonb);
    else
      v := diff -> k;
      if length(v::text) > 600 then diff := jsonb_set(diff, array[k], to_jsonb(left(v::text, 600) || '…')); end if;
    end if;
  end loop;
  insert into public.data_changes (tenant_id, table_name, row_id, op, actor_id, actor, changes)
    values (tid, tg_table_name, src ->> 'id', lower(tg_op), who, label, diff);
  return null;
end $$;

-- Every table holding a school's data, except high-volume logs and machine state.
do $$
declare t text;
begin
  for t in
    select c.table_name from information_schema.columns c
    join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name
    where c.table_schema = 'public' and c.column_name = 'tenant_id' and x.table_type = 'BASE TABLE'
      and c.table_name not in ('data_changes','audit_logs','platform_audit_logs','message_outbox','exam_events','exam_attempts','practice_sessions',
        'browser_events','environment_events','screen_snapshots','student_presence','session_participants','raise_hands','rtc_rooms','rtc_peers','rtc_signals',
        'transport_live','push_subscriptions','doc_counters','lead_sequence_runs','access_grants','phone_login_codes','quiz_attempts','quiz_answers',
        'activity_responses','game_sessions','game_players','leaderboard_entries','conversation_messages','pickup_attempts','device_enrollments','devices',
        'teacher_commands','survey_invites','tenants')
  loop
    execute format('drop trigger if exists zz_log_data_change on public.%I', t);
    execute format('create trigger zz_log_data_change after insert or update or delete on public.%I for each row execute function public.log_data_change()', t);
  end loop;
end $$;

-- Deleting a school skips the change history and removes it with everything else.
create or replace function public.platform_delete_tenant(p_tenant uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  r record;
  v_users uuid[];
  v_pass int := 0;
  v_blocked text[];
begin
  if not exists (select 1 from public.tenants where id = p_tenant) then raise exception 'school not found'; end if;
  perform set_config('app.purging_tenant', p_tenant::text, true);
  select coalesce(array_agg(id), '{}') into v_users from public.users where tenant_id = p_tenant;
  loop
    v_pass := v_pass + 1;
    v_blocked := '{}';
    for r in
      select c.table_name
      from information_schema.columns c
      join information_schema.tables t on t.table_schema = c.table_schema and t.table_name = c.table_name
      where c.table_schema = 'public' and c.column_name = 'tenant_id' and t.table_type = 'BASE TABLE'
        and c.table_name not in ('tenants', 'platform_audit_logs')   -- the platform keeps its history
      order by c.table_name
    loop
      begin
        execute format('delete from public.%I where tenant_id = $1', r.table_name) using p_tenant;
      exception when foreign_key_violation then
        v_blocked := v_blocked || r.table_name::text;
      end;
    end loop;
    exit when cardinality(v_blocked) = 0 or v_pass >= 15;
  end loop;
  if cardinality(v_blocked) > 0 then
    raise exception 'could not remove data from: %', array_to_string(v_blocked, ', ');
  end if;
  delete from public.tenants where id = p_tenant;
  perform set_config('app.purging_tenant', '', true);
  return jsonb_build_object('users', to_jsonb(v_users), 'passes', v_pass);
end $$;
revoke all on function public.platform_delete_tenant(uuid) from public, anon, authenticated;
grant execute on function public.platform_delete_tenant(uuid) to service_role;

grant all on public.school_sections, public.staff_devices, public.access_grants, public.phone_login_codes, public.consent_purposes,
  public.consent_records, public.data_changes to service_role;

-- ===== 20260101003300_sis.sql =====
-- =========================================================================
-- EduClass Fusion: student information system (phase 5).
--  * students: admission and leaving details (date admitted, previous
--    school, date left, how and why, destination school).
--  * student_movements: the enrolment history: admitted, promoted,
--    repeated, moved class, transferred in or out, withdrawn, graduated,
--    suspended, reinstated.
--  * student_documents: birth certificates, reports, medical and other
--    papers, stored privately; some may be shared with the family.
--  * sen_profiles, ieps, iep_targets, iep_reviews: special educational
--    needs, access arrangements (extra exam time and so on) and individual
--    education plans with targets and reviews.
--  * student_achievements and portfolio_items: awards, positions and
--    pieces of work.
--  * certificates: numbered, signed certificates (awards, transfer
--    certificates, testimonials) with a public verification link.
-- Apply AFTER 20260101003200. Idempotent.
-- =========================================================================

alter table public.students add column if not exists admitted_on date;
alter table public.students add column if not exists previous_school text;
alter table public.students add column if not exists left_on date;
alter table public.students add column if not exists leaving_kind text;
alter table public.students add column if not exists leaving_reason text;
alter table public.students add column if not exists destination_school text;
update public.students set admitted_on = created_at::date where admitted_on is null;
alter table public.students drop constraint if exists students_leaving_kind_check;
alter table public.students add constraint students_leaving_kind_check check (leaving_kind is null or leaving_kind in ('transferred','withdrawn','graduated','expelled','deceased','other'));

-- Who coordinates special educational needs (SENCO): admins, counsellors and named coordinators.
create or replace function public.is_sen_staff()
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_role(array['school_admin','principal','platform_admin','counsellor']);
$$;
grant execute on function public.is_sen_staff() to authenticated;

-- ---------- enrolment history ----------
create table if not exists public.student_movements (
  id                  uuid primary key default gen_random_uuid(),
  tenant_id           uuid not null references public.tenants(id) on delete cascade,
  student_id          uuid not null references public.students(id) on delete cascade,
  kind                text not null check (kind in ('admitted','promoted','repeated','class_change','transferred_in','transferred_out','withdrawn','graduated','suspended','reinstated','expelled','other')),
  effective_on        date not null default current_date,
  from_class          text,
  to_class            text,
  session_name        text,
  school              text,                 -- previous school (transferred in) or destination (transferred out)
  reason              text,
  notes               text,
  recorded_by         uuid references public.users(id) on delete set null,
  created_at          timestamptz not null default now()
);
create index if not exists student_movements_student on public.student_movements(student_id, effective_on desc);
create index if not exists student_movements_kind on public.student_movements(tenant_id, kind, effective_on desc);

-- ---------- documents ----------
create table if not exists public.student_documents (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null references public.tenants(id) on delete cascade,
  student_id         uuid not null references public.students(id) on delete cascade,
  kind               text not null default 'other' check (kind in ('birth_certificate','passport_photo','previous_report','transfer_letter','medical','immunisation','id_document','court_order','sen_report','certificate','agreement','other')),
  name               text not null,
  path               text not null,
  size               int,
  content_type       text,
  notes              text,
  shared_with_family boolean not null default false,
  confidential       boolean not null default false,   -- court orders, SEN and medical reports: admins, counsellors and nurse only
  uploaded_by        uuid references public.users(id) on delete set null,
  created_at         timestamptz not null default now()
);
create index if not exists student_documents_student on public.student_documents(student_id, created_at desc);
insert into storage.buckets (id, name, public) values ('student-documents', 'student-documents', false) on conflict (id) do nothing;

-- ---------- SEN and IEPs ----------
create table if not exists public.sen_profiles (
  student_id          uuid primary key references public.students(id) on delete cascade,
  tenant_id           uuid not null references public.tenants(id) on delete cascade,
  status              text not null default 'monitoring' check (status in ('monitoring','sen_support','ehcp','closed')),
  areas               text[] not null default '{}',   -- cognition_learning, communication_interaction, semh, sensory_physical
  needs               text[] not null default '{}',   -- dyslexia, adhd, autism, hearing, visual …
  summary             text,
  strengths           text,
  strategies          text,                            -- what helps in class: shared with the child's teachers
  extra_time_pct      int not null default 0 check (extra_time_pct between 0 and 100),
  arrangements        text[] not null default '{}',   -- reader, scribe, rest_breaks, separate_room, enlarged_print, assistive_tech, prompter
  agencies            text,                            -- outside professionals involved
  coordinator_id      uuid references public.users(id) on delete set null,
  share_with_teachers boolean not null default true,
  updated_by          uuid references public.users(id) on delete set null,
  updated_at          timestamptz not null default now(),
  created_at          timestamptz not null default now()
);

create table if not exists public.ieps (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  student_id       uuid not null references public.students(id) on delete cascade,
  title            text not null default 'Individual education plan',
  starts_on        date not null default current_date,
  review_on        date,
  status           text not null default 'draft' check (status in ('draft','active','closed')),
  student_voice    text,                       -- what the child says helps
  parent_views     text,
  parent_agreed_at timestamptz,
  created_by       uuid references public.users(id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index if not exists ieps_student on public.ieps(student_id, starts_on desc);
create index if not exists ieps_review on public.ieps(tenant_id, review_on) where status = 'active';

create table if not exists public.iep_targets (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null references public.tenants(id) on delete cascade,
  iep_id            uuid not null references public.ieps(id) on delete cascade,
  area              text,
  target            text not null check (length(target) between 2 and 1000),
  strategies        text,
  success_criteria  text,
  owner_id          uuid references public.users(id) on delete set null,
  progress          text not null default 'not_started' check (progress in ('not_started','emerging','developing','secure','achieved')),
  notes             text,
  position          int not null default 0,
  updated_at        timestamptz not null default now()
);

create table if not exists public.iep_reviews (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  iep_id        uuid not null references public.ieps(id) on delete cascade,
  reviewed_on   date not null default current_date,
  summary       text not null,
  attendees     text,
  next_review   date,
  created_by    uuid references public.users(id) on delete set null,
  created_at    timestamptz not null default now()
);

-- ---------- achievements and portfolio ----------
create table if not exists public.student_achievements (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null references public.tenants(id) on delete cascade,
  student_id         uuid not null references public.students(id) on delete cascade,
  kind               text not null default 'academic' check (kind in ('academic','sports','arts','leadership','service','competition','attendance','character','other')),
  title              text not null check (length(title) between 2 and 160),
  description        text,
  level              text not null default 'school' check (level in ('class','school','local','state','national','international')),
  award              text,                  -- e.g. 1st place, Gold, Head Girl
  achieved_on        date not null default current_date,
  shared_with_family boolean not null default true,
  recorded_by        uuid references public.users(id) on delete set null,
  created_at         timestamptz not null default now()
);
create index if not exists student_achievements_student on public.student_achievements(student_id, achieved_on desc);

create table if not exists public.portfolio_items (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  student_id   uuid not null references public.students(id) on delete cascade,
  title        text not null check (length(title) between 2 and 160),
  description  text,
  kind         text not null default 'work' check (kind in ('work','project','artwork','writing','photo','video','audio','other')),
  subject_id   uuid references public.subjects(id) on delete set null,
  path         text,                         -- file in student-documents storage
  content_type text,
  link_url     text,                         -- or a link (video, website)
  status       text not null default 'approved' check (status in ('submitted','approved','returned')),
  shared_with_family boolean not null default true,
  added_by     uuid references public.users(id) on delete set null,
  reviewed_by  uuid references public.users(id) on delete set null,
  feedback     text,
  created_at   timestamptz not null default now()
);
create index if not exists portfolio_items_student on public.portfolio_items(student_id, created_at desc);

-- ---------- certificates ----------
create table if not exists public.certificates (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  student_id      uuid not null references public.students(id) on delete cascade,
  kind            text not null check (kind in ('award','transfer','testimonial','completion','attendance','participation','custom')),
  serial_no       text not null,
  title           text not null,
  body            text not null default '',
  data            jsonb not null default '{}'::jsonb,   -- the facts printed (snapshotted when issued)
  achievement_id  uuid references public.student_achievements(id) on delete set null,
  issued_on       date not null default current_date,
  signer_name     text,
  signer_title    text,
  status          text not null default 'issued' check (status in ('issued','revoked')),
  revoked_reason  text,
  revoked_at      timestamptz,
  signature       text,
  verify_token    text not null default encode(gen_random_bytes(16), 'hex'),
  shared_with_family boolean not null default true,
  issued_by       uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  unique (tenant_id, serial_no),
  unique (verify_token)
);
create index if not exists certificates_student on public.certificates(student_id, issued_on desc);

-- ---------- RLS ----------
alter table public.student_movements enable row level security;
drop policy if exists student_movements_read on public.student_movements;
create policy student_movements_read on public.student_movements for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists student_movements_admin on public.student_movements;
create policy student_movements_admin on public.student_movements for all using (tenant_id = public.my_tenant_id() and public.is_school_admin())
  with check (tenant_id = public.my_tenant_id() and public.is_school_admin());

-- Documents: staff see ordinary ones; confidential ones only admins, counsellors and the nurse. Families via the server.
alter table public.student_documents enable row level security;
drop policy if exists student_documents_read on public.student_documents;
create policy student_documents_read on public.student_documents for select using (
  tenant_id = public.my_tenant_id() and public.is_staff()
  and (not confidential or public.has_role(array['school_admin','principal','platform_admin','counsellor','nurse'])));
drop policy if exists student_documents_write on public.student_documents;
create policy student_documents_write on public.student_documents for all using (
  tenant_id = public.my_tenant_id() and public.has_role(array['school_admin','principal','platform_admin','it_admin','counsellor','nurse']))
  with check (tenant_id = public.my_tenant_id() and public.has_role(array['school_admin','principal','platform_admin','it_admin','counsellor','nurse']));

-- SEN: the SEN team manages; the named coordinator too; the child's teachers read the profile when it is shared with them.
alter table public.sen_profiles enable row level security;
drop policy if exists sen_profiles_team on public.sen_profiles;
create policy sen_profiles_team on public.sen_profiles for all using (
  tenant_id = public.my_tenant_id() and (public.is_sen_staff() or coordinator_id = auth.uid()))
  with check (tenant_id = public.my_tenant_id() and (public.is_sen_staff() or coordinator_id = auth.uid()));
drop policy if exists sen_profiles_teachers on public.sen_profiles;
create policy sen_profiles_teachers on public.sen_profiles for select using (
  tenant_id = public.my_tenant_id() and share_with_teachers and public.teaches_student(student_id));

create or replace function public.can_manage_sen(p_student uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_sen_staff() or exists (select 1 from public.sen_profiles where student_id = p_student and coordinator_id = auth.uid());
$$;
create or replace function public.can_read_sen(p_student uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.can_manage_sen(p_student)
    or (public.teaches_student(p_student) and exists (select 1 from public.sen_profiles where student_id = p_student and share_with_teachers));
$$;
grant execute on function public.can_manage_sen(uuid), public.can_read_sen(uuid) to authenticated;

alter table public.ieps enable row level security;
drop policy if exists ieps_manage on public.ieps;
create policy ieps_manage on public.ieps for all using (tenant_id = public.my_tenant_id() and public.can_manage_sen(student_id))
  with check (tenant_id = public.my_tenant_id() and public.can_manage_sen(student_id));
drop policy if exists ieps_read on public.ieps;
create policy ieps_read on public.ieps for select using (tenant_id = public.my_tenant_id() and status <> 'draft' and public.can_read_sen(student_id));

do $$
declare t text;
begin
  foreach t in array array['iep_targets','iep_reviews'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_manage', t);
    execute format('create policy %I on public.%I for all using (tenant_id = public.my_tenant_id() and exists (select 1 from public.ieps i where i.id = %I.iep_id and public.can_manage_sen(i.student_id))) with check (tenant_id = public.my_tenant_id() and exists (select 1 from public.ieps i where i.id = %I.iep_id and public.can_manage_sen(i.student_id)))', t || '_manage', t, t, t);
    execute format('drop policy if exists %I on public.%I', t || '_read', t);
    execute format('create policy %I on public.%I for select using (tenant_id = public.my_tenant_id() and exists (select 1 from public.ieps i where i.id = %I.iep_id and i.status <> %L and public.can_read_sen(i.student_id)))', t || '_read', t, t, 'draft');
  end loop;
end $$;
-- Teachers who own a target record progress on it.
drop policy if exists iep_targets_owner on public.iep_targets;
create policy iep_targets_owner on public.iep_targets for update using (tenant_id = public.my_tenant_id() and owner_id = auth.uid())
  with check (tenant_id = public.my_tenant_id() and owner_id = auth.uid());

-- Achievements: any staff member records; everyone on staff reads; families through the server.
alter table public.student_achievements enable row level security;
drop policy if exists student_achievements_read on public.student_achievements;
create policy student_achievements_read on public.student_achievements for select using (tenant_id = public.my_tenant_id()
  and (public.is_staff() or (shared_with_family and (public.is_guardian_of(student_id) or public.is_student_self(student_id)))));
drop policy if exists student_achievements_write on public.student_achievements;
create policy student_achievements_write on public.student_achievements for insert with check (tenant_id = public.my_tenant_id() and public.is_staff() and recorded_by = auth.uid());
drop policy if exists student_achievements_edit on public.student_achievements;
create policy student_achievements_edit on public.student_achievements for update using (tenant_id = public.my_tenant_id() and (recorded_by = auth.uid() or public.is_school_admin()))
  with check (tenant_id = public.my_tenant_id());
drop policy if exists student_achievements_delete on public.student_achievements;
create policy student_achievements_delete on public.student_achievements for delete using (tenant_id = public.my_tenant_id() and (recorded_by = auth.uid() or public.is_school_admin()));

-- Portfolio: staff manage; students see and add their own work through the server (it waits for a teacher).
alter table public.portfolio_items enable row level security;
drop policy if exists portfolio_staff on public.portfolio_items;
create policy portfolio_staff on public.portfolio_items for all using (tenant_id = public.my_tenant_id() and public.is_staff())
  with check (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists portfolio_own on public.portfolio_items;
create policy portfolio_own on public.portfolio_items for select using (tenant_id = public.my_tenant_id()
  and (public.is_student_self(student_id) or (status = 'approved' and shared_with_family and public.is_guardian_of(student_id))));

-- Certificates are numbered and signed by the server; staff read them, admins revoke through the server.
alter table public.certificates enable row level security;
drop policy if exists certificates_read on public.certificates;
create policy certificates_read on public.certificates for select using (tenant_id = public.my_tenant_id()
  and (public.is_staff() or (shared_with_family and status = 'issued' and (public.is_guardian_of(student_id) or public.is_student_self(student_id)))));

grant all on public.student_movements, public.student_documents, public.sen_profiles, public.ieps, public.iep_targets, public.iep_reviews,
  public.student_achievements, public.portfolio_items, public.certificates to service_role;

-- Every new student starts their history with "admitted", however they were created.
alter table public.students alter column admitted_on set default current_date;
create or replace function public.student_admitted()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.student_movements (tenant_id, student_id, kind, effective_on, to_class, school, recorded_by)
  values (new.tenant_id, new.id, 'admitted', coalesce(new.admitted_on, current_date),
          (select name from public.class_groups where id = new.class_group_id), new.previous_school, auth.uid());
  return new;
end $$;
drop trigger if exists students_admitted on public.students;
create trigger students_admitted after insert on public.students for each row execute function public.student_admitted();
-- Students who were here before the history began.
insert into public.student_movements (tenant_id, student_id, kind, effective_on, to_class, notes)
select s.tenant_id, s.id, 'admitted', coalesce(s.admitted_on, s.created_at::date), c.name, 'Recorded when the enrolment history began'
from public.students s left join public.class_groups c on c.id = s.class_group_id
where not exists (select 1 from public.student_movements m where m.student_id = s.id);

-- ===== 20260101003400_lms_teaching.sql =====
-- =========================================================================
-- EduClass Fusion: learning management, part 1 (phase 6a).
--  * homework: late penalties, resubmission, file uploads, differentiated
--    groups, curriculum objectives; earlier attempts kept; annotations and
--    voice/video feedback on submissions; originality checks.
--  * learning_groups: support / core / extension groups inside a class.
--  * forums, forum_threads, forum_posts, forum_reports: class and school
--    discussion, moderated by staff.
--  * badges, student_badges, learning_activity: badges, points and streaks.
--  * curriculum_objectives, schemes_of_work, scheme_weeks: schemes of work
--    mapped to curriculum objectives, with approval and coverage.
-- Apply AFTER 20260101003300. Idempotent.
-- =========================================================================

-- ---------- differentiation ----------
create table if not exists public.learning_groups (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  class_group_id  uuid not null references public.class_groups(id) on delete cascade,
  name            text not null check (length(name) between 1 and 60),
  kind            text not null default 'custom' check (kind in ('support','core','extension','custom')),
  created_by      uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  unique (class_group_id, name)
);
create table if not exists public.learning_group_members (
  group_id    uuid not null references public.learning_groups(id) on delete cascade,
  student_id  uuid not null references public.students(id) on delete cascade,
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  primary key (group_id, student_id)
);

-- ---------- homework ----------
alter table public.homework add column if not exists late_penalty_pct numeric not null default 0;          -- % of the mark lost per day late
alter table public.homework add column if not exists late_penalty_max numeric not null default 100;       -- never lose more than this
alter table public.homework add column if not exists allow_resubmit boolean not null default false;
alter table public.homework add column if not exists max_attempts int not null default 1;
alter table public.homework add column if not exists accept_files boolean not null default true;
alter table public.homework add column if not exists group_ids uuid[] not null default '{}';            -- empty = the whole class
alter table public.homework add column if not exists objective_ids uuid[] not null default '{}';
alter table public.homework add column if not exists check_originality boolean not null default true;
do $$ begin
  alter table public.homework drop constraint if exists homework_late_rules_check;
  alter table public.homework add constraint homework_late_rules_check check (late_penalty_pct between 0 and 100 and late_penalty_max between 0 and 100 and max_attempts between 1 and 10);
end $$;

alter table public.homework_submissions add column if not exists attempt int not null default 1;
alter table public.homework_submissions add column if not exists files jsonb not null default '[]'::jsonb;         -- [{ path, name, type, size }]
alter table public.homework_submissions add column if not exists raw_score numeric;                              -- before any late penalty
alter table public.homework_submissions add column if not exists penalty_pct numeric not null default 0;
alter table public.homework_submissions add column if not exists status text not null default 'submitted';
alter table public.homework_submissions add column if not exists returned_note text;
alter table public.homework_submissions add column if not exists feedback_media jsonb not null default '[]'::jsonb; -- [{ path, type, seconds, created_at }]
alter table public.homework_submissions add column if not exists originality jsonb;                                -- { similarity, matches, style, checked_at }
do $$ begin
  alter table public.homework_submissions drop constraint if exists homework_submissions_status_check;
  alter table public.homework_submissions add constraint homework_submissions_status_check check (status in ('submitted','returned','marked'));
end $$;

-- Earlier attempts, kept when a student resubmits.
create table if not exists public.homework_submission_versions (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  submission_id uuid not null references public.homework_submissions(id) on delete cascade,
  attempt       int not null,
  body          text,
  files         jsonb not null default '[]'::jsonb,
  submitted_at  timestamptz not null,
  late          boolean not null default false,
  score         numeric,
  feedback      text,
  created_at    timestamptz not null default now()
);

create table if not exists public.submission_annotations (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references public.tenants(id) on delete cascade,
  submission_id  uuid not null references public.homework_submissions(id) on delete cascade,
  author_id      uuid references public.users(id) on delete set null,
  kind           text not null check (kind in ('text','pin')),
  start_offset   int,            -- text: character range in the answer
  end_offset     int,
  quote          text,
  file_index     int,            -- pin: which uploaded image, and where (percent of width / height)
  x              numeric check (x between 0 and 100),
  y              numeric check (y between 0 and 100),
  comment        text not null check (length(comment) between 1 and 2000),
  created_at     timestamptz not null default now()
);
create index if not exists submission_annotations_sub on public.submission_annotations(submission_id);
insert into storage.buckets (id, name, public) values ('homework', 'homework', false) on conflict (id) do nothing;

-- ---------- forums ----------
create table if not exists public.forums (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  kind            text not null default 'class' check (kind in ('class','school','staff')),
  class_group_id  uuid references public.class_groups(id) on delete cascade,
  subject_id      uuid references public.subjects(id) on delete set null,
  title           text not null check (length(title) between 2 and 120),
  description     text,
  locked          boolean not null default false,
  created_by      uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  check (kind <> 'class' or class_group_id is not null)
);
create table if not exists public.forum_threads (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references public.tenants(id) on delete cascade,
  forum_id       uuid not null references public.forums(id) on delete cascade,
  author_id      uuid references public.users(id) on delete set null,
  title          text not null check (length(title) between 2 and 160),
  body           text not null check (length(body) between 1 and 20000),
  pinned         boolean not null default false,
  locked         boolean not null default false,
  hidden         boolean not null default false,
  post_count     int not null default 0,
  last_post_at   timestamptz not null default now(),
  created_at     timestamptz not null default now()
);
create index if not exists forum_threads_forum on public.forum_threads(forum_id, pinned desc, last_post_at desc);
create table if not exists public.forum_posts (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references public.tenants(id) on delete cascade,
  thread_id      uuid not null references public.forum_threads(id) on delete cascade,
  author_id      uuid references public.users(id) on delete set null,
  body           text not null check (length(body) between 1 and 20000),
  hidden         boolean not null default false,
  hidden_by      uuid references public.users(id) on delete set null,
  hidden_reason  text,
  edited_at      timestamptz,
  created_at     timestamptz not null default now()
);
create index if not exists forum_posts_thread on public.forum_posts(thread_id, created_at);
create table if not exists public.forum_reports (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  post_id      uuid references public.forum_posts(id) on delete cascade,
  thread_id    uuid references public.forum_threads(id) on delete cascade,
  reporter_id  uuid references public.users(id) on delete set null,
  reason       text not null check (length(reason) between 2 and 500),
  resolved_at  timestamptz,
  resolved_by  uuid references public.users(id) on delete set null,
  created_at   timestamptz not null default now()
);

-- Who may read and write in a forum: staff everywhere except they do not need a class link;
-- students only in school forums and their own class's forums; nobody else.
create or replace function public.can_use_forum(p_forum uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.forums f
    where f.id = p_forum and f.tenant_id = public.my_tenant_id()
      and (
        (public.is_staff())
        or (f.kind = 'school' and public.has_role(array['student']))
        or (f.kind = 'class' and exists (select 1 from public.students s where s.user_id = auth.uid() and s.status = 'active' and s.class_group_id = f.class_group_id))
      )
      and (f.kind <> 'staff' or public.is_staff())
  );
$$;
grant execute on function public.can_use_forum(uuid) to authenticated;

-- Locked forums and threads take no new posts; counts and last activity follow the posts.
create or replace function public.forum_post_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare t public.forum_threads; f public.forums;
begin
  select * into t from public.forum_threads where id = new.thread_id;
  select * into f from public.forums where id = t.forum_id;
  if tg_op = 'INSERT' then
    if (t.locked or f.locked) and not public.is_staff() then raise exception 'this discussion is closed'; end if;
    update public.forum_threads set post_count = post_count + 1, last_post_at = now() where id = t.id;
  end if;
  return new;
end $$;
drop trigger if exists forum_posts_guard on public.forum_posts;
create trigger forum_posts_guard before insert on public.forum_posts for each row execute function public.forum_post_guard();

-- ---------- gamification ----------
create table if not exists public.badges (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  name         text not null check (length(name) between 2 and 60),
  description  text,
  emoji        text not null default '🏅',
  rule         jsonb,            -- automatic: { type: streak|points|homework|practice|forum, threshold }; null = given by staff
  active       boolean not null default true,
  created_at   timestamptz not null default now(),
  unique (tenant_id, name)
);
create table if not exists public.student_badges (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  badge_id    uuid not null references public.badges(id) on delete cascade,
  student_id  uuid not null references public.students(id) on delete cascade,
  awarded_by  uuid references public.users(id) on delete set null,
  reason      text,
  awarded_at  timestamptz not null default now(),
  unique (badge_id, student_id)
);
create table if not exists public.learning_activity (
  id          bigint generated always as identity primary key,
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  student_id  uuid not null references public.students(id) on delete cascade,
  kind        text not null check (kind in ('homework','practice','content','path_step','forum','lesson','exam','tutor')),
  points      int not null default 0 check (points between 0 and 1000),
  ref_id      uuid,
