-- ===== 20260101004000_accounts.sql =====
-- =====================================================================
--  Phase 9b: budgets, petty cash and the general ledger.
--
--  * Budgets per period with income and expense lines; a second person approves.
--  * Petty cash floats with a custodian, top-ups, spends (each one an expense,
--    with an optional receipt), returns, cash counts and adjustments.
--  * A chart of accounts per school, mappings (fee items, expense categories,
--    payment methods to accounts) and manual journals that must balance.
--    Everything else in the ledger (fees billed and received, expenses, payroll,
--    wallet, petty cash) is derived from the records the school already keeps.
--  * Closing the books up to a date: expenses, petty cash and journals dated
--    on or before it can no longer be added, changed or removed.
-- =====================================================================

alter table public.expenses add column if not exists receipt_path text;
alter table public.tenant_settings add column if not exists books_closed_until date;
insert into storage.buckets (id, name, public) values ('expense-receipts', 'expense-receipts', false) on conflict (id) do nothing;

-- ---------- Closed periods ----------
-- Attach with the name of the row's date column. Server jobs (no signed-in user) are not blocked.
create or replace function public.books_closed_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_until date; v_tenant uuid; v_col text := tg_argv[0]; v_d date;
begin
  if auth.uid() is null then return case when tg_op = 'DELETE' then old else new end; end if;
  if tg_op = 'DELETE' then v_tenant := old.tenant_id; else v_tenant := new.tenant_id; end if;
  select books_closed_until into v_until from public.tenant_settings where tenant_id = v_tenant;
  if v_until is null then return case when tg_op = 'DELETE' then old else new end; end if;
  if tg_op <> 'INSERT' then
    v_d := (to_jsonb(old) ->> v_col)::date;
    if v_d <= v_until then raise exception 'the books are closed up to %; record a correction in an open period', to_char(v_until, 'DD Mon YYYY'); end if;
  end if;
  if tg_op <> 'DELETE' then
    v_d := (to_jsonb(new) ->> v_col)::date;
    if v_d <= v_until then raise exception 'the books are closed up to %; use a later date', to_char(v_until, 'DD Mon YYYY'); end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;

drop trigger if exists expenses_books_closed on public.expenses;
create trigger expenses_books_closed before insert or update or delete on public.expenses
  for each row execute function public.books_closed_guard('spent_on');

-- ---------- Budgets ----------
create table if not exists public.budgets (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  name         text not null,
  starts_on    date not null,
  ends_on      date not null,
  status       text not null default 'draft' check (status in ('draft','approved')),
  notes        text,
  created_by   uuid references public.users(id) on delete set null,
  approved_by  uuid references public.users(id) on delete set null,
  approved_at  timestamptz,
  created_at   timestamptz not null default now(),
  check (ends_on >= starts_on),
  unique (tenant_id, name)
);
create table if not exists public.budget_lines (
  id         uuid primary key default gen_random_uuid(),
  tenant_id  uuid not null references public.tenants(id) on delete cascade,
  budget_id  uuid not null references public.budgets(id) on delete cascade,
  kind       text not null check (kind in ('income','expense')),
  category   text not null check (length(trim(category)) between 1 and 80),
  amount     numeric(14,2) not null check (amount >= 0),
  note       text,
  unique (budget_id, kind, category)
);

-- Approval by a head or admin who did not prepare it; an approved budget is reopened before it changes.
create or replace function public.budget_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return case when tg_op = 'DELETE' then old else new end; end if;
  if tg_op = 'INSERT' then
    new.created_by := auth.uid(); new.status := 'draft'; new.approved_by := null; new.approved_at := null;
    return new;
  end if;
  if tg_op = 'DELETE' then
    if old.status = 'approved' then raise exception 'reopen the budget before deleting it'; end if;
    return old;
  end if;
  if old.status = 'approved' and new.status = 'approved' then raise exception 'reopen the budget to change it'; end if;
  if new.status = 'approved' and old.status = 'draft' then
    if not public.has_role(array['school_admin','principal','platform_admin']) then raise exception 'only the principal or a school admin can approve a budget'; end if;
    if old.created_by = auth.uid() then raise exception 'a budget must be approved by someone other than the person who prepared it'; end if;
    new.approved_by := auth.uid(); new.approved_at := now();
  elsif new.status = 'draft' then
    if old.status = 'approved' and not public.has_role(array['school_admin','principal','platform_admin']) then raise exception 'only the principal or a school admin can reopen an approved budget'; end if;
    new.approved_by := null; new.approved_at := null;
  end if;
  new.created_by := old.created_by;
  return new;
end $$;
drop trigger if exists budget_guard on public.budgets;
create trigger budget_guard before insert or update or delete on public.budgets for each row execute function public.budget_guard();

create or replace function public.budget_line_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_budget uuid; v_status text; v_tenant uuid;
begin
  if auth.uid() is null then return case when tg_op = 'DELETE' then old else new end; end if;
  if tg_op = 'DELETE' then v_budget := old.budget_id; else v_budget := new.budget_id; end if;
  select status, tenant_id into v_status, v_tenant from public.budgets where id = v_budget;
  if v_status = 'approved' then raise exception 'reopen the budget to change it'; end if;
  if tg_op <> 'DELETE' and v_tenant is distinct from new.tenant_id then raise exception 'budget not found'; end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;
drop trigger if exists budget_line_guard on public.budget_lines;
create trigger budget_line_guard before insert or update or delete on public.budget_lines for each row execute function public.budget_line_guard();

-- ---------- Petty cash ----------
create table if not exists public.petty_cash_floats (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  name          text not null check (length(trim(name)) between 1 and 80),
  custodian_id  uuid references public.users(id) on delete set null,
  imprest       numeric(14,2) not null default 0 check (imprest >= 0),   -- the amount it is topped back up to
  balance       numeric(14,2) not null default 0,                         -- kept by the trigger below
  active        boolean not null default true,
  created_at    timestamptz not null default now(),
  unique (tenant_id, name)
);
create table if not exists public.petty_cash_moves (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  float_id     uuid not null references public.petty_cash_floats(id) on delete cascade,
  kind         text not null check (kind in ('topup','spend','return','adjust')),
  amount       numeric(14,2) not null check (amount <> 0 and (kind = 'adjust' or amount > 0)),   -- adjust: + over, - short
  on_date      date not null default current_date,
  note         text,
  expense_id   uuid references public.expenses(id) on delete cascade,
  recorded_by  uuid references public.users(id) on delete set null,
  created_at   timestamptz not null default now(),
  check ((kind = 'spend') = (expense_id is not null))
);
create unique index if not exists petty_cash_moves_expense on public.petty_cash_moves(expense_id) where expense_id is not null;
create index if not exists petty_cash_moves_float on public.petty_cash_moves(float_id, on_date desc);
create table if not exists public.petty_cash_counts (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  float_id    uuid not null references public.petty_cash_floats(id) on delete cascade,
  counted     numeric(14,2) not null check (counted >= 0),
  expected    numeric(14,2) not null default 0,     -- the float's balance when counted
  note        text,
  counted_by  uuid references public.users(id) on delete set null,
  counted_at  timestamptz not null default now()
);

create or replace function public.petty_cash_rebalance() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_float uuid; v_bal numeric;
begin
  if tg_op = 'DELETE' then v_float := old.float_id; else v_float := new.float_id; end if;
  select coalesce(sum(case when kind in ('topup','adjust') then amount else -amount end), 0) into v_bal
    from public.petty_cash_moves where float_id = v_float;
  update public.petty_cash_floats set balance = v_bal where id = v_float;
  if tg_op = 'INSERT' and v_bal < 0 then
    raise exception 'not enough in the petty cash float: it would be % short', to_char(-v_bal, 'FM999,999,999,990.00');
  end if;
  return null;
end $$;
drop trigger if exists petty_cash_rebalance on public.petty_cash_moves;
create trigger petty_cash_rebalance after insert or update or delete on public.petty_cash_moves
  for each row execute function public.petty_cash_rebalance();

-- Nobody types a balance: it only ever comes from the records (the rebalance trigger runs one level down).
create or replace function public.petty_cash_float_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or pg_trigger_depth() > 1 then return new; end if;
  if tg_op = 'INSERT' then new.balance := 0; else new.balance := old.balance; end if;
  return new;
end $$;
drop trigger if exists petty_cash_float_guard on public.petty_cash_floats;
create trigger petty_cash_float_guard before insert or update on public.petty_cash_floats for each row execute function public.petty_cash_float_guard();

create or replace function public.petty_cash_move_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_active boolean; v_tenant uuid;
begin
  if auth.uid() is null then return new; end if;
  select active, tenant_id into v_active, v_tenant from public.petty_cash_floats where id = new.float_id;
  if v_tenant is distinct from new.tenant_id then raise exception 'petty cash float not found'; end if;
  if not v_active and new.kind in ('topup','spend') then raise exception 'this float is closed'; end if;
  new.recorded_by := auth.uid();
  return new;
end $$;
drop trigger if exists petty_cash_move_guard on public.petty_cash_moves;
create trigger petty_cash_move_guard before insert on public.petty_cash_moves for each row execute function public.petty_cash_move_guard();
drop trigger if exists petty_cash_books_closed on public.petty_cash_moves;
create trigger petty_cash_books_closed before insert or update or delete on public.petty_cash_moves
  for each row execute function public.books_closed_guard('on_date');

create or replace function public.petty_cash_count_before() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_bal numeric; v_tenant uuid;
begin
  select balance, tenant_id into v_bal, v_tenant from public.petty_cash_floats where id = new.float_id;
  if v_tenant is distinct from new.tenant_id then raise exception 'petty cash float not found'; end if;
  new.expected := coalesce(v_bal, 0);
  if auth.uid() is not null then new.counted_by := auth.uid(); new.counted_at := now(); end if;
  return new;
end $$;
drop trigger if exists petty_cash_count_before on public.petty_cash_counts;
create trigger petty_cash_count_before before insert on public.petty_cash_counts for each row execute function public.petty_cash_count_before();

create or replace function public.is_custodian_of(p_float uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.petty_cash_floats f where f.id = p_float and f.tenant_id = public.my_tenant_id() and f.custodian_id = auth.uid());
$$;
grant execute on function public.is_custodian_of(uuid) to authenticated;

-- A spend is an expense paid from the float, recorded by the custodian or the bursary.
create or replace function public.petty_cash_spend(p_float uuid, p_amount numeric, p_category text, p_description text,
  p_payee text default null, p_on date default null, p_receipt text default null)
returns uuid language plpgsql security definer set search_path = public as $$
declare f public.petty_cash_floats%rowtype; v_exp uuid; v_amt numeric := round(p_amount, 2);
begin
  select * into f from public.petty_cash_floats where id = p_float and tenant_id = public.my_tenant_id();
  if f.id is null then raise exception 'petty cash float not found'; end if;
  if not (public.is_finance() or f.custodian_id = auth.uid()) then raise exception 'only the custodian or the bursary can spend from this float'; end if;
  if v_amt is null or v_amt <= 0 then raise exception 'enter an amount'; end if;
  if coalesce(trim(p_category), '') = '' or coalesce(trim(p_description), '') = '' then raise exception 'say what the money was spent on'; end if;
  if p_receipt is not null and p_receipt not like f.tenant_id::text || '/%' then raise exception 'receipt not found'; end if;
  insert into public.expenses (tenant_id, category, description, amount, spent_on, payee, method, receipt_path, recorded_by)
    values (f.tenant_id, left(trim(p_category), 60), left(trim(p_description), 200), v_amt, coalesce(p_on, current_date),
            nullif(left(trim(coalesce(p_payee, '')), 120), ''), 'petty_cash', p_receipt, auth.uid())
    returning id into v_exp;
  insert into public.petty_cash_moves (tenant_id, float_id, kind, amount, on_date, note, expense_id)
    values (f.tenant_id, f.id, 'spend', v_amt, coalesce(p_on, current_date), left(trim(p_description), 200), v_exp);
  return v_exp;
end $$;
revoke all on function public.petty_cash_spend(uuid, numeric, text, text, text, date, text) from public, anon;
grant execute on function public.petty_cash_spend(uuid, numeric, text, text, text, date, text) to authenticated;

-- ---------- Chart of accounts and journals ----------
create table if not exists public.ledger_accounts (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  code        text not null check (code ~ '^[0-9A-Za-z.-]{1,20}$'),
  name        text not null check (length(trim(name)) between 1 and 120),
  type        text not null check (type in ('asset','liability','equity','income','expense')),
  system_key  text,          -- built-in accounts the ledger posts to (bank, receivables, fee_income …)
  active      boolean not null default true,
  created_at  timestamptz not null default now(),
  unique (tenant_id, code),
  unique (tenant_id, system_key)
);
create table if not exists public.ledger_mappings (
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  source      text not null check (source in ('fee_item','expense_category','payment_method')),
  key         text not null,
  account_id  uuid not null references public.ledger_accounts(id) on delete cascade,
  primary key (tenant_id, source, key)
);
create table if not exists public.journal_entries (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  entry_no    text,
  entry_date  date not null,
  memo        text not null check (length(trim(memo)) between 1 and 300),
  status      text not null default 'draft' check (status in ('draft','posted')),
  reverses    uuid references public.journal_entries(id) on delete set null,
  created_by  uuid references public.users(id) on delete set null,
  posted_by   uuid references public.users(id) on delete set null,
  posted_at   timestamptz,
  created_at  timestamptz not null default now(),
  unique (tenant_id, entry_no)
);
create index if not exists journal_entries_date on public.journal_entries(tenant_id, entry_date);
create table if not exists public.journal_lines (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  entry_id     uuid not null references public.journal_entries(id) on delete cascade,
  account_id   uuid not null references public.ledger_accounts(id),
  debit        numeric(14,2) not null default 0 check (debit >= 0),
  credit       numeric(14,2) not null default 0 check (credit >= 0),
  description  text,
  check ((debit > 0) <> (credit > 0))
);
create index if not exists journal_lines_entry on public.journal_lines(entry_id);

create or replace function public.ledger_account_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return case when tg_op = 'DELETE' then old else new end; end if;
  if tg_op = 'INSERT' then
    if new.system_key is not null then raise exception 'built-in accounts are added by the system'; end if;
    return new;
  end if;
  if tg_op = 'DELETE' then
    if old.system_key is not null then raise exception 'built-in accounts can be renamed or hidden but not deleted'; end if;
    if exists (select 1 from public.journal_lines l where l.account_id = old.id) then raise exception 'this account has journal lines; hide it instead'; end if;
    return old;
  end if;
  if old.system_key is not null and (new.type is distinct from old.type or new.system_key is distinct from old.system_key) then
    raise exception 'the type of a built-in account cannot change';
  end if;
  if old.system_key is null and new.system_key is not null then raise exception 'built-in accounts are added by the system'; end if;
  return new;
end $$;
drop trigger if exists ledger_account_guard on public.ledger_accounts;
create trigger ledger_account_guard before insert or update or delete on public.ledger_accounts for each row execute function public.ledger_account_guard();

-- Journals are drafted, then posted once debits equal credits. Posted journals never change: reverse them.
create or replace function public.journal_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_dr numeric; v_cr numeric; v_n int;
begin
  if auth.uid() is null then return case when tg_op = 'DELETE' then old else new end; end if;
  if tg_op = 'INSERT' then
    new.created_by := auth.uid(); new.status := 'draft'; new.entry_no := null; new.posted_by := null; new.posted_at := null;
    return new;
  end if;
  if old.status = 'posted' then raise exception 'posted journals cannot be changed or deleted; post a reversing journal instead'; end if;
  if tg_op = 'DELETE' then return old; end if;
  if new.status = 'posted' then
    select coalesce(sum(debit), 0), coalesce(sum(credit), 0), count(*) into v_dr, v_cr, v_n from public.journal_lines where entry_id = new.id;
    if v_n < 2 then raise exception 'a journal needs at least two lines'; end if;
    if v_dr <> v_cr then raise exception 'debits (%) and credits (%) must be equal', v_dr, v_cr; end if;
    if v_dr = 0 then raise exception 'a journal must move some money'; end if;
    new.entry_no := public.next_doc_no(new.tenant_id, 'jnl'); new.posted_by := auth.uid(); new.posted_at := now();
  end if;
  new.created_by := old.created_by;
  return new;
end $$;
drop trigger if exists journal_guard on public.journal_entries;
create trigger journal_guard before insert or update or delete on public.journal_entries for each row execute function public.journal_guard();
drop trigger if exists journal_books_closed on public.journal_entries;
create trigger journal_books_closed before insert or update or delete on public.journal_entries
  for each row execute function public.books_closed_guard('entry_date');

create or replace function public.journal_line_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_entry uuid; v_status text; v_tenant uuid;
begin
  if auth.uid() is null then return case when tg_op = 'DELETE' then old else new end; end if;
  if tg_op = 'DELETE' then v_entry := old.entry_id; else v_entry := new.entry_id; end if;
  select status, tenant_id into v_status, v_tenant from public.journal_entries where id = v_entry;
  if v_status = 'posted' then raise exception 'posted journals cannot be changed; post a reversing journal instead'; end if;
  if tg_op <> 'DELETE' then
    if v_tenant is distinct from new.tenant_id then raise exception 'journal not found'; end if;
    if not exists (select 1 from public.ledger_accounts a where a.id = new.account_id and a.tenant_id = new.tenant_id) then raise exception 'account not found'; end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;
drop trigger if exists journal_line_guard on public.journal_lines;
create trigger journal_line_guard before insert or update or delete on public.journal_lines for each row execute function public.journal_line_guard();

-- Mappings point at this school's accounts only.
create or replace function public.ledger_mapping_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from public.ledger_accounts a where a.id = new.account_id and a.tenant_id = new.tenant_id) then raise exception 'account not found'; end if;
  return new;
end $$;
drop trigger if exists ledger_mapping_guard on public.ledger_mappings;
create trigger ledger_mapping_guard before insert or update on public.ledger_mappings for each row execute function public.ledger_mapping_guard();

-- ---------- RLS ----------
alter table public.budgets enable row level security;
alter table public.budget_lines enable row level security;
alter table public.ledger_accounts enable row level security;
alter table public.ledger_mappings enable row level security;
alter table public.journal_entries enable row level security;
alter table public.journal_lines enable row level security;
do $$
declare t text;
begin
  foreach t in array array['budgets','budget_lines','ledger_accounts','ledger_mappings','journal_entries','journal_lines'] loop
    execute format('drop policy if exists %I on public.%I', t || '_finance', t);
    execute format('create policy %I on public.%I for all using (tenant_id = public.my_tenant_id() and public.is_finance()) with check (tenant_id = public.my_tenant_id() and public.is_finance())', t || '_finance', t);
  end loop;
end $$;

alter table public.petty_cash_floats enable row level security;
drop policy if exists petty_floats_read on public.petty_cash_floats;
create policy petty_floats_read on public.petty_cash_floats for select using (tenant_id = public.my_tenant_id() and (public.is_finance() or custodian_id = auth.uid()));
drop policy if exists petty_floats_write on public.petty_cash_floats;
create policy petty_floats_write on public.petty_cash_floats for all using (tenant_id = public.my_tenant_id() and public.is_finance())
  with check (tenant_id = public.my_tenant_id() and public.is_finance());

-- Moves are a ledger: added, never edited. Spends come through petty_cash_spend(); a spend goes away only with its expense.
alter table public.petty_cash_moves enable row level security;
drop policy if exists petty_moves_read on public.petty_cash_moves;
create policy petty_moves_read on public.petty_cash_moves for select using (tenant_id = public.my_tenant_id() and (public.is_finance() or public.is_custodian_of(float_id)));
drop policy if exists petty_moves_insert on public.petty_cash_moves;
create policy petty_moves_insert on public.petty_cash_moves for insert with check (tenant_id = public.my_tenant_id() and public.is_finance() and kind <> 'spend');

alter table public.petty_cash_counts enable row level security;
drop policy if exists petty_counts_read on public.petty_cash_counts;
create policy petty_counts_read on public.petty_cash_counts for select using (tenant_id = public.my_tenant_id() and (public.is_finance() or public.is_custodian_of(float_id)));
drop policy if exists petty_counts_insert on public.petty_cash_counts;
create policy petty_counts_insert on public.petty_cash_counts for insert with check (tenant_id = public.my_tenant_id() and (public.is_finance() or public.is_custodian_of(float_id)));

grant all on public.budgets, public.budget_lines, public.petty_cash_floats, public.petty_cash_moves, public.petty_cash_counts,
  public.ledger_accounts, public.ledger_mappings, public.journal_entries, public.journal_lines to service_role;

select public.attach_change_log();

-- ===== 20260101004100_hr_people.sql =====
-- =====================================================================
--  Phase 10a: people.
--
--  * Staff records: line manager, personal and statutory details (NIN, TIN,
--    pension RSA PIN, NHF number, next of kin), documents, contracts and
--    qualifications (with expiry, e.g. TRCN licences).
--  * Recruitment: job postings on a public careers page, applications with
--    CVs, stages, interviews with a panel and each panellist's scores.
--  * Onboarding and offboarding checklists, ticked by whoever owns each item.
--  * Leave: policies per type (days, paid, carry-over), half days, the line
--    manager's recommendation before HR decides, a supporting document, and
--    approved leave feeding the cover planner.
-- =====================================================================

-- ---------- Helpers ----------
create or replace function public.is_hr()
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_role(array['hr_manager','school_admin','principal','platform_admin']);
$$;
grant execute on function public.is_hr() to authenticated;

create or replace function public.my_staff_id()
returns uuid language sql stable security definer set search_path = public as $$
  select id from public.staff where user_id = auth.uid() and tenant_id = public.my_tenant_id() limit 1;
$$;
grant execute on function public.my_staff_id() to authenticated;

-- ---------- Staff records ----------
alter table public.staff add column if not exists line_manager_id uuid references public.staff(id) on delete set null;
alter table public.staff add column if not exists probation_ends_on date;
alter table public.staff add column if not exists exit_date date;
alter table public.staff add column if not exists exit_reason text;

-- The signed-in user is this staff member's line manager.
create or replace function public.manages_staff(p_staff uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.staff s join public.staff m on m.id = s.line_manager_id
                 where s.id = p_staff and s.tenant_id = public.my_tenant_id() and m.user_id = auth.uid());
$$;
grant execute on function public.manages_staff(uuid) to authenticated;

create table if not exists public.staff_personal (
  staff_id                uuid primary key references public.staff(id) on delete cascade,
  tenant_id               uuid not null references public.tenants(id) on delete cascade,
  date_of_birth           date,
  gender                  text check (gender in ('female','male','other')),
  marital_status          text,
  address                 text,
  state_of_origin         text,
  nationality             text,
  nin                     text check (nin ~ '^\d{11}$'),             -- National Identification Number
  tin                     text,                                      -- tax ID for PAYE
  pfa_name                text,                                      -- pension fund administrator
  rsa_pin                 text check (rsa_pin ~* '^PEN\d{12}$'),     -- retirement savings account PIN
  nhf_number              text,                                      -- National Housing Fund
  next_of_kin_name        text,
  next_of_kin_relation    text,
  next_of_kin_phone       text,
  emergency_contact_name  text,
  emergency_contact_phone text,
  medical_notes           text,
  updated_at              timestamptz not null default now()
);

create table if not exists public.staff_documents (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null references public.tenants(id) on delete cascade,
  staff_id          uuid not null references public.staff(id) on delete cascade,
  kind              text not null check (kind in ('cv','id','offer_letter','contract','certificate','reference','medical','appraisal','exit','other')),
  title             text not null check (length(trim(title)) between 1 and 160),
  path              text not null,
  mime              text,
  size_bytes        int,
  visible_to_staff  boolean not null default true,     -- e.g. references stay with HR
  uploaded_by       uuid references public.users(id) on delete set null,
  created_at        timestamptz not null default now()
);
create index if not exists staff_documents_staff on public.staff_documents(staff_id);
insert into storage.buckets (id, name, public) values ('staff-documents', 'staff-documents', false) on conflict (id) do nothing;

create table if not exists public.staff_contracts (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null references public.tenants(id) on delete cascade,
  staff_id           uuid not null references public.staff(id) on delete cascade,
  kind               text not null check (kind in ('permanent','fixed_term','probation','part_time','consultancy','internship')),
  position           text,
  starts_on          date not null,
  ends_on            date,
  probation_ends_on  date,
  notice_days        int check (notice_days between 0 and 365),
  salary_note        text,
  notes              text,
  document_id        uuid references public.staff_documents(id) on delete set null,
  status             text not null default 'active' check (status in ('draft','active','ended')),
  accepted_at        timestamptz,             -- the staff member accepted it in their portal
  created_by         uuid references public.users(id) on delete set null,
  created_at         timestamptz not null default now(),
  check (ends_on is null or ends_on >= starts_on)
);
create index if not exists staff_contracts_staff on public.staff_contracts(staff_id, starts_on desc);

create table if not exists public.staff_qualifications (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  staff_id      uuid not null references public.staff(id) on delete cascade,
  kind          text not null check (kind in ('degree','diploma','certificate','professional','licence','other')),
  title         text not null check (length(trim(title)) between 1 and 160),
  institution   text,
  awarded_on    date,
  expires_on    date,
  reference_no  text,                    -- e.g. TRCN registration number
  document_id   uuid references public.staff_documents(id) on delete set null,
  verified_by   uuid references public.users(id) on delete set null,
  verified_at   timestamptz,
  created_at    timestamptz not null default now()
);
create index if not exists staff_qualifications_staff on public.staff_qualifications(staff_id);

-- Staff add their own qualifications; only HR verifies, and a verified one is HR's to change.
create or replace function public.staff_qualification_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return case when tg_op = 'DELETE' then old else new end; end if;
  if public.is_hr() then
    if tg_op = 'DELETE' then return old; end if;
    if tg_op = 'INSERT' then
      if new.verified_at is not null then new.verified_by := auth.uid(); new.verified_at := now(); end if;
    elsif new.verified_at is not null and old.verified_at is null then
      new.verified_by := auth.uid(); new.verified_at := now();
    elsif new.verified_at is null then
      new.verified_by := null;
    end if;
    return new;
  end if;
  if tg_op <> 'INSERT' and old.verified_at is not null then raise exception 'HR has verified this qualification; ask HR to change it'; end if;
  if tg_op = 'DELETE' then return old; end if;
  new.verified_by := null; new.verified_at := null;
  return new;
end $$;
drop trigger if exists staff_qualification_guard on public.staff_qualifications;
create trigger staff_qualification_guard before insert or update or delete on public.staff_qualifications for each row execute function public.staff_qualification_guard();

-- ---------- Recruitment ----------
create table if not exists public.job_postings (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  title            text not null check (length(trim(title)) between 2 and 160),
  department       text,
  employment_type  text not null default 'full_time' check (employment_type in ('full_time','part_time','contract','volunteer')),
  location         text,
  description      text not null default '',
  requirements     text,
  salary_range     text,
  positions        int not null default 1 check (positions between 1 and 100),
  closes_on        date,
  status           text not null default 'draft' check (status in ('draft','open','closed','filled')),
  internal_only    boolean not null default false,
  token            text not null default encode(gen_random_bytes(9), 'hex'),
  created_by       uuid references public.users(id) on delete set null,
  published_at     timestamptz,
  created_at       timestamptz not null default now(),
  unique (token)
);

create table if not exists public.job_applications (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null references public.tenants(id) on delete cascade,
  posting_id        uuid not null references public.job_postings(id) on delete cascade,
  full_name         text not null,
  email             text not null,
  phone             text,
  cover_letter      text,
  cv_path           text,
  answers           jsonb not null default '{}'::jsonb,
  source            text,
  internal_staff_id uuid references public.staff(id) on delete set null,   -- a current member of staff applying
  stage             text not null default 'applied' check (stage in ('applied','shortlisted','interview','offer','hired','rejected','withdrawn')),
  rating            smallint check (rating between 1 and 5),
  notes             text,
  track_token       text not null default encode(gen_random_bytes(18), 'hex'),
  hired_staff_id    uuid references public.staff(id) on delete set null,
  stage_changed_at  timestamptz not null default now(),
  created_at        timestamptz not null default now(),
  unique (track_token)
);
create unique index if not exists job_applications_once on public.job_applications(posting_id, lower(email));
create index if not exists job_applications_stage on public.job_applications(tenant_id, stage);
insert into storage.buckets (id, name, public) values ('job-applications', 'job-applications', false) on conflict (id) do nothing;

create table if not exists public.job_interviews (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  application_id  uuid not null references public.job_applications(id) on delete cascade,
  scheduled_at    timestamptz not null,
  duration_min    int not null default 30 check (duration_min between 5 and 480),
  mode            text not null default 'in_person' check (mode in ('in_person','phone','video')),
  location        text,                 -- a room, or the video link
  panel           uuid[] not null default '{}',
  status          text not null default 'scheduled' check (status in ('scheduled','done','cancelled','no_show')),
  created_by      uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now()
);
create index if not exists job_interviews_app on public.job_interviews(application_id);

create table if not exists public.interview_scores (
  interview_id    uuid not null references public.job_interviews(id) on delete cascade,
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  panelist_id     uuid not null references public.users(id) on delete cascade,
  score           smallint not null check (score between 1 and 5),
  recommendation  text not null check (recommendation in ('hire','maybe','no')),
  comments        text,
  created_at      timestamptz not null default now(),
  primary key (interview_id, panelist_id)
);

create or replace function public.on_interview_panel(p_application uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.job_interviews i where i.application_id = p_application
                 and i.tenant_id = public.my_tenant_id() and auth.uid() = any(i.panel));
$$;
grant execute on function public.on_interview_panel(uuid) to authenticated;

create or replace function public.interview_score_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return new; end if;
  if not exists (select 1 from public.job_interviews i where i.id = new.interview_id and i.tenant_id = new.tenant_id and auth.uid() = any(i.panel)) then
    raise exception 'only members of the interview panel can score it';
  end if;
  new.panelist_id := auth.uid();
  return new;
end $$;
drop trigger if exists interview_score_guard on public.interview_scores;
create trigger interview_score_guard before insert or update on public.interview_scores for each row execute function public.interview_score_guard();

-- ---------- Onboarding and offboarding ----------
create table if not exists public.hr_checklist_templates (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  kind        text not null check (kind in ('onboarding','offboarding')),
  name        text not null check (length(trim(name)) between 1 and 120),
  items       jsonb not null default '[]'::jsonb,     -- [{ "label": "…", "owner": "hr_manager", "due_days": 3 }]
  created_at  timestamptz not null default now(),
  unique (tenant_id, kind, name)
);
create table if not exists public.staff_checklists (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  staff_id      uuid not null references public.staff(id) on delete cascade,
  kind          text not null check (kind in ('onboarding','offboarding')),
  name          text not null,
  started_on    date not null default current_date,
  completed_at  timestamptz,
  created_by    uuid references public.users(id) on delete set null,
  created_at    timestamptz not null default now()
);
create index if not exists staff_checklists_staff on public.staff_checklists(staff_id);
create table if not exists public.staff_checklist_items (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  checklist_id  uuid not null references public.staff_checklists(id) on delete cascade,
  position      int not null default 0,
  label         text not null check (length(trim(label)) between 1 and 200),
  owner         text not null default 'hr_manager',    -- a role, 'staff' (the person themselves) or 'line_manager'
  due_on        date,
  done_at       timestamptz,
  done_by       uuid references public.users(id) on delete set null,
  note          text
);
create index if not exists staff_checklist_items_list on public.staff_checklist_items(checklist_id, position);

-- Who may tick an item: HR, anyone holding the owner role, the person themselves for 'staff', their manager for 'line_manager'.
create or replace function public.can_tick_item(p_checklist uuid, p_owner text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_hr()
    or (p_owner not in ('staff','line_manager') and public.has_role(array[p_owner]))
    or exists (select 1 from public.staff_checklists c join public.staff s on s.id = c.staff_id
               where c.id = p_checklist and c.tenant_id = public.my_tenant_id()
                 and ((p_owner = 'staff' and s.user_id = auth.uid()) or (p_owner = 'line_manager' and public.manages_staff(s.id))));
$$;
grant execute on function public.can_tick_item(uuid, text) to authenticated;

create or replace function public.checklist_item_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return case when tg_op = 'DELETE' then old else new end; end if;
  if tg_op = 'DELETE' or tg_op = 'INSERT' then
    if not public.is_hr() then raise exception 'only HR can change a checklist'; end if;
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if not public.is_hr() and (new.label is distinct from old.label or new.owner is distinct from old.owner or new.due_on is distinct from old.due_on
      or new.position is distinct from old.position or new.checklist_id is distinct from old.checklist_id) then
    raise exception 'you can tick items and add a note, nothing else';
  end if;
  if new.done_at is not null and old.done_at is null then new.done_by := auth.uid(); new.done_at := now(); end if;
  if new.done_at is null then new.done_by := null; end if;
  return new;
end $$;
drop trigger if exists checklist_item_guard on public.staff_checklist_items;
create trigger checklist_item_guard before insert or update or delete on public.staff_checklist_items for each row execute function public.checklist_item_guard();

create or replace function public.checklist_completion() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_list uuid;
begin
  if tg_op = 'DELETE' then v_list := old.checklist_id; else v_list := new.checklist_id; end if;
  update public.staff_checklists c set completed_at = case
      when exists (select 1 from public.staff_checklist_items i where i.checklist_id = c.id)
       and not exists (select 1 from public.staff_checklist_items i where i.checklist_id = c.id and i.done_at is null)
      then coalesce(c.completed_at, now()) else null end
    where c.id = v_list;
  return null;
end $$;
drop trigger if exists checklist_completion on public.staff_checklist_items;
create trigger checklist_completion after insert or update or delete on public.staff_checklist_items for each row execute function public.checklist_completion();

-- ---------- Leave ----------
create table if not exists public.leave_policies (
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  leave_type      text not null check (leave_type in ('annual','sick','maternity','paternity','compassionate','study','unpaid','other')),
  days_per_year   numeric check (days_per_year is null or days_per_year between 0 and 366),   -- null = no yearly limit
  paid            boolean not null default true,
  carry_over_max  numeric not null default 0 check (carry_over_max between 0 and 366),
  needs_document  boolean not null default false,
  min_notice_days int not null default 0 check (min_notice_days between 0 and 365),
  primary key (tenant_id, leave_type)
);

alter table public.leave_requests alter column days type numeric using days::numeric;
alter table public.leave_requests drop constraint if exists leave_requests_days_check;
alter table public.leave_requests add constraint leave_requests_days_check check (days > 0 and days * 2 = round(days * 2));
alter table public.leave_requests add column if not exists half_day boolean not null default false;
alter table public.leave_requests add column if not exists document_id uuid references public.staff_documents(id) on delete set null;
alter table public.leave_requests add column if not exists cover_note text;
alter table public.leave_requests add column if not exists manager_status text check (manager_status in ('pending','recommended','not_recommended'));
alter table public.leave_requests add column if not exists manager_id uuid references public.users(id) on delete set null;
alter table public.leave_requests add column if not exists manager_note text;
alter table public.leave_requests add column if not exists manager_at timestamptz;
alter table public.staff_absences add column if not exists leave_request_id uuid references public.leave_requests(id) on delete cascade;
create unique index if not exists staff_absences_leave on public.staff_absences(leave_request_id) where leave_request_id is not null;

-- Line managers see and recommend their team's leave; HR decides; staff only cancel their own.
drop policy if exists leave_read on public.leave_requests;
create policy leave_read on public.leave_requests for select using (
  tenant_id = public.my_tenant_id() and (public.is_hr() or staff_id = public.my_staff_id() or public.manages_staff(staff_id)));
drop policy if exists leave_update on public.leave_requests;
create policy leave_update on public.leave_requests for update using (
  tenant_id = public.my_tenant_id() and (public.is_hr() or staff_id = public.my_staff_id() or public.manages_staff(staff_id))
) with check (tenant_id = public.my_tenant_id());

create or replace function public.leave_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_self boolean; v_manager boolean;
begin
  if auth.uid() is null then return new; end if;
  v_self := new.staff_id = public.my_staff_id();
  v_manager := public.manages_staff(new.staff_id);
  if new.staff_id is distinct from old.staff_id or new.starts_on is distinct from old.starts_on or new.ends_on is distinct from old.ends_on
     or new.days is distinct from old.days or new.leave_type is distinct from old.leave_type then
    if not public.is_hr() or v_self then raise exception 'the dates and type of a request cannot be changed; cancel it and ask again'; end if;
  end if;
  if new.status is distinct from old.status then
    if new.status in ('approved','rejected') then
      if not public.is_hr() then raise exception 'only HR or admins can decide leave'; end if;
      if v_self then raise exception 'you cannot decide your own leave'; end if;
      new.decided_by := auth.uid(); new.decided_at := now();
    elsif new.status = 'cancelled' then
      if not (v_self or public.is_hr()) then raise exception 'only the person on leave or HR can cancel it'; end if;
    else
      raise exception 'leave cannot go back to pending';
    end if;
  elsif not public.is_hr() and (new.decided_by is distinct from old.decided_by or new.decision_note is distinct from old.decision_note) then
    raise exception 'only HR records the decision';
  end if;
  if new.manager_status is distinct from old.manager_status or new.manager_note is distinct from old.manager_note then
    if v_self then raise exception 'you cannot recommend your own leave'; end if;
    if not (v_manager or public.is_hr()) then raise exception 'only the line manager can recommend leave'; end if;
    if old.status <> 'pending' then raise exception 'this request is already decided'; end if;
    new.manager_id := auth.uid(); new.manager_at := now();
  end if;
  if v_self and not public.is_hr() and not v_manager then
    if new.cover_note is distinct from old.cover_note or new.reason is distinct from old.reason or new.document_id is distinct from old.document_id then
      if old.status <> 'pending' then raise exception 'this request is already decided'; end if;
    end if;
  end if;
  return new;
end $$;

-- ---------- RLS ----------
alter table public.staff_personal enable row level security;
drop policy if exists staff_personal_read on public.staff_personal;
create policy staff_personal_read on public.staff_personal for select using (tenant_id = public.my_tenant_id() and (public.is_hr() or staff_id = public.my_staff_id()));
drop policy if exists staff_personal_write on public.staff_personal;
create policy staff_personal_write on public.staff_personal for all using (tenant_id = public.my_tenant_id() and (public.is_hr() or staff_id = public.my_staff_id()))
  with check (tenant_id = public.my_tenant_id() and (public.is_hr() or staff_id = public.my_staff_id()));

alter table public.staff_documents enable row level security;
drop policy if exists staff_documents_read on public.staff_documents;
create policy staff_documents_read on public.staff_documents for select using (tenant_id = public.my_tenant_id()
  and (public.is_hr() or (staff_id = public.my_staff_id() and visible_to_staff)));
drop policy if exists staff_documents_write on public.staff_documents;
create policy staff_documents_write on public.staff_documents for all using (tenant_id = public.my_tenant_id() and public.is_hr())
  with check (tenant_id = public.my_tenant_id() and public.is_hr());
-- Staff upload their own documents through the server, which checks the file and the kind.

alter table public.staff_contracts enable row level security;
drop policy if exists staff_contracts_read on public.staff_contracts;
create policy staff_contracts_read on public.staff_contracts for select using (tenant_id = public.my_tenant_id() and (public.is_hr() or (staff_id = public.my_staff_id() and status <> 'draft')));
drop policy if exists staff_contracts_write on public.staff_contracts;
create policy staff_contracts_write on public.staff_contracts for all using (tenant_id = public.my_tenant_id() and public.is_hr())
  with check (tenant_id = public.my_tenant_id() and public.is_hr());

alter table public.staff_qualifications enable row level security;
drop policy if exists staff_qualifications_read on public.staff_qualifications;
create policy staff_qualifications_read on public.staff_qualifications for select using (tenant_id = public.my_tenant_id() and (public.is_hr() or staff_id = public.my_staff_id()));
drop policy if exists staff_qualifications_write on public.staff_qualifications;
create policy staff_qualifications_write on public.staff_qualifications for all using (tenant_id = public.my_tenant_id() and (public.is_hr() or staff_id = public.my_staff_id()))
  with check (tenant_id = public.my_tenant_id() and (public.is_hr() or staff_id = public.my_staff_id()));

alter table public.job_postings enable row level security;
drop policy if exists job_postings_read on public.job_postings;
create policy job_postings_read on public.job_postings for select using (tenant_id = public.my_tenant_id() and (public.is_hr() or (public.is_staff() and status = 'open')));
drop policy if exists job_postings_write on public.job_postings;
create policy job_postings_write on public.job_postings for all using (tenant_id = public.my_tenant_id() and public.is_hr())
  with check (tenant_id = public.my_tenant_id() and public.is_hr());

-- Applications arrive through the careers page (server); HR manages them; the interview panel reads the ones it meets.
alter table public.job_applications enable row level security;
drop policy if exists job_applications_read on public.job_applications;
create policy job_applications_read on public.job_applications for select using (tenant_id = public.my_tenant_id() and (public.is_hr() or public.on_interview_panel(id)));
drop policy if exists job_applications_write on public.job_applications;
create policy job_applications_write on public.job_applications for update using (tenant_id = public.my_tenant_id() and public.is_hr())
  with check (tenant_id = public.my_tenant_id() and public.is_hr());
drop policy if exists job_applications_delete on public.job_applications;
create policy job_applications_delete on public.job_applications for delete using (tenant_id = public.my_tenant_id() and public.is_hr());

alter table public.job_interviews enable row level security;
drop policy if exists job_interviews_read on public.job_interviews;
create policy job_interviews_read on public.job_interviews for select using (tenant_id = public.my_tenant_id() and (public.is_hr() or auth.uid() = any(panel)));
drop policy if exists job_interviews_write on public.job_interviews;
create policy job_interviews_write on public.job_interviews for all using (tenant_id = public.my_tenant_id() and public.is_hr())
  with check (tenant_id = public.my_tenant_id() and public.is_hr());

-- Each panellist scores alone; HR sees every score.
alter table public.interview_scores enable row level security;
drop policy if exists interview_scores_read on public.interview_scores;
create policy interview_scores_read on public.interview_scores for select using (tenant_id = public.my_tenant_id() and (public.is_hr() or panelist_id = auth.uid()));
drop policy if exists interview_scores_write on public.interview_scores;
create policy interview_scores_write on public.interview_scores for all using (tenant_id = public.my_tenant_id() and panelist_id = auth.uid())
  with check (tenant_id = public.my_tenant_id());

alter table public.hr_checklist_templates enable row level security;
drop policy if exists hr_templates_hr on public.hr_checklist_templates;
create policy hr_templates_hr on public.hr_checklist_templates for all using (tenant_id = public.my_tenant_id() and public.is_hr())
  with check (tenant_id = public.my_tenant_id() and public.is_hr());

-- A checklist is visible to HR, the person, their manager, and anyone with a task on it (checked as definer so the two tables' policies do not call each other).
create or replace function public.checklist_visible(p_checklist uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_hr() or exists (
    select 1 from public.staff_checklists c where c.id = p_checklist and c.tenant_id = public.my_tenant_id()
      and (c.staff_id = public.my_staff_id() or public.manages_staff(c.staff_id)
           or exists (select 1 from public.staff_checklist_items i where i.checklist_id = c.id and i.owner not in ('staff','line_manager') and public.has_role(array[i.owner]))));
$$;
grant execute on function public.checklist_visible(uuid) to authenticated;

alter table public.staff_checklists enable row level security;
drop policy if exists staff_checklists_read on public.staff_checklists;
create policy staff_checklists_read on public.staff_checklists for select using (tenant_id = public.my_tenant_id() and public.checklist_visible(id));
drop policy if exists staff_checklists_write on public.staff_checklists;
create policy staff_checklists_write on public.staff_checklists for all using (tenant_id = public.my_tenant_id() and public.is_hr())
  with check (tenant_id = public.my_tenant_id() and public.is_hr());

alter table public.staff_checklist_items enable row level security;
drop policy if exists checklist_items_read on public.staff_checklist_items;
create policy checklist_items_read on public.staff_checklist_items for select using (tenant_id = public.my_tenant_id() and public.checklist_visible(checklist_id));
drop policy if exists checklist_items_insert on public.staff_checklist_items;
create policy checklist_items_insert on public.staff_checklist_items for insert with check (tenant_id = public.my_tenant_id() and public.is_hr());
drop policy if exists checklist_items_update on public.staff_checklist_items;
create policy checklist_items_update on public.staff_checklist_items for update using (tenant_id = public.my_tenant_id() and public.can_tick_item(checklist_id, owner))
  with check (tenant_id = public.my_tenant_id());
drop policy if exists checklist_items_delete on public.staff_checklist_items;
create policy checklist_items_delete on public.staff_checklist_items for delete using (tenant_id = public.my_tenant_id() and public.is_hr());

alter table public.leave_policies enable row level security;
drop policy if exists leave_policies_read on public.leave_policies;
create policy leave_policies_read on public.leave_policies for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists leave_policies_write on public.leave_policies;
create policy leave_policies_write on public.leave_policies for all using (tenant_id = public.my_tenant_id() and public.is_hr())
  with check (tenant_id = public.my_tenant_id() and public.is_hr());

grant all on public.staff_personal, public.staff_documents, public.staff_contracts, public.staff_qualifications, public.job_postings, public.job_applications,
  public.job_interviews, public.interview_scores, public.hr_checklist_templates, public.staff_checklists, public.staff_checklist_items, public.leave_policies to service_role;

select public.attach_change_log();

-- ===== 20260101004200_payroll_appraisals.sql =====
-- =====================================================================
--  Phase 10b: statutory payroll, appraisals, lesson observation responses and CPD.
--
--  * HR and payroll settings per school: Nigerian PAYE (Nigeria Tax Act 2025
--    bands, or the school's own) or a flat rate; pension (employee and employer
--    shares on basic + housing + transport), NHF, NHIS, NSITF and ITF; rent
--    relief; leave year; CPD target hours.
--  * Pay grades; salary profiles linked to a grade, with rent, NHF and NHIS
--    choices; staff loans and salary advances repaid through payroll.
--  * Payslips keep PAYE, pension, NHF, employer contributions and loan
--    repayments; loans go down when a run is marked paid.
--  * Appraisal cycles with criteria; self-review, the reviewer's review (shown
--    to the person only at the discussion stage), goals and acknowledgement.
--  * Teachers acknowledge and answer lesson observations.
--  * CPD activities logged by staff and verified by HR.
-- =====================================================================

-- ---------- Settings ----------
create table if not exists public.hr_settings (
  tenant_id              uuid primary key references public.tenants(id) on delete cascade,
  tax_regime             text not null default 'nta2025' check (tax_regime in ('nta2025','flat')),
  tax_bands              jsonb,            -- [{ "upto": 800000, "rate": 0 }, …, { "upto": null, "rate": 25 }]; null = the Act's bands
  pension_employee_pct   numeric not null default 8  check (pension_employee_pct between 0 and 100),
  pension_employer_pct   numeric not null default 10 check (pension_employer_pct between 0 and 100),
  nhf_pct                numeric not null default 2.5 check (nhf_pct between 0 and 100),
  nhis_employee_pct      numeric not null default 0 check (nhis_employee_pct between 0 and 100),
  nhis_employer_pct      numeric not null default 0 check (nhis_employer_pct between 0 and 100),
  nsitf_pct              numeric not null default 1 check (nsitf_pct between 0 and 100),
  itf_pct                numeric not null default 0 check (itf_pct between 0 and 100),
  rent_relief_pct        numeric not null default 20 check (rent_relief_pct between 0 and 100),
  rent_relief_cap        numeric not null default 500000 check (rent_relief_cap >= 0),
  prorate_joiners        boolean not null default true,
  leave_year_start_month int not null default 1 check (leave_year_start_month between 1 and 12),
  cpd_target_hours       numeric not null default 20 check (cpd_target_hours between 0 and 1000),
  updated_at             timestamptz not null default now()
);

-- ---------- Pay ----------
create table if not exists public.pay_grades (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  name        text not null check (length(trim(name)) between 1 and 60),
  basic       numeric(14,2) not null check (basic >= 0),
  allowances  jsonb not null default '[]'::jsonb,     -- [{ name, amount, pensionable?, taxable? }]
  created_at  timestamptz not null default now(),
  unique (tenant_id, name)
);
alter table public.salary_profiles add column if not exists grade_id uuid references public.pay_grades(id) on delete set null;
alter table public.salary_profiles add column if not exists annual_rent numeric(14,2) not null default 0 check (annual_rent >= 0);
alter table public.salary_profiles add column if not exists nhf boolean not null default false;
alter table public.salary_profiles add column if not exists nhis boolean not null default false;
alter table public.salary_profiles add column if not exists pension_exempt boolean not null default false;

create table if not exists public.staff_loans (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null references public.tenants(id) on delete cascade,
  staff_id           uuid not null references public.staff(id) on delete cascade,
  kind               text not null default 'loan' check (kind in ('loan','advance')),
  principal          numeric(14,2) not null check (principal > 0),
  monthly_deduction  numeric(14,2) not null check (monthly_deduction > 0),
  balance            numeric(14,2) not null check (balance >= 0),
  start_period       text not null check (start_period ~ '^\d{4}-(0[1-9]|1[0-2])$'),
  status             text not null default 'active' check (status in ('active','settled','cancelled')),
  note               text,
  created_by         uuid references public.users(id) on delete set null,
  approved_by        uuid references public.users(id) on delete set null,
  created_at         timestamptz not null default now()
);
create index if not exists staff_loans_staff on public.staff_loans(staff_id, status);

alter table public.payslips add column if not exists paye numeric(14,2) not null default 0;
alter table public.payslips add column if not exists taxable_income numeric(14,2) not null default 0;     -- annualised, after reliefs
alter table public.payslips add column if not exists pension_employee numeric(14,2) not null default 0;
alter table public.payslips add column if not exists pension_employer numeric(14,2) not null default 0;
alter table public.payslips add column if not exists nhf numeric(14,2) not null default 0;
alter table public.payslips add column if not exists employer_contributions jsonb not null default '[]'::jsonb;
alter table public.payslips add column if not exists employer_total numeric(14,2) not null default 0;
alter table public.payslips add column if not exists loan_repayments jsonb not null default '[]'::jsonb;   -- [{ loan_id, amount }]
alter table public.payslips add column if not exists days_worked numeric;      -- set when pay was prorated (joined or left mid-month)
alter table public.payroll_runs add column if not exists employer_total numeric(14,2) not null default 0;

-- A loan is approved by someone other than the person who entered it; a staff member never approves their own.
create or replace function public.staff_loan_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  -- Repayments are booked by the payroll trigger (one level down), not by a person.
  if auth.uid() is null or pg_trigger_depth() > 1 then return new; end if;
  if tg_op = 'INSERT' then
    new.created_by := auth.uid(); new.approved_by := null; new.balance := new.principal;
    return new;
  end if;
  if new.approved_by is distinct from old.approved_by then
    if new.approved_by is not null then
      if not public.has_role(array['school_admin','principal','platform_admin']) then raise exception 'only the principal or a school admin can approve a loan'; end if;
      if old.created_by = auth.uid() then raise exception 'a loan must be approved by someone other than the person who entered it'; end if;
      if exists (select 1 from public.staff s where s.id = new.staff_id and s.user_id = auth.uid()) then raise exception 'you cannot approve your own loan'; end if;
      new.approved_by := auth.uid();
    end if;
  end if;
  if old.approved_by is not null and (new.principal is distinct from old.principal or new.balance is distinct from old.balance) then
    raise exception 'an approved loan changes only through payroll; cancel it and enter a new one';
  end if;
  return new;
end $$;
drop trigger if exists staff_loan_guard on public.staff_loans;
create trigger staff_loan_guard before insert or update on public.staff_loans for each row execute function public.staff_loan_guard();

-- When a run is paid, its loan repayments come off the balances (once: a run is paid only once).
create or replace function public.payroll_paid_loans() returns trigger
language plpgsql security definer set search_path = public as $$
declare r record;
begin
  if new.status = 'paid' and old.status is distinct from 'paid' then
    for r in select (x ->> 'loan_id')::uuid as loan_id, sum((x ->> 'amount')::numeric) as amount
             from public.payslips p, jsonb_array_elements(p.loan_repayments) x where p.run_id = new.id group by 1 loop
      update public.staff_loans set balance = greatest(0, balance - r.amount),
        status = case when balance - r.amount <= 0 then 'settled' else status end
        where id = r.loan_id and tenant_id = new.tenant_id;
    end loop;
  end if;
  return null;
end $$;
drop trigger if exists payroll_paid_loans on public.payroll_runs;
create trigger payroll_paid_loans after update on public.payroll_runs for each row execute function public.payroll_paid_loans();

-- ---------- Appraisals ----------
create table if not exists public.appraisal_cycles (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  name         text not null check (length(trim(name)) between 1 and 120),
  starts_on    date not null,
  ends_on      date not null,
  status       text not null default 'draft' check (status in ('draft','open','closed')),
  criteria     jsonb not null default '[]'::jsonb,   -- [{ "id": "c1", "label": "Planning", "weight": 20 }]
  self_review  boolean not null default true,
  created_by   uuid references public.users(id) on delete set null,
  created_at   timestamptz not null default now(),
  check (ends_on >= starts_on),
  unique (tenant_id, name)
);
create table if not exists public.appraisals (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null references public.tenants(id) on delete cascade,
  cycle_id           uuid not null references public.appraisal_cycles(id) on delete cascade,
  staff_id           uuid not null references public.staff(id) on delete cascade,
  reviewer_id        uuid references public.users(id) on delete set null,
  status             text not null default 'self_review' check (status in ('self_review','review','discussion','completed')),
  self_scores        jsonb not null default '{}'::jsonb,
  self_comments      text,
  self_submitted_at  timestamptz,
  goals              jsonb not null default '[]'::jsonb,   -- [{ text, measure, due_on, status }]
  staff_comment      text,
  acknowledged_at    timestamptz,
  completed_at       timestamptz,
  created_at         timestamptz not null default now(),
  unique (cycle_id, staff_id)
);
create table if not exists public.appraisal_reviews (
  appraisal_id    uuid primary key references public.appraisals(id) on delete cascade,
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  scores          jsonb not null default '{}'::jsonb,
  overall         numeric check (overall between 0 and 5),
  strengths       text,
  development     text,
  recommendation  text check (recommendation in ('confirm','promote','increment','support_plan','none')),
  submitted_at    timestamptz,
  updated_at      timestamptz not null default now()
);

create or replace function public.is_appraisal_reviewer(p_appraisal uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.appraisals a where a.id = p_appraisal and a.tenant_id = public.my_tenant_id() and a.reviewer_id = auth.uid());
$$;
-- The person sees the reviewer's view once it reaches the discussion.
create or replace function public.appraisal_shared(p_appraisal uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.appraisals a where a.id = p_appraisal and a.tenant_id = public.my_tenant_id()
                 and a.staff_id = public.my_staff_id() and a.status in ('discussion','completed'));
$$;
grant execute on function public.is_appraisal_reviewer(uuid) to authenticated;
grant execute on function public.appraisal_shared(uuid) to authenticated;

-- Who moves an appraisal on, and what each person may write.
create or replace function public.appraisal_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_self boolean; v_reviewer boolean; v_hr boolean;
begin
  if auth.uid() is null then return new; end if;
  v_hr := public.is_hr();
  v_self := new.staff_id = public.my_staff_id();
  v_reviewer := old.reviewer_id = auth.uid();
  if v_self and v_reviewer then raise exception 'you cannot review yourself'; end if;
  if v_hr and not v_self then
    if new.status = 'completed' and old.status <> 'completed' then new.completed_at := now(); end if;
    return new;
  end if;
  if new.staff_id is distinct from old.staff_id or new.cycle_id is distinct from old.cycle_id or new.reviewer_id is distinct from old.reviewer_id then
    raise exception 'only HR assigns appraisals';
  end if;
  if v_self then
    if (new.self_scores is distinct from old.self_scores or new.self_comments is distinct from old.self_comments) and old.status <> 'self_review' then
      raise exception 'your self-review has been sent';
    end if;
    if new.goals is distinct from old.goals then raise exception 'goals are agreed with your reviewer'; end if;
    if new.status is distinct from old.status then
      if old.status = 'self_review' and new.status = 'review' then new.self_submitted_at := now();
      elsif old.status = 'discussion' and new.status = 'completed' then new.acknowledged_at := now(); new.completed_at := now();
      else raise exception 'you cannot move your appraisal to %', new.status; end if;
    end if;
    if new.staff_comment is distinct from old.staff_comment and old.status <> 'discussion' then raise exception 'you can comment once you have discussed the review'; end if;
    return new;
  end if;
  if v_reviewer then
    if new.self_scores is distinct from old.self_scores or new.self_comments is distinct from old.self_comments or new.staff_comment is distinct from old.staff_comment
       or new.acknowledged_at is distinct from old.acknowledged_at then
      raise exception 'that part belongs to the person being appraised';
    end if;
    if new.status is distinct from old.status then
      if old.status in ('self_review','review') and new.status = 'discussion' then
        if not exists (select 1 from public.appraisal_reviews r where r.appraisal_id = new.id and r.submitted_at is not null) then
          raise exception 'finish your review before sharing it';
        end if;
      elsif old.status = 'self_review' and new.status = 'review' then null;   -- go ahead without a self-review
      else raise exception 'you cannot move this appraisal to %', new.status; end if;
    end if;
    if old.status = 'completed' then raise exception 'this appraisal is complete'; end if;
    return new;
  end if;
  raise exception 'this appraisal is not yours';
end $$;
drop trigger if exists appraisal_guard on public.appraisals;
create trigger appraisal_guard before update on public.appraisals for each row execute function public.appraisal_guard();

create or replace function public.appraisal_review_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_status text; v_tenant uuid;
begin
  if auth.uid() is null then return case when tg_op = 'DELETE' then old else new end; end if;
  select status, tenant_id into v_status, v_tenant from public.appraisals where id = case when tg_op = 'DELETE' then old.appraisal_id else new.appraisal_id end;
  if v_status = 'completed' and not public.is_hr() then raise exception 'this appraisal is complete'; end if;
  if tg_op = 'DELETE' then return old; end if;
  if v_tenant is distinct from new.tenant_id then raise exception 'appraisal not found'; end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists appraisal_review_guard on public.appraisal_reviews;
create trigger appraisal_review_guard before insert or update or delete on public.appraisal_reviews for each row execute function public.appraisal_review_guard();

-- ---------- Lesson observations: the teacher's reply ----------
alter table public.qa_observations add column if not exists acknowledged_at timestamptz;
alter table public.qa_observations add column if not exists teacher_response text;
create or replace function public.acknowledge_observation(p_id uuid, p_response text)
returns void language plpgsql security definer set search_path = public as $$
begin
  update public.qa_observations set acknowledged_at = coalesce(acknowledged_at, now()), teacher_response = nullif(left(trim(coalesce(p_response, '')), 2000), '')
    where id = p_id and tenant_id = public.my_tenant_id() and staff_id = public.my_staff_id();
  if not found then raise exception 'observation not found'; end if;
end $$;
revoke all on function public.acknowledge_observation(uuid, text) from public, anon;
grant execute on function public.acknowledge_observation(uuid, text) to authenticated;

-- ---------- CPD ----------
create table if not exists public.cpd_activities (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  staff_id     uuid not null references public.staff(id) on delete cascade,
  title        text not null check (length(trim(title)) between 1 and 200),
  provider     text,
  kind         text not null default 'workshop' check (kind in ('workshop','course','conference','in_house','online','mentoring','reading','other')),
  starts_on    date not null,
  ends_on      date,
  hours        numeric not null check (hours > 0 and hours <= 1000),
  cost         numeric(14,2) check (cost >= 0),
  document_id  uuid references public.staff_documents(id) on delete set null,
  status       text not null default 'completed' check (status in ('planned','completed')),
  reflection   text,
  verified_by  uuid references public.users(id) on delete set null,
  verified_at  timestamptz,
  created_by   uuid references public.users(id) on delete set null,
  created_at   timestamptz not null default now(),
  check (ends_on is null or ends_on >= starts_on)
);
create index if not exists cpd_staff on public.cpd_activities(staff_id, starts_on desc);

create or replace function public.cpd_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return case when tg_op = 'DELETE' then old else new end; end if;
  if tg_op = 'INSERT' then new.created_by := auth.uid(); end if;
  if public.is_hr() then
    if tg_op <> 'DELETE' then
      if tg_op = 'INSERT' then
        if new.verified_at is not null then new.verified_by := auth.uid(); new.verified_at := now(); end if;
      elsif new.verified_at is not null and old.verified_at is null then new.verified_by := auth.uid(); new.verified_at := now();
      elsif new.verified_at is null then new.verified_by := null; end if;
    end if;
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if tg_op <> 'INSERT' and old.verified_at is not null then raise exception 'HR has verified this activity; ask HR to change it'; end if;
  if tg_op = 'DELETE' then return old; end if;
  new.verified_by := null; new.verified_at := null;
  return new;
end $$;
drop trigger if exists cpd_guard on public.cpd_activities;
create trigger cpd_guard before insert or update or delete on public.cpd_activities for each row execute function public.cpd_guard();

-- ---------- RLS ----------
alter table public.hr_settings enable row level security;
drop policy if exists hr_settings_read on public.hr_settings;
create policy hr_settings_read on public.hr_settings for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists hr_settings_write on public.hr_settings;
create policy hr_settings_write on public.hr_settings for all using (tenant_id = public.my_tenant_id() and public.has_role(array['hr_manager','bursar','school_admin','principal','platform_admin']))
  with check (tenant_id = public.my_tenant_id() and public.has_role(array['hr_manager','bursar','school_admin','principal','platform_admin']));

alter table public.pay_grades enable row level security;
drop policy if exists pay_grades_rw on public.pay_grades;
create policy pay_grades_rw on public.pay_grades for all using (tenant_id = public.my_tenant_id() and public.has_role(array['hr_manager','bursar','school_admin','principal','platform_admin']))
  with check (tenant_id = public.my_tenant_id() and public.has_role(array['hr_manager','bursar','school_admin','principal','platform_admin']));

alter table public.staff_loans enable row level security;
drop policy if exists staff_loans_read on public.staff_loans;
create policy staff_loans_read on public.staff_loans for select using (tenant_id = public.my_tenant_id()
  and (public.has_role(array['hr_manager','bursar','school_admin','principal','platform_admin']) or staff_id = public.my_staff_id()));
drop policy if exists staff_loans_write on public.staff_loans;
create policy staff_loans_write on public.staff_loans for all using (tenant_id = public.my_tenant_id() and public.has_role(array['hr_manager','bursar','school_admin','principal','platform_admin']))
  with check (tenant_id = public.my_tenant_id() and public.has_role(array['hr_manager','bursar','school_admin','principal','platform_admin']));

alter table public.appraisal_cycles enable row level security;
drop policy if exists appraisal_cycles_read on public.appraisal_cycles;
create policy appraisal_cycles_read on public.appraisal_cycles for select using (tenant_id = public.my_tenant_id() and (public.is_hr() or (public.is_staff() and status <> 'draft')));
drop policy if exists appraisal_cycles_write on public.appraisal_cycles;
create policy appraisal_cycles_write on public.appraisal_cycles for all using (tenant_id = public.my_tenant_id() and public.is_hr())
  with check (tenant_id = public.my_tenant_id() and public.is_hr());

alter table public.appraisals enable row level security;
drop policy if exists appraisals_read on public.appraisals;
create policy appraisals_read on public.appraisals for select using (tenant_id = public.my_tenant_id() and (public.is_hr() or staff_id = public.my_staff_id() or reviewer_id = auth.uid()));
drop policy if exists appraisals_insert on public.appraisals;
create policy appraisals_insert on public.appraisals for insert with check (tenant_id = public.my_tenant_id() and public.is_hr());
drop policy if exists appraisals_update on public.appraisals;
create policy appraisals_update on public.appraisals for update using (tenant_id = public.my_tenant_id() and (public.is_hr() or staff_id = public.my_staff_id() or reviewer_id = auth.uid()))
  with check (tenant_id = public.my_tenant_id());
drop policy if exists appraisals_delete on public.appraisals;
create policy appraisals_delete on public.appraisals for delete using (tenant_id = public.my_tenant_id() and public.is_hr());

alter table public.appraisal_reviews enable row level security;
drop policy if exists appraisal_reviews_read on public.appraisal_reviews;
create policy appraisal_reviews_read on public.appraisal_reviews for select using (tenant_id = public.my_tenant_id()
  and (public.is_hr() or public.is_appraisal_reviewer(appraisal_id) or public.appraisal_shared(appraisal_id)));
drop policy if exists appraisal_reviews_write on public.appraisal_reviews;
create policy appraisal_reviews_write on public.appraisal_reviews for all using (tenant_id = public.my_tenant_id() and (public.is_hr() or public.is_appraisal_reviewer(appraisal_id)))
  with check (tenant_id = public.my_tenant_id() and (public.is_hr() or public.is_appraisal_reviewer(appraisal_id)));

alter table public.cpd_activities enable row level security;
drop policy if exists cpd_read on public.cpd_activities;
create policy cpd_read on public.cpd_activities for select using (tenant_id = public.my_tenant_id() and (public.is_hr() or staff_id = public.my_staff_id() or public.manages_staff(staff_id)));
drop policy if exists cpd_write on public.cpd_activities;
create policy cpd_write on public.cpd_activities for all using (tenant_id = public.my_tenant_id() and (public.is_hr() or staff_id = public.my_staff_id()))
  with check (tenant_id = public.my_tenant_id() and (public.is_hr() or staff_id = public.my_staff_id()));

grant all on public.hr_settings, public.pay_grades, public.staff_loans, public.appraisal_cycles, public.appraisals, public.appraisal_reviews, public.cpd_activities to service_role;

select public.attach_change_log();

-- ===== 20260101004300_welfare.sql =====
-- =====================================================================
--  Phase 11a: student welfare and pastoral care.
--
--  * Counselling: cases and session notes seen only by counsellors (and the
--    safeguarding team when the counsellor shares a case); teachers refer
--    students without seeing the notes; every opening of a record is logged.
--  * Safeguarding: concerns reported by any staff member, a chronology that is
--    never edited, acknowledgement, escalation to the head if nobody picks a
--    concern up in time, external referrals.
--  * Behaviour: incidents with everyone involved, detention sessions and
--    detentions served or missed.
--  * Health: allergy severity and care plans, clinic vitals and follow-up,
--    medication plans with a dose log, immunisations.
--  * Wellbeing: student check-ins (mood, feelings, "I'd like to talk"), named
--    or anonymous, followed up by the form teacher or a counsellor.
--  None of the confidential records go into the change history.
-- =====================================================================

-- ---------- Helpers ----------
create or replace function public.is_counsellor()
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_role(array['counsellor']);
$$;
grant execute on function public.is_counsellor() to authenticated;

create or replace function public.is_form_teacher_of(p_student uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.students s join public.class_groups g on g.id = s.class_group_id
                 where s.id = p_student and s.tenant_id = public.my_tenant_id() and g.form_teacher_id = auth.uid());
$$;
grant execute on function public.is_form_teacher_of(uuid) to authenticated;

-- Opening a confidential record is logged (who, what, when).
create table if not exists public.sensitive_access_log (
  id           bigint generated always as identity primary key,
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  user_id      uuid references public.users(id) on delete set null,
  record_kind  text not null,
  record_id    uuid not null,
  student_id   uuid references public.students(id) on delete cascade,
  at           timestamptz not null default now()
);
create index if not exists sensitive_access_record on public.sensitive_access_log(record_kind, record_id, at desc);

-- ---------- Counselling ----------
create table if not exists public.pastoral_referrals (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  student_id   uuid not null references public.students(id) on delete cascade,
  referred_by  uuid references public.users(id) on delete set null,
  reason       text not null check (length(trim(reason)) between 3 and 2000),
  urgency      text not null default 'routine' check (urgency in ('routine','soon','urgent')),
  status       text not null default 'new' check (status in ('new','accepted','declined')),
  case_id      uuid,
  decided_by   uuid references public.users(id) on delete set null,
  decided_at   timestamptz,
  created_at   timestamptz not null default now()
);
create table if not exists public.counselling_cases (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  student_id       uuid not null references public.students(id) on delete cascade,
  counsellor_id    uuid references public.users(id) on delete set null,
  source           text not null default 'self' check (source in ('self','teacher','parent','safeguarding','other')),
  category         text not null default 'emotional' check (category in ('academic','emotional','family','peer','bereavement','behaviour','career','health','other')),
  summary          text,
  risk_level       text not null default 'low' check (risk_level in ('low','medium','high')),
  shared_with_dsl  boolean not null default false,     -- the safeguarding team may read it
  status           text not null default 'open' check (status in ('open','closed')),
  opened_at        timestamptz not null default now(),
  closed_at        timestamptz,
  created_by       uuid references public.users(id) on delete set null
);
alter table public.pastoral_referrals drop constraint if exists pastoral_referrals_case_fk;
alter table public.pastoral_referrals add constraint pastoral_referrals_case_fk foreign key (case_id) references public.counselling_cases(id) on delete set null;
create table if not exists public.counselling_sessions (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  case_id          uuid not null references public.counselling_cases(id) on delete cascade,
  held_at          timestamptz not null default now(),
  duration_min     int check (duration_min between 1 and 480),
  mode             text not null default 'in_person' check (mode in ('in_person','group','phone','online')),
  notes            text,
  actions          text,
  next_session_at  timestamptz,
  created_by       uuid references public.users(id) on delete set null,
  created_at       timestamptz not null default now()
);

create or replace function public.can_read_counselling(p_case uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.counselling_cases c where c.id = p_case and c.tenant_id = public.my_tenant_id()
                 and (public.is_counsellor() or c.counsellor_id = auth.uid() or (c.shared_with_dsl and public.is_safeguarding_lead())));
$$;
grant execute on function public.can_read_counselling(uuid) to authenticated;

-- Session notes are kept as written: the author may correct them on the day, then they are fixed.
create or replace function public.counselling_session_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return case when tg_op = 'DELETE' then old else new end; end if;
  if tg_op = 'INSERT' then new.created_by := auth.uid(); return new; end if;
  if old.created_by is distinct from auth.uid() or old.created_at < now() - interval '24 hours' then
    raise exception 'session notes can only be corrected by their author on the day; add a new note instead';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;
drop trigger if exists counselling_session_guard on public.counselling_sessions;
create trigger counselling_session_guard before insert or update or delete on public.counselling_sessions for each row execute function public.counselling_session_guard();

-- ---------- Safeguarding ----------
create table if not exists public.safeguarding_concerns (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null references public.tenants(id) on delete cascade,
  student_id         uuid not null references public.students(id) on delete cascade,
  reported_by        uuid references public.users(id) on delete set null,
  category           text not null check (category in ('physical','emotional','sexual','neglect','online','self_harm','bullying','exploitation','radicalisation','fgm','domestic','other')),
  severity           text not null default 'medium' check (severity in ('low','medium','high','critical')),
  description        text not null check (length(trim(description)) >= 10),
  observed_at        timestamptz not null default now(),
  location           text,
  immediate_action   text,
  status             text not null default 'new' check (status in ('new','acknowledged','investigating','referred','monitoring','closed')),
  assigned_to        uuid references public.users(id) on delete set null,
  acknowledged_at    timestamptz,
  escalated_at       timestamptz,
  external_agency    text,
  external_ref       text,
  parents_informed   text check (parents_informed in ('yes','no','not_appropriate')),
  outcome            text,
  closed_at          timestamptz,
  source_ref         text,              -- e.g. a flagged message the concern came from
  created_at         timestamptz not null default now()
);
create index if not exists safeguarding_open on public.safeguarding_concerns(tenant_id, status, created_at);
create table if not exists public.safeguarding_actions (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  concern_id  uuid not null references public.safeguarding_concerns(id) on delete cascade,
  kind        text not null check (kind in ('note','acknowledged','assigned','status','contacted_parent','referred','meeting','escalated')),
  detail      text not null,
  by_user     uuid references public.users(id) on delete set null,
  at          timestamptz not null default now()
);
create index if not exists safeguarding_actions_concern on public.safeguarding_actions(concern_id, at);

-- The chronology is written once and never changed.
create or replace function public.safeguarding_action_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if auth.uid() is not null then new.by_user := auth.uid(); new.at := now(); end if;
    return new;
  end if;
  if auth.uid() is null then return case when tg_op = 'DELETE' then old else new end; end if;
  raise exception 'the safeguarding chronology cannot be changed; add a new entry';
end $$;
drop trigger if exists safeguarding_action_guard on public.safeguarding_actions;
create trigger safeguarding_action_guard before insert or update or delete on public.safeguarding_actions for each row execute function public.safeguarding_action_guard();

-- Reporters write the concern; the safeguarding team manages it. Each change goes into the chronology.
create or replace function public.safeguarding_concern_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if auth.uid() is not null then
      new.reported_by := auth.uid(); new.status := 'new'; new.acknowledged_at := null; new.escalated_at := null; new.closed_at := null; new.assigned_to := null;
    end if;
    return new;
  end if;
  if auth.uid() is null then return new; end if;
  if not public.is_safeguarding_lead() then raise exception 'only the safeguarding team can update a concern'; end if;
  if new.description is distinct from old.description or new.student_id is distinct from old.student_id or new.reported_by is distinct from old.reported_by then
    raise exception 'the original report is kept as written; add a note instead';
  end if;
  if new.status is distinct from old.status then
    if old.status = 'new' and new.acknowledged_at is null then new.acknowledged_at := now(); end if;
    if new.status = 'closed' then
      if coalesce(trim(new.outcome), '') = '' then raise exception 'record the outcome before closing'; end if;
      new.closed_at := now();
    else new.closed_at := null; end if;
    insert into public.safeguarding_actions (tenant_id, concern_id, kind, detail) values (new.tenant_id, new.id, 'status', old.status || ' → ' || new.status);
  end if;
  if new.assigned_to is distinct from old.assigned_to then
    insert into public.safeguarding_actions (tenant_id, concern_id, kind, detail)
      values (new.tenant_id, new.id, 'assigned', coalesce((select full_name from public.users where id = new.assigned_to), 'nobody'));
  end if;
  if new.external_agency is distinct from old.external_agency and new.external_agency is not null then
    insert into public.safeguarding_actions (tenant_id, concern_id, kind, detail) values (new.tenant_id, new.id, 'referred', new.external_agency || coalesce(' (' || new.external_ref || ')', ''));
  end if;
  return new;
end $$;
drop trigger if exists safeguarding_concern_guard on public.safeguarding_concerns;
create trigger safeguarding_concern_guard before insert or update on public.safeguarding_concerns for each row execute function public.safeguarding_concern_guard();
alter table public.tenant_settings add column if not exists safeguarding_escalate_hours int not null default 4 check (safeguarding_escalate_hours between 1 and 72);

-- ---------- Behaviour: incidents and detentions ----------
create table if not exists public.behaviour_incidents (
