-- ===== 20260101004500_library.sql =====
-- =====================================================================
--  Phase 11c: library.
--
--  * Catalogue: print and digital (e-book, audio, video, link) with cover,
--    description, year, edition, language, price and a barcode for books
--    without an ISBN; digital items open for everyone, staff or students.
--  * Reservations: a queue per title; a returned copy is held for the next
--    reader for a few days, and nobody else can borrow it meanwhile.
--  * Loans: a limit per student, renewals (not when someone is waiting),
--    lost books charged at the book's price, fines owed, paid or waived,
--    overdue reminders.
-- =====================================================================

alter table public.library_books add column if not exists format text not null default 'print' check (format in ('print','ebook','audio','video','link'));
alter table public.library_books add column if not exists barcode text;
alter table public.library_books add column if not exists cover_url text;
alter table public.library_books add column if not exists description text;
alter table public.library_books add column if not exists year int check (year between 1400 and 2200);
alter table public.library_books add column if not exists edition text;
alter table public.library_books add column if not exists language text;
alter table public.library_books add column if not exists price numeric(14,2) check (price >= 0);
alter table public.library_books add column if not exists digital_path text;      -- a file in the library-digital bucket
alter table public.library_books add column if not exists digital_url text;       -- or a link
alter table public.library_books add column if not exists access text not null default 'everyone' check (access in ('everyone','staff','students'));
alter table public.library_books add column if not exists views int not null default 0;
create unique index if not exists library_books_barcode on public.library_books(tenant_id, barcode) where barcode is not null;
create index if not exists library_books_isbn on public.library_books(tenant_id, isbn) where isbn is not null;
insert into storage.buckets (id, name, public) values ('library-digital', 'library-digital', false) on conflict (id) do nothing;

alter table public.library_loans add column if not exists renewals int not null default 0;
alter table public.library_loans add column if not exists fine_status text not null default 'none' check (fine_status in ('none','owed','paid','waived'));
alter table public.library_loans add column if not exists fine_settled_at timestamptz;
alter table public.library_loans add column if not exists fine_settled_by uuid references public.users(id) on delete set null;
alter table public.library_loans add column if not exists lost_at timestamptz;
alter table public.library_loans add column if not exists last_reminded_at timestamptz;

alter table public.tenant_settings add column if not exists library_max_loans int not null default 3 check (library_max_loans between 1 and 50);
alter table public.tenant_settings add column if not exists library_hold_days int not null default 3 check (library_hold_days between 1 and 30);
alter table public.tenant_settings add column if not exists library_max_renewals int not null default 2 check (library_max_renewals between 0 and 20);

create table if not exists public.library_reservations (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  book_id      uuid not null references public.library_books(id) on delete cascade,
  student_id   uuid references public.students(id) on delete cascade,
  staff_id     uuid references public.staff(id) on delete cascade,
  status       text not null default 'waiting' check (status in ('waiting','ready','collected','cancelled','expired')),
  ready_at     timestamptz,
  expires_at   timestamptz,
  notified_at  timestamptz,                 -- the reader was told the book is waiting
  created_at   timestamptz not null default now(),
  check ((student_id is null) <> (staff_id is null))
);
create index if not exists library_reservations_queue on public.library_reservations(book_id, status, created_at);
create unique index if not exists library_reservations_once on public.library_reservations(book_id, coalesce(student_id, staff_id)) where status in ('waiting','ready');

create or replace function public.is_librarian()
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_role(array['librarian','school_admin','principal','platform_admin']);
$$;
grant execute on function public.is_librarian() to authenticated;

-- Copies held for readers who reserved the book (not for this borrower).
create or replace function public.library_holds_for_others(p_book uuid, p_student uuid, p_staff uuid)
returns int language sql stable security definer set search_path = public as $$
  select count(*)::int from public.library_reservations r
   where r.book_id = p_book and r.status = 'ready' and r.expires_at > now()
     and coalesce(r.student_id, r.staff_id) is distinct from coalesce(p_student, p_staff);
$$;

-- Issue: copies available after holds, digital items never, within the loan limit; a borrower's own hold is collected.
create or replace function public.library_issue(p_book uuid, p_student uuid, p_staff uuid, p_days int)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_book public.library_books; v_id uuid; v_max int; v_open int;
begin
  perform set_config('app.library_fn', 'on', true);
  if not public.is_librarian() then raise exception 'forbidden'; end if;
  select * into v_book from public.library_books where id = p_book and tenant_id = public.my_tenant_id() for update;
  if v_book.id is null then raise exception 'book not found'; end if;
  if v_book.format <> 'print' then raise exception 'digital items are read online, not lent'; end if;
  if v_book.available_copies <= public.library_holds_for_others(p_book, p_student, p_staff) then
    raise exception '%', case when v_book.available_copies > 0 then 'the copies left are held for readers who reserved this book' else 'no copies available; reserve it instead' end;
  end if;
  if p_student is not null then
    select library_max_loans into v_max from public.tenant_settings where tenant_id = v_book.tenant_id;
    select count(*) into v_open from public.library_loans where student_id = p_student and returned_at is null;
    if v_open >= coalesce(v_max, 3) then raise exception 'this student already has % books out (the most allowed)', v_open; end if;
  end if;
  update public.library_books set available_copies = available_copies - 1 where id = p_book;
  insert into public.library_loans (tenant_id, book_id, student_id, staff_id, issued_by, due_at)
  values (v_book.tenant_id, p_book, p_student, p_staff, auth.uid(), now() + make_interval(days => greatest(p_days, 1)))
  returning id into v_id;
  update public.library_reservations set status = 'collected'
   where book_id = p_book and status in ('waiting','ready') and coalesce(student_id, staff_id) = coalesce(p_student, p_staff);
  return v_id;
end $$;

-- Return: fine for late days; the copy goes to the next reader in the queue, held for them.
create or replace function public.library_return(p_loan uuid, p_fine_per_day numeric)
returns numeric language plpgsql security definer set search_path = public as $$
declare v_loan public.library_loans; v_fine numeric; v_hold int; v_next uuid;
begin
  perform set_config('app.library_fn', 'on', true);
  if not public.is_librarian() then raise exception 'forbidden'; end if;
  select * into v_loan from public.library_loans where id = p_loan and tenant_id = public.my_tenant_id() and returned_at is null for update;
  if v_loan.id is null then raise exception 'loan not found or already returned'; end if;
  v_fine := greatest(0, ceil(extract(epoch from (now() - v_loan.due_at)) / 86400.0)) * coalesce(p_fine_per_day, 0);
  update public.library_loans set returned_at = now(), fine_amount = v_fine, fine_status = case when v_fine > 0 then 'owed' else 'none' end where id = p_loan;
  update public.library_books set available_copies = least(total_copies, available_copies + 1) where id = v_loan.book_id;
  select library_hold_days into v_hold from public.tenant_settings where tenant_id = v_loan.tenant_id;
  select id into v_next from public.library_reservations where book_id = v_loan.book_id and status = 'waiting' order by created_at limit 1 for update skip locked;
  if v_next is not null then
    update public.library_reservations set status = 'ready', ready_at = now(), expires_at = now() + make_interval(days => coalesce(v_hold, 3)), notified_at = null where id = v_next;
  end if;
  return v_fine;
end $$;

-- Renew: not overdue by a lot, not past the renewal limit, and nobody waiting for the book.
create or replace function public.library_renew(p_loan uuid)
returns timestamptz language plpgsql security definer set search_path = public as $$
declare v_loan public.library_loans; v_days int; v_max int; v_due timestamptz;
begin
  perform set_config('app.library_fn', 'on', true);
  select * into v_loan from public.library_loans where id = p_loan and tenant_id = public.my_tenant_id() and returned_at is null for update;
  if v_loan.id is null then raise exception 'loan not found'; end if;
  if not (public.is_librarian() or public.is_student_self(v_loan.student_id)
          or exists (select 1 from public.staff s where s.id = v_loan.staff_id and s.user_id = auth.uid())) then raise exception 'forbidden'; end if;
  select library_loan_days, library_max_renewals into v_days, v_max from public.tenant_settings where tenant_id = v_loan.tenant_id;
  if v_loan.renewals >= coalesce(v_max, 2) then raise exception 'this book has been renewed the most times allowed; please return it'; end if;
  if exists (select 1 from public.library_reservations where book_id = v_loan.book_id and status = 'waiting') then raise exception 'someone is waiting for this book; please return it'; end if;
  if not public.is_librarian() and v_loan.due_at < now() - interval '7 days' then raise exception 'this book is well overdue; please bring it to the library'; end if;
  v_due := greatest(v_loan.due_at, now()) + make_interval(days => coalesce(v_days, 14));
  update public.library_loans set due_at = v_due, renewals = renewals + 1 where id = p_loan;
  return v_due;
end $$;

-- Reserve: for yourself (or by the librarian for a reader). If a copy is free now, it is held straight away.
create or replace function public.library_reserve(p_book uuid, p_student uuid, p_staff uuid)
returns text language plpgsql security definer set search_path = public as $$
declare v_book public.library_books; v_hold int; v_status text;
begin
  if not (public.is_librarian() or (p_student is not null and public.is_student_self(p_student))
          or (p_staff is not null and exists (select 1 from public.staff s where s.id = p_staff and s.user_id = auth.uid()))) then raise exception 'forbidden'; end if;
  select * into v_book from public.library_books where id = p_book and tenant_id = public.my_tenant_id();
  if v_book.id is null then raise exception 'book not found'; end if;
  if v_book.format <> 'print' then raise exception 'digital items can be read now; no need to reserve'; end if;
  if exists (select 1 from public.library_loans where book_id = p_book and returned_at is null and coalesce(student_id, staff_id) = coalesce(p_student, p_staff)) then
    raise exception 'you already have this book';
  end if;
  select library_hold_days into v_hold from public.tenant_settings where tenant_id = v_book.tenant_id;
  v_status := case when v_book.available_copies > public.library_holds_for_others(p_book, p_student, p_staff) then 'ready' else 'waiting' end;
  insert into public.library_reservations (tenant_id, book_id, student_id, staff_id, status, ready_at, expires_at)
  values (v_book.tenant_id, p_book, p_student, p_staff, v_status, case when v_status = 'ready' then now() end,
          case when v_status = 'ready' then now() + make_interval(days => coalesce(v_hold, 3)) end);
  return v_status;
exception when unique_violation then raise exception 'you have already reserved this book';
end $$;

-- Lost: the loan closes, the reader owes the book's price (plus any late fine), and the library has one copy fewer.
create or replace function public.library_lost(p_loan uuid)
returns numeric language plpgsql security definer set search_path = public as $$
declare v_loan public.library_loans; v_price numeric;
begin
  perform set_config('app.library_fn', 'on', true);
  if not public.is_librarian() then raise exception 'forbidden'; end if;
  select * into v_loan from public.library_loans where id = p_loan and tenant_id = public.my_tenant_id() and returned_at is null for update;
  if v_loan.id is null then raise exception 'loan not found or already closed'; end if;
  select coalesce(price, 0) into v_price from public.library_books where id = v_loan.book_id;
  update public.library_loans set returned_at = now(), lost_at = now(), fine_amount = v_price, fine_status = case when v_price > 0 then 'owed' else 'none' end where id = p_loan;
  update public.library_books set total_copies = greatest(0, total_copies - 1) where id = v_loan.book_id;
  return v_price;
end $$;

-- Holds not collected in time lapse, and the next reader gets the copy.
create or replace function public.library_expire_holds()
returns int language plpgsql security definer set search_path = public as $$
declare r record; v_next uuid; v_hold int; n int := 0;
begin
  for r in update public.library_reservations set status = 'expired' where status = 'ready' and expires_at < now() returning book_id, tenant_id loop
    select library_hold_days into v_hold from public.tenant_settings where tenant_id = r.tenant_id;
    select id into v_next from public.library_reservations where book_id = r.book_id and status = 'waiting' order by created_at limit 1;
    if v_next is not null then
      update public.library_reservations set status = 'ready', ready_at = now(), expires_at = now() + make_interval(days => coalesce(v_hold, 3)) where id = v_next;
    end if;
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.library_expire_holds() from public, anon, authenticated;
grant execute on function public.library_expire_holds() to service_role;
grant execute on function public.library_renew(uuid), public.library_reserve(uuid, uuid, uuid), public.library_lost(uuid) to authenticated;

-- Fines are settled by the library (paid or waived) and nothing else about a loan changes by hand.
drop policy if exists library_loans_settle on public.library_loans;
create policy library_loans_settle on public.library_loans for update using (tenant_id = public.my_tenant_id() and public.is_librarian()) with check (tenant_id = public.my_tenant_id());
create or replace function public.library_loan_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return new; end if;
  -- Issue, return, renew and lost go through the library functions, which set this flag for their own statement.
  if (new.book_id, new.student_id, new.staff_id, new.issued_at, new.due_at, new.returned_at, new.fine_amount, new.renewals, new.lost_at)
     is distinct from (old.book_id, old.student_id, old.staff_id, old.issued_at, old.due_at, old.returned_at, old.fine_amount, old.renewals, old.lost_at)
     and current_setting('app.library_fn', true) is distinct from 'on' then
    raise exception 'loans change only by issuing, returning, renewing or marking lost';
  end if;
  if new.fine_status is distinct from old.fine_status and current_setting('app.library_fn', true) is distinct from 'on' then
    if new.fine_status not in ('paid','waived') or old.fine_status <> 'owed' then raise exception 'a fine can only be marked paid or waived'; end if;
    new.fine_settled_at := now(); new.fine_settled_by := auth.uid();
  end if;
  return new;
end $$;
drop trigger if exists library_loan_guard on public.library_loans;
create trigger library_loan_guard before update on public.library_loans for each row execute function public.library_loan_guard();

alter table public.library_reservations enable row level security;
drop policy if exists library_reservations_read on public.library_reservations;
create policy library_reservations_read on public.library_reservations for select using (tenant_id = public.my_tenant_id() and (public.is_librarian()
  or (student_id is not null and (public.is_student_self(student_id) or public.is_guardian_of(student_id)))
  or exists (select 1 from public.staff s where s.id = library_reservations.staff_id and s.user_id = auth.uid())));
drop policy if exists library_reservations_manage on public.library_reservations;
create policy library_reservations_manage on public.library_reservations for update using (tenant_id = public.my_tenant_id() and public.is_librarian()) with check (tenant_id = public.my_tenant_id());
-- readers reserve and cancel through the functions and the server

grant all on public.library_reservations to service_role;
select public.attach_change_log();

-- ===== 20260101004600_inventory_procurement.sql =====
-- =====================================================================
--  Phase 11d: stock, assets and procurement.
--
--  * Stock items with a size or colour (uniforms), a barcode and a selling
--    price; items issued to a student or member of staff; tuck-shop and
--    uniform-shop sales take stock off automatically.
--  * Assets: serial number, supplier, warranty and a maintenance schedule;
--    services and repairs logged; any member of staff can report a fault.
--  * Procurement: suppliers; quotes against a requisition; requisitions above
--    a set amount need a second approver; purchase orders, goods received
--    into stock or the asset register, and payment recorded as an expense.
-- =====================================================================

-- ---------- Stock ----------
alter table public.inventory_items add column if not exists variant text;          -- e.g. size 10, age 7–8, blue
alter table public.inventory_items add column if not exists barcode text;
alter table public.inventory_items add column if not exists sell_price numeric(14,2) check (sell_price >= 0);
alter table public.inventory_items drop constraint if exists inventory_items_tenant_id_name_key;
create unique index if not exists inventory_items_name_variant on public.inventory_items(tenant_id, lower(name), coalesce(lower(variant), ''));
create unique index if not exists inventory_items_barcode on public.inventory_items(tenant_id, barcode) where barcode is not null;

alter table public.inventory_moves add column if not exists student_id uuid references public.students(id) on delete set null;
alter table public.inventory_moves add column if not exists staff_id uuid references public.staff(id) on delete set null;
alter table public.inventory_moves add column if not exists unit_cost numeric(14,2);
alter table public.inventory_moves add column if not exists purchase_order_id uuid;

alter table public.shop_items add column if not exists inventory_item_id uuid references public.inventory_items(id) on delete set null;
alter table public.shop_items add column if not exists barcode text;
create unique index if not exists shop_items_barcode on public.shop_items(tenant_id, barcode) where barcode is not null;

-- Issue stock to a person (uniform, textbooks, a laptop charger …).
create or replace function public.inventory_issue(p_item uuid, p_qty numeric, p_student uuid, p_staff uuid, p_reason text)
returns numeric language plpgsql security definer set search_path = public as $$
declare v_new numeric; v_tenant uuid;
begin
  if not public.has_role(array['bursar','school_admin','principal','platform_admin']) then raise exception 'forbidden'; end if;
  if p_qty is null or p_qty <= 0 then raise exception 'quantity must be positive'; end if;
  if (p_student is null) = (p_staff is null) then raise exception 'choose who receives it'; end if;
  update public.inventory_items set quantity = quantity - p_qty where id = p_item and tenant_id = public.my_tenant_id() returning quantity, tenant_id into v_new, v_tenant;
  if v_tenant is null then raise exception 'item not found'; end if;
  if v_new < 0 then raise exception 'not enough stock'; end if;
  insert into public.inventory_moves (tenant_id, item_id, kind, quantity, reason, recorded_by, student_id, staff_id)
  values (v_tenant, p_item, 'out', p_qty, coalesce(nullif(trim(p_reason), ''), 'Issued'), auth.uid(), p_student, p_staff);
  return v_new;
end $$;
grant execute on function public.inventory_issue(uuid, numeric, uuid, uuid, text) to authenticated;

-- A shop sale takes the stock it sold; a sale cannot sell what is not on the shelf.
create or replace function public.shop_sale_stock() returns trigger
language plpgsql security definer set search_path = public as $$
declare line jsonb; v_item uuid; v_name text; v_left numeric;
begin
  if new.kind <> 'purchase' or new.status <> 'success' then return null; end if;
  for line in select * from jsonb_array_elements(coalesce(new.items, '[]'::jsonb)) loop
    select s.inventory_item_id, s.name into v_item, v_name from public.shop_items s where s.id = (line ->> 'id')::uuid and s.tenant_id = new.tenant_id;
    if v_item is null then continue; end if;
    update public.inventory_items set quantity = quantity - coalesce((line ->> 'qty')::numeric, 1) where id = v_item returning quantity into v_left;
    if v_left < 0 then raise exception 'not enough % in stock', v_name; end if;
    insert into public.inventory_moves (tenant_id, item_id, kind, quantity, reason, reference, recorded_by, student_id)
    values (new.tenant_id, v_item, 'out', coalesce((line ->> 'qty')::numeric, 1), 'Shop sale', new.reference, new.recorded_by, new.student_id);
  end loop;
  return null;
exception when invalid_text_representation then return null;
end $$;
drop trigger if exists shop_sale_stock on public.wallet_transactions;
create trigger shop_sale_stock after insert on public.wallet_transactions for each row execute function public.shop_sale_stock();

-- ---------- Assets ----------
alter table public.assets add column if not exists serial_no text;
alter table public.assets add column if not exists supplier text;
alter table public.assets add column if not exists warranty_expires date;
alter table public.assets add column if not exists maintenance_every_days int check (maintenance_every_days between 1 and 3650);
alter table public.assets add column if not exists last_maintenance_on date;
alter table public.assets add column if not exists next_maintenance_on date;
alter table public.assets add column if not exists purchase_order_id uuid;

create table if not exists public.asset_maintenance (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  asset_id     uuid not null references public.assets(id) on delete cascade,
  kind         text not null default 'service' check (kind in ('service','repair','inspection','calibration','cleaning','fault')),
  status       text not null default 'done' check (status in ('reported','scheduled','done','cancelled')),
  description  text,
  due_on       date,
  done_on      date,
  cost         numeric(14,2) check (cost >= 0),
  vendor       text,
  reported_by  uuid references public.users(id) on delete set null,
  done_by      uuid references public.users(id) on delete set null,
  created_at   timestamptz not null default now()
);
create index if not exists asset_maintenance_asset on public.asset_maintenance(asset_id, created_at desc);

-- Work done moves the asset's next service date on; a fault puts it in for repair.
create or replace function public.asset_maintenance_after() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.status = 'done' and new.done_on is not null and (tg_op = 'INSERT' or old.status is distinct from 'done') then
    update public.assets set last_maintenance_on = new.done_on,
      next_maintenance_on = case when maintenance_every_days is not null then new.done_on + maintenance_every_days else next_maintenance_on end,
      status = case when status = 'repair' and new.kind in ('repair','fault') then 'in_use' else status end
     where id = new.asset_id;
  elsif new.status = 'reported' and tg_op = 'INSERT' then
    update public.assets set condition = case when condition in ('new','good') then 'fair' else condition end where id = new.asset_id;
  end if;
  return null;
end $$;
drop trigger if exists asset_maintenance_after on public.asset_maintenance;
create trigger asset_maintenance_after after insert or update on public.asset_maintenance for each row execute function public.asset_maintenance_after();

-- ---------- Procurement ----------
create table if not exists public.suppliers (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  name          text not null check (length(trim(name)) between 1 and 160),
  contact_name  text,
  phone         text,
  email         text,
  address       text,
  category      text,
  tax_id        text,
  bank_name     text,
  account_no    text,
  account_name  text,
  notes         text,
  active        boolean not null default true,
  created_at    timestamptz not null default now(),
  unique (tenant_id, name)
);

alter table public.requisitions drop constraint if exists requisitions_status_check;
alter table public.requisitions add constraint requisitions_status_check check (status in ('submitted','endorsed','approved','rejected','fulfilled','cancelled'));
alter table public.requisitions add column if not exists endorsed_by uuid references public.users(id) on delete set null;
alter table public.requisitions add column if not exists endorsed_at timestamptz;
alter table public.tenant_settings add column if not exists procurement_second_approval_over numeric(14,2) not null default 500000 check (procurement_second_approval_over >= 0);

-- Small requisitions need one approver; larger ones are endorsed first, then approved by the principal or an admin who did not endorse them.
create or replace function public.requisitions_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_limit numeric;
begin
  if auth.uid() is null then return new; end if;
  if new.status is distinct from old.status then
    if new.status = 'cancelled' and old.requested_by = auth.uid() and old.status in ('submitted','endorsed') then return new; end if;
    if not public.has_role(array['school_admin','principal','bursar','platform_admin']) then raise exception 'only approvers can change requisition status'; end if;
    if old.requested_by = auth.uid() and new.status in ('endorsed','approved','rejected') then raise exception 'you cannot approve your own requisition'; end if;
    select procurement_second_approval_over into v_limit from public.tenant_settings where tenant_id = new.tenant_id;
    if new.status = 'endorsed' then
      if old.status <> 'submitted' then raise exception 'only a new requisition can be endorsed'; end if;
      new.endorsed_by := auth.uid(); new.endorsed_at := now();
    elsif new.status = 'approved' then
      if old.status not in ('submitted','endorsed') then raise exception 'this requisition is %', old.status; end if;
      if new.total_amount > coalesce(v_limit, 500000) then
        if old.status <> 'endorsed' then raise exception 'requisitions over % need endorsing first, then a second approver', coalesce(v_limit, 500000); end if;
        if old.endorsed_by = auth.uid() then raise exception 'the second approval must come from someone other than the endorser'; end if;
        if not public.has_role(array['school_admin','principal','platform_admin']) then raise exception 'the principal or a school admin gives the second approval'; end if;
      end if;
    elsif new.status = 'fulfilled' and old.status <> 'approved' then
      raise exception 'only approved requisitions are fulfilled';
    end if;
  end if;
  if new.total_amount is distinct from old.total_amount and old.status <> 'submitted' then raise exception 'the amount cannot change after approval has started'; end if;
  return new;
end $$;

create table if not exists public.supplier_quotes (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  requisition_id  uuid not null references public.requisitions(id) on delete cascade,
  supplier_id     uuid not null references public.suppliers(id) on delete cascade,
  amount          numeric(14,2) not null check (amount >= 0),
  delivery_days   int check (delivery_days between 0 and 365),
  notes           text,
  chosen          boolean not null default false,
  created_at      timestamptz not null default now(),
  unique (requisition_id, supplier_id)
);

create table if not exists public.purchase_orders (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  po_no           text,
  requisition_id  uuid references public.requisitions(id) on delete set null,
  supplier_id     uuid not null references public.suppliers(id),
  status          text not null default 'draft' check (status in ('draft','sent','partly_received','received','cancelled')),
  total           numeric(14,2) not null default 0,
  ordered_on      date,
  expected_on     date,
  notes           text,
  paid_at         timestamptz,
  expense_id      uuid references public.expenses(id) on delete set null,
  created_by      uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  unique (tenant_id, po_no)
);
create table if not exists public.purchase_order_lines (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null references public.tenants(id) on delete cascade,
  po_id              uuid not null references public.purchase_orders(id) on delete cascade,
  description        text not null check (length(trim(description)) between 1 and 200),
  quantity           numeric not null check (quantity > 0),
  unit_cost          numeric(14,2) not null check (unit_cost >= 0),
  inventory_item_id  uuid references public.inventory_items(id) on delete set null,
  is_asset           boolean not null default false,
  received_qty       numeric not null default 0 check (received_qty >= 0),
  check (received_qty <= quantity)
);
alter table public.inventory_moves drop constraint if exists inventory_moves_po_fk;
alter table public.inventory_moves add constraint inventory_moves_po_fk foreign key (purchase_order_id) references public.purchase_orders(id) on delete set null;
alter table public.assets drop constraint if exists assets_po_fk;
alter table public.assets add constraint assets_po_fk foreign key (purchase_order_id) references public.purchase_orders(id) on delete set null;
alter table public.expenses add column if not exists purchase_order_id uuid references public.purchase_orders(id) on delete set null;

-- Order totals follow their lines; numbers are given when the order is first sent.
create or replace function public.po_lines_changed() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_po uuid;
begin
  if tg_op = 'DELETE' then v_po := old.po_id; else v_po := new.po_id; end if;
  update public.purchase_orders set total = (select coalesce(sum(round(quantity * unit_cost, 2)), 0) from public.purchase_order_lines where po_id = v_po) where id = v_po;
  return null;
end $$;
drop trigger if exists po_lines_changed on public.purchase_order_lines;
create trigger po_lines_changed after insert or update or delete on public.purchase_order_lines for each row execute function public.po_lines_changed();

create or replace function public.po_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if auth.uid() is not null then new.created_by := auth.uid(); new.status := 'draft'; new.po_no := null; new.paid_at := null; new.expense_id := null; end if;
    return new;
  end if;
  -- Receiving goods (po_receive) moves the status itself.
  if auth.uid() is null or current_setting('app.po_fn', true) = 'on' then return new; end if;
  if new.status = 'sent' and old.status = 'draft' then
    if not exists (select 1 from public.purchase_order_lines where po_id = new.id) then raise exception 'add the items before sending the order'; end if;
    new.po_no := coalesce(old.po_no, public.next_doc_no(new.tenant_id, 'po')); new.ordered_on := coalesce(new.ordered_on, current_date);
  elsif new.status is distinct from old.status and new.status in ('partly_received','received') then
    raise exception 'orders are marked received by receiving the goods';
  elsif new.status = 'cancelled' and old.status in ('partly_received','received') then
    raise exception 'goods have been received against this order';
  end if;
  if old.status <> 'draft' and (new.supplier_id is distinct from old.supplier_id) then raise exception 'the supplier cannot change after the order is sent'; end if;
  return new;
end $$;
drop trigger if exists po_guard on public.purchase_orders;
create trigger po_guard before insert or update on public.purchase_orders for each row execute function public.po_guard();

create or replace function public.po_line_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_status text;
begin
  if auth.uid() is null or current_setting('app.po_fn', true) = 'on' then return case when tg_op = 'DELETE' then old else new end; end if;
  select status into v_status from public.purchase_orders where id = case when tg_op = 'DELETE' then old.po_id else new.po_id end;
  if v_status <> 'draft' then
    if tg_op <> 'UPDATE' or (new.description, new.quantity, new.unit_cost, new.inventory_item_id, new.is_asset) is distinct from (old.description, old.quantity, old.unit_cost, old.inventory_item_id, old.is_asset)
       or new.received_qty is distinct from old.received_qty then
      raise exception 'a sent order cannot be changed; cancel it and raise another';
    end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;
drop trigger if exists po_line_guard on public.purchase_order_lines;
create trigger po_line_guard before insert or update or delete on public.purchase_order_lines for each row execute function public.po_line_guard();

-- Goods received: stock goes up, assets are registered, and the order (and its requisition) is closed when everything has arrived.
create or replace function public.po_receive(p_line uuid, p_qty numeric, p_tags text[] default null)
returns text language plpgsql security definer set search_path = public as $$
declare l public.purchase_order_lines; po public.purchase_orders; v_sup text; v_all boolean; i int;
begin
  if not public.is_finance() then raise exception 'forbidden'; end if;
  perform set_config('app.po_fn', 'on', true);
  select * into l from public.purchase_order_lines where id = p_line and tenant_id = public.my_tenant_id() for update;
  if l.id is null then raise exception 'order line not found'; end if;
  select * into po from public.purchase_orders where id = l.po_id for update;
  if po.status not in ('sent','partly_received') then raise exception 'send the order before receiving goods'; end if;
  if p_qty is null or p_qty <= 0 then raise exception 'enter the quantity received'; end if;
  if l.received_qty + p_qty > l.quantity then raise exception 'only % more were ordered', l.quantity - l.received_qty; end if;
  update public.purchase_order_lines set received_qty = received_qty + p_qty where id = l.id;
  if l.inventory_item_id is not null then
    update public.inventory_items set quantity = quantity + p_qty, unit_cost = l.unit_cost where id = l.inventory_item_id;
    insert into public.inventory_moves (tenant_id, item_id, kind, quantity, reason, reference, recorded_by, unit_cost, purchase_order_id)
    values (l.tenant_id, l.inventory_item_id, 'in', p_qty, 'Received', po.po_no, auth.uid(), l.unit_cost, po.id);
  end if;
  if l.is_asset then
    select name into v_sup from public.suppliers where id = po.supplier_id;
    for i in 1 .. floor(p_qty)::int loop
      insert into public.assets (tenant_id, tag, name, cost, purchase_date, supplier, status, purchase_order_id)
      values (l.tenant_id, coalesce(p_tags[i], po.po_no || '-' || substr(l.id::text, 1, 4) || '-' || (l.received_qty::int + i)), l.description, l.unit_cost, current_date, v_sup, 'in_store', po.id);
    end loop;
  end if;
  select bool_and(received_qty >= quantity) into v_all from public.purchase_order_lines where po_id = po.id;
  update public.purchase_orders set status = case when v_all then 'received' else 'partly_received' end where id = po.id;
  if v_all and po.requisition_id is not null then
    update public.requisitions set status = 'fulfilled' where id = po.requisition_id and status = 'approved';
  end if;
  return case when v_all then 'received' else 'partly_received' end;
end $$;
grant execute on function public.po_receive(uuid, numeric, text[]) to authenticated;

-- ---------- RLS ----------
alter table public.asset_maintenance enable row level security;
drop policy if exists asset_maintenance_read on public.asset_maintenance;
create policy asset_maintenance_read on public.asset_maintenance for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists asset_maintenance_write on public.asset_maintenance;
create policy asset_maintenance_write on public.asset_maintenance for all using (tenant_id = public.my_tenant_id() and public.is_finance())
  with check (tenant_id = public.my_tenant_id() and public.is_finance());
drop policy if exists asset_fault_report on public.asset_maintenance;
create policy asset_fault_report on public.asset_maintenance for insert with check (tenant_id = public.my_tenant_id() and public.is_staff()
  and status = 'reported' and kind = 'fault' and reported_by = auth.uid());

do $$
declare t text;
begin
  foreach t in array array['suppliers','supplier_quotes','purchase_orders','purchase_order_lines'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_finance', t);
    execute format('create policy %I on public.%I for all using (tenant_id = public.my_tenant_id() and public.is_finance()) with check (tenant_id = public.my_tenant_id() and public.is_finance())', t || '_finance', t);
  end loop;
end $$;
-- Requesters follow their own requisition's quotes and orders.
drop policy if exists purchase_orders_requester on public.purchase_orders;
create policy purchase_orders_requester on public.purchase_orders for select using (tenant_id = public.my_tenant_id()
  and exists (select 1 from public.requisitions r where r.id = purchase_orders.requisition_id and r.requested_by = auth.uid()));

grant all on public.asset_maintenance, public.suppliers, public.supplier_quotes, public.purchase_orders, public.purchase_order_lines to service_role;
select public.attach_change_log();

-- ===== 20260101004700_cocurricular.sql =====
-- =====================================================================
--  Phase 11e: co-curricular life.
--
--  * Clubs, societies and teams: who leads them, who may join (open, by
--    approval, or closed), members with roles, sessions and attendance, and a
--    fee for the group linked to fees.
--  * Competitions and events entered, with results that become achievements.
--  * Trips: departure and return, staff going, meeting point, risk
--    assessment, and a roster ticked on the day (gone, back), with an alert if
--    anyone is not back on time.
-- =====================================================================

create table if not exists public.cc_groups (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null references public.tenants(id) on delete cascade,
  name              text not null check (length(trim(name)) between 1 and 120),
  kind              text not null default 'club' check (kind in ('club','society','sport','team','choir','band','drama','other')),
  description       text,
  meets             text,                                  -- e.g. Wednesdays 3–4pm
  location          text,
  capacity          int check (capacity between 1 and 2000),
  lead_id           uuid references public.users(id) on delete set null,
  assistant_ids     uuid[] not null default '{}',
  open_to_class_ids uuid[] not null default '{}',          -- empty = every class
  joining           text not null default 'approval' check (joining in ('open','approval','closed')),
  fee_item_id       uuid references public.fee_items(id) on delete set null,
  house_id          uuid references public.houses(id) on delete set null,
  active            boolean not null default true,
  created_at        timestamptz not null default now(),
  unique (tenant_id, name)
);
create table if not exists public.cc_members (
  group_id      uuid not null references public.cc_groups(id) on delete cascade,
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  student_id    uuid not null references public.students(id) on delete cascade,
  role          text not null default 'member' check (role in ('member','captain','vice_captain','secretary','treasurer','other')),
  status        text not null default 'active' check (status in ('requested','active','left','declined')),
  requested_at  timestamptz not null default now(),
  joined_on     date,
  left_on       date,
  primary key (group_id, student_id)
);
create index if not exists cc_members_student on public.cc_members(student_id);
create table if not exists public.cc_sessions (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  group_id    uuid not null references public.cc_groups(id) on delete cascade,
  held_on     date not null,
  kind        text not null default 'meeting' check (kind in ('meeting','training','rehearsal','match','performance','other')),
  notes       text,
  created_by  uuid references public.users(id) on delete set null,
  created_at  timestamptz not null default now(),
  unique (group_id, held_on, kind)
);
create table if not exists public.cc_attendance (
  session_id  uuid not null references public.cc_sessions(id) on delete cascade,
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  student_id  uuid not null references public.students(id) on delete cascade,
  status      text not null check (status in ('present','absent','late','excused')),
  primary key (session_id, student_id)
);

create table if not exists public.competitions (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  title       text not null check (length(trim(title)) between 2 and 160),
  kind        text not null default 'sports' check (kind in ('sports','academic','arts','debate','quiz','other')),
  level       text not null default 'school' check (level in ('house','school','local','state','national','international')),
  held_on     date not null,
  venue       text,
  organiser   text,
  group_id    uuid references public.cc_groups(id) on delete set null,
  notes       text,
  created_by  uuid references public.users(id) on delete set null,
  created_at  timestamptz not null default now()
);
create table if not exists public.competition_entries (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  competition_id  uuid not null references public.competitions(id) on delete cascade,
  student_id      uuid not null references public.students(id) on delete cascade,
  event           text,                       -- e.g. 100 m, under-14 chess
  team_name       text,
  position        int check (position between 1 and 1000),
  score           text,
  award           text,
  notes           text,
  achievement_id  uuid references public.student_achievements(id) on delete set null,
  created_at      timestamptz not null default now()
);
create index if not exists competition_entries_comp on public.competition_entries(competition_id);
create unique index if not exists competition_entries_once on public.competition_entries(competition_id, student_id, coalesce(event, ''));

alter table public.school_events add column if not exists departs_at timestamptz;
alter table public.school_events add column if not exists returns_at timestamptz;
alter table public.school_events add column if not exists meeting_point text;
alter table public.school_events add column if not exists staff_ids uuid[] not null default '{}';
alter table public.school_events add column if not exists risk_assessment text;
alter table public.school_events add column if not exists emergency_contact text;
alter table public.school_events add column if not exists late_alerted_at timestamptz;
create table if not exists public.trip_roster (
  event_id     uuid not null references public.school_events(id) on delete cascade,
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  student_id   uuid not null references public.students(id) on delete cascade,
  status       text not null default 'going' check (status in ('going','departed','returned','absent','cancelled')),
  departed_at  timestamptz,
  returned_at  timestamptz,
  note         text,
  primary key (event_id, student_id)
);

-- ---------- Helpers ----------
create or replace function public.leads_group(p_group uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_school_admin() or exists (select 1 from public.cc_groups g where g.id = p_group and g.tenant_id = public.my_tenant_id()
    and (g.lead_id = auth.uid() or auth.uid() = any(g.assistant_ids)));
$$;
create or replace function public.on_trip_staff(p_event uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_school_admin() or exists (select 1 from public.school_events e where e.id = p_event and e.tenant_id = public.my_tenant_id() and auth.uid() = any(e.staff_ids));
$$;
grant execute on function public.leads_group(uuid), public.on_trip_staff(uuid) to authenticated;

-- Roster times are stamped as the status moves.
create or replace function public.trip_roster_stamp() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.status = 'departed' and (tg_op = 'INSERT' or old.status is distinct from 'departed') then new.departed_at := coalesce(new.departed_at, now()); end if;
  if new.status = 'returned' and (tg_op = 'INSERT' or old.status is distinct from 'returned') then new.returned_at := coalesce(new.returned_at, now()); end if;
  return new;
end $$;
drop trigger if exists trip_roster_stamp on public.trip_roster;
create trigger trip_roster_stamp before insert or update on public.trip_roster for each row execute function public.trip_roster_stamp();

-- Leads run their group day to day; who leads it and what it costs stay with admins.
create or replace function public.cc_groups_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or public.is_school_admin() then return new; end if;
  if new.lead_id is distinct from old.lead_id or new.assistant_ids is distinct from old.assistant_ids or new.fee_item_id is distinct from old.fee_item_id then
    raise exception 'only admins change who leads a group or its fee';
  end if;
  return new;
end $$;
drop trigger if exists cc_groups_guard on public.cc_groups;
create trigger cc_groups_guard before update on public.cc_groups for each row execute function public.cc_groups_guard();

-- ---------- RLS ----------
alter table public.cc_groups enable row level security;
drop policy if exists cc_groups_read on public.cc_groups;
create policy cc_groups_read on public.cc_groups for select using (tenant_id = public.my_tenant_id());
drop policy if exists cc_groups_write on public.cc_groups;
create policy cc_groups_write on public.cc_groups for insert with check (tenant_id = public.my_tenant_id() and public.is_school_admin());
drop policy if exists cc_groups_update on public.cc_groups;
create policy cc_groups_update on public.cc_groups for update using (tenant_id = public.my_tenant_id() and public.leads_group(id)) with check (tenant_id = public.my_tenant_id());
drop policy if exists cc_groups_delete on public.cc_groups;
create policy cc_groups_delete on public.cc_groups for delete using (tenant_id = public.my_tenant_id() and public.is_school_admin());

alter table public.cc_members enable row level security;
drop policy if exists cc_members_read on public.cc_members;
create policy cc_members_read on public.cc_members for select using (tenant_id = public.my_tenant_id()
  and (public.is_staff() or public.is_student_self(student_id) or public.is_guardian_of(student_id)));
drop policy if exists cc_members_write on public.cc_members;
create policy cc_members_write on public.cc_members for all using (tenant_id = public.my_tenant_id() and public.leads_group(group_id))
  with check (tenant_id = public.my_tenant_id() and public.leads_group(group_id));
-- students ask to join through the server, which checks the group is open to them

alter table public.cc_sessions enable row level security;
drop policy if exists cc_sessions_read on public.cc_sessions;
create policy cc_sessions_read on public.cc_sessions for select using (tenant_id = public.my_tenant_id());
drop policy if exists cc_sessions_write on public.cc_sessions;
create policy cc_sessions_write on public.cc_sessions for all using (tenant_id = public.my_tenant_id() and public.leads_group(group_id))
  with check (tenant_id = public.my_tenant_id() and public.leads_group(group_id));

alter table public.cc_attendance enable row level security;
drop policy if exists cc_attendance_read on public.cc_attendance;
create policy cc_attendance_read on public.cc_attendance for select using (tenant_id = public.my_tenant_id()
  and (public.is_staff() or public.is_student_self(student_id) or public.is_guardian_of(student_id)));
drop policy if exists cc_attendance_write on public.cc_attendance;
create policy cc_attendance_write on public.cc_attendance for all using (tenant_id = public.my_tenant_id()
  and public.leads_group((select s.group_id from public.cc_sessions s where s.id = session_id)))
  with check (tenant_id = public.my_tenant_id() and public.leads_group((select s.group_id from public.cc_sessions s where s.id = session_id)));

-- Competitions are public in the school; results for a child are seen by staff, the child and their family.
alter table public.competitions enable row level security;
drop policy if exists competitions_read on public.competitions;
create policy competitions_read on public.competitions for select using (tenant_id = public.my_tenant_id());
drop policy if exists competitions_write on public.competitions;
create policy competitions_write on public.competitions for all using (tenant_id = public.my_tenant_id() and public.is_staff())
  with check (tenant_id = public.my_tenant_id() and public.is_staff());
alter table public.competition_entries enable row level security;
drop policy if exists competition_entries_read on public.competition_entries;
create policy competition_entries_read on public.competition_entries for select using (tenant_id = public.my_tenant_id()
  and (public.is_staff() or public.is_student_self(student_id) or public.is_guardian_of(student_id)));
drop policy if exists competition_entries_write on public.competition_entries;
create policy competition_entries_write on public.competition_entries for all using (tenant_id = public.my_tenant_id() and public.is_staff())
  with check (tenant_id = public.my_tenant_id() and public.is_staff());

alter table public.trip_roster enable row level security;
drop policy if exists trip_roster_read on public.trip_roster;
create policy trip_roster_read on public.trip_roster for select using (tenant_id = public.my_tenant_id()
  and (public.is_staff() or public.is_guardian_of(student_id) or public.is_student_self(student_id)));
drop policy if exists trip_roster_write on public.trip_roster;
create policy trip_roster_write on public.trip_roster for all using (tenant_id = public.my_tenant_id() and public.on_trip_staff(event_id))
  with check (tenant_id = public.my_tenant_id() and public.on_trip_staff(event_id));

grant all on public.cc_groups, public.cc_members, public.cc_sessions, public.cc_attendance, public.competitions, public.competition_entries, public.trip_roster to service_role;
select public.attach_change_log();

-- ===== 20260101004800_portals.sql =====
-- =====================================================================
--  Phase 12a: portals and dashboards.
--
--  * Students already see their own fees (balance, what is due); the school
--    can now turn this off.
--  * A daily snapshot of the school's key numbers, so the head's dashboard
--    shows trends (attendance, fee collection, behaviour, admissions), with
--    targets the school sets.
-- =====================================================================

alter table public.tenant_settings add column if not exists student_sees_fees boolean not null default true;
-- e.g. {"attendance_rate": 95, "collection_rate": 90}
alter table public.tenant_settings add column if not exists kpi_targets jsonb not null default '{}'::jsonb;

create or replace function public.students_see_fees()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select s.student_sees_fees from public.tenant_settings s where s.tenant_id = public.my_tenant_id()), true);
$$;
grant execute on function public.students_see_fees() to authenticated;

-- Students already read their own invoices; the school can now turn that off (parents and the bursar are unaffected).
drop policy if exists fee_invoices_student_read on public.fee_invoices;
drop policy if exists fee_invoice_lines_student_read on public.fee_invoice_lines;
drop policy if exists fee_invoices_read on public.fee_invoices;
create policy fee_invoices_read on public.fee_invoices for select using (
  tenant_id = public.my_tenant_id() and (public.is_finance() or public.is_guardian_of(student_id)
    or (public.students_see_fees() and exists (select 1 from public.students s where s.id = fee_invoices.student_id and s.user_id = auth.uid()))));
drop policy if exists fee_lines_read on public.fee_invoice_lines;
create policy fee_lines_read on public.fee_invoice_lines for select using (
  exists (select 1 from public.fee_invoices i where i.id = fee_invoice_lines.invoice_id and i.tenant_id = public.my_tenant_id()
          and (public.is_finance() or public.is_guardian_of(i.student_id)
               or (public.students_see_fees() and exists (select 1 from public.students s where s.id = i.student_id and s.user_id = auth.uid())))));

-- One row per school per day, written by the daily job.
create table if not exists public.kpi_snapshots (
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  day         date not null,
  metrics     jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now(),
  primary key (tenant_id, day)
);
alter table public.kpi_snapshots enable row level security;
drop policy if exists kpi_snapshots_read on public.kpi_snapshots;
create policy kpi_snapshots_read on public.kpi_snapshots for select
  using (tenant_id = public.my_tenant_id() and (public.is_school_admin() or public.is_finance()));
-- No write policies: only the server writes snapshots.
grant all on public.kpi_snapshots to service_role;

-- Snapshots are written by the server once a day; no need to log every one in the change history.
create or replace function public.attach_change_log()
returns int language plpgsql security definer set search_path = public as $$
declare t text; n int := 0;
  skip text[] := array['data_changes','audit_logs','platform_audit_logs','message_outbox','exam_events','exam_attempts','practice_sessions',
        'browser_events','environment_events','screen_snapshots','student_presence','session_participants','raise_hands','rtc_rooms','rtc_peers','rtc_signals',
        'transport_live','push_subscriptions','doc_counters','lead_sequence_runs','access_grants','phone_login_codes','quiz_attempts','quiz_answers',
        'activity_responses','game_sessions','game_players','leaderboard_entries','conversation_messages','pickup_attempts','device_enrollments','devices',
        'teacher_commands','survey_invites','tenants',
        'learning_activity','content_attempts','xapi_statements','xapi_state','breakout_members','online_lesson_joins','tutor_messages','integration_secrets','online_lesson_hosts','admission_secrets',
        'calendar_feeds','notice_recipients','student_thread_messages',
        'sensitive_access_log','pastoral_referrals','counselling_cases','counselling_sessions','safeguarding_concerns','safeguarding_actions','wellbeing_checkins',
        'kpi_snapshots'];
begin
  for t in
    select c.table_name from information_schema.columns c
    join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name
    where c.table_schema = 'public' and c.column_name = 'tenant_id' and x.table_type = 'BASE TABLE'
  loop
    -- Re-running an older update re-attaches the trigger everywhere; this puts the exclusions back.
    execute format('drop trigger if exists zz_log_data_change on public.%I', t);
    if t = any(skip) then continue; end if;
    execute format('create trigger zz_log_data_change after insert or update or delete on public.%I for each row execute function public.log_data_change()', t);
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.attach_change_log() from public, anon, authenticated;
select public.attach_change_log();

-- ===== 20260101004900_apps.sql =====
-- =====================================================================
--  Phase 12b: the apps.
--
--  * Notification choices: each person can turn off groups of messages
--    (never safety alerts) and set quiet hours, when app, WhatsApp and SMS
--    messages wait until the morning. Email is not held.
--  * Outbox messages remember who they are for, so those choices apply
--    when they are sent.
--  * Phones running the native app (Android, iPhone) register for push
--    through Firebase Cloud Messaging alongside web push.
-- =====================================================================

create table if not exists public.notification_prefs (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  user_id      uuid references public.users(id) on delete cascade,          -- staff and students
  guardian_id  uuid references public.guardians(id) on delete cascade,      -- parents (set by the server)
  muted        text[] not null default '{}',
  quiet_from   time,
  quiet_to     time,
  updated_at   timestamptz not null default now(),
  check ((user_id is not null) <> (guardian_id is not null)),
  check (muted <@ array['attendance','learning','fees','messages','transport','activities','work','other']::text[]),
  check ((quiet_from is null) = (quiet_to is null) and (quiet_from is null or quiet_from <> quiet_to))
);
create unique index if not exists notification_prefs_user on public.notification_prefs(user_id) where user_id is not null;
create unique index if not exists notification_prefs_guardian on public.notification_prefs(guardian_id) where guardian_id is not null;

alter table public.notification_prefs enable row level security;
drop policy if exists notification_prefs_own on public.notification_prefs;
create policy notification_prefs_own on public.notification_prefs for all
  using (tenant_id = public.my_tenant_id() and user_id = auth.uid())
  with check (tenant_id = public.my_tenant_id() and user_id = auth.uid() and guardian_id is null);
-- Parents' choices are saved by the server after it identifies them (signed in or by their private link).
grant all on public.notification_prefs to service_role;

alter table public.message_outbox add column if not exists recipient_user_id uuid;
alter table public.message_outbox add column if not exists recipient_guardian_id uuid;
create index if not exists message_outbox_recipient_user on public.message_outbox(recipient_user_id) where recipient_user_id is not null;
create index if not exists message_outbox_recipient_guardian on public.message_outbox(recipient_guardian_id) where recipient_guardian_id is not null;

-- Native app devices: the endpoint holds the Firebase registration token.
alter table public.push_subscriptions add column if not exists kind text not null default 'web';
alter table public.push_subscriptions add column if not exists platform text;
alter table public.push_subscriptions drop constraint if exists push_subscriptions_kind_check;
alter table public.push_subscriptions add constraint push_subscriptions_kind_check check (kind in ('web','fcm'));
alter table public.push_subscriptions drop constraint if exists push_subscriptions_platform_check;
alter table public.push_subscriptions add constraint push_subscriptions_platform_check check (platform is null or platform in ('android','ios','web'));
alter table public.push_subscriptions alter column p256dh drop not null;
alter table public.push_subscriptions alter column auth drop not null;
alter table public.push_subscriptions drop constraint if exists push_subscriptions_keys_check;
alter table public.push_subscriptions add constraint push_subscriptions_keys_check check (kind = 'fcm' or (p256dh is not null and auth is not null));

select public.attach_change_log();

-- ===== 20260101005000_insights.sql =====
-- =====================================================================
--  Phase 13a: analytics and statutory returns.
--
--  * The school's census details (EMIS/school code, state, LGA, ownership…)
--    used on government returns.
--  * Statutory returns (the annual school census for the state ministry /
--    UBEC): figures worked out from the school's records, checked and edited
--    by an admin, then marked submitted with the ministry's reference. A
--    submitted return is kept as sent and cannot be changed.
-- =====================================================================

-- e.g. {"school_code":"LA/IKJ/123","state":"Lagos","lga":"Ikeja","ownership":"private","school_type":"junior_senior_secondary","location":"urban"}
alter table public.tenant_settings add column if not exists census_profile jsonb not null default '{}'::jsonb;

create table if not exists public.statutory_returns (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  kind          text not null default 'annual_school_census' check (kind in ('annual_school_census','enrolment_return','staff_return')),
  period        text not null check (length(trim(period)) between 4 and 20),   -- e.g. 2026/2027
  data          jsonb not null default '{}'::jsonb,
  status        text not null default 'draft' check (status in ('draft','submitted')),
  prepared_by   uuid references public.users(id) on delete set null,
  prepared_at   timestamptz not null default now(),
  submitted_by  uuid references public.users(id) on delete set null,
  submitted_at  timestamptz,
  reference     text,              -- the ministry's acknowledgement number
  notes         text,
  unique (tenant_id, kind, period)
);

-- Once submitted, the return stays as it was sent; only the acknowledgement reference and notes may be added.
create or replace function public.statutory_returns_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'DELETE' then
    if old.status = 'submitted' and auth.uid() is not null then raise exception 'a submitted return cannot be deleted'; end if;
    return old;
  end if;
  if old.status = 'submitted' and (new.status <> 'submitted' or new.data is distinct from old.data or new.period <> old.period
     or new.kind <> old.kind or new.submitted_at is distinct from old.submitted_at or new.submitted_by is distinct from old.submitted_by) then
    raise exception 'a submitted return cannot be changed';
  end if;
  if new.status = 'submitted' and old.status = 'draft' then
    new.submitted_at := coalesce(new.submitted_at, now());
    new.submitted_by := coalesce(new.submitted_by, auth.uid());
  end if;
  return new;
end $$;
drop trigger if exists statutory_returns_guard on public.statutory_returns;
create trigger statutory_returns_guard before update or delete on public.statutory_returns for each row execute function public.statutory_returns_guard();

alter table public.statutory_returns enable row level security;
drop policy if exists statutory_returns_rw on public.statutory_returns;
create policy statutory_returns_rw on public.statutory_returns for all
  using (tenant_id = public.my_tenant_id() and public.is_school_admin())
  with check (tenant_id = public.my_tenant_id() and public.is_school_admin());
grant all on public.statutory_returns to service_role;

select public.attach_change_log();

-- ===== 20260101005100_report_builder.sql =====
-- =====================================================================
--  Phase 13b: custom reports.
--
--  * Saved reports: a dataset (students, attendance, results, fees,
--    payments, applications, staff, library, behaviour…), the columns,
--    filters, grouping and totals chosen in the report builder.
--  * Kept private to their author or shared with colleagues (who still
--    only see datasets their role allows).
--  * Sent on a schedule (daily, weekly or monthly) to members of staff of
--    the same school, never to outside addresses or families.
-- =====================================================================

create table if not exists public.saved_reports (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references public.tenants(id) on delete cascade,
  owner_id       uuid references public.users(id) on delete cascade,
  name           text not null check (length(trim(name)) between 1 and 120),
  description    text,
  dataset        text not null check (dataset ~ '^[a-z_]{2,40}$'),
  spec           jsonb not null default '{}'::jsonb,
  shared         boolean not null default false,
  schedule       text not null default 'none' check (schedule in ('none','daily','weekly','monthly')),
  schedule_day   int check (schedule_day between 1 and 28),       -- weekday 1–7 (Mon–Sun) for weekly, day of month for monthly
  schedule_hour  int not null default 7 check (schedule_hour between 0 and 23),
  recipient_ids  uuid[] not null default '{}',
  next_run_at    timestamptz,
  last_sent_at   timestamptz,
  last_error     text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  check (schedule = 'none' or cardinality(recipient_ids) between 1 and 50),
  check (schedule <> 'weekly' or schedule_day between 1 and 7),
  check (schedule <> 'monthly' or schedule_day is not null)
);
create index if not exists saved_reports_due on public.saved_reports(next_run_at) where schedule <> 'none';

-- Scheduled copies go only to staff of the same school.
create or replace function public.saved_reports_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if exists (
    select 1 from unnest(new.recipient_ids) r(id)
    where not exists (select 1 from public.users u where u.id = r.id and u.tenant_id = new.tenant_id
                        and u.active and u.role not in ('parent','student'))
  ) then
    raise exception 'reports can only be sent to staff of this school';
  end if;
  if tg_op = 'UPDATE' and auth.uid() is not null and new.owner_id is distinct from old.owner_id and not public.is_school_admin() then
    raise exception 'only admins can hand a report to someone else';
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists saved_reports_guard on public.saved_reports;
create trigger saved_reports_guard before insert or update on public.saved_reports for each row execute function public.saved_reports_guard();

alter table public.saved_reports enable row level security;
drop policy if exists saved_reports_read on public.saved_reports;
create policy saved_reports_read on public.saved_reports for select
  using (tenant_id = public.my_tenant_id() and public.is_staff() and (owner_id = auth.uid() or shared or public.is_school_admin()));
drop policy if exists saved_reports_insert on public.saved_reports;
create policy saved_reports_insert on public.saved_reports for insert
  with check (tenant_id = public.my_tenant_id() and public.is_staff() and owner_id = auth.uid());
drop policy if exists saved_reports_update on public.saved_reports;
create policy saved_reports_update on public.saved_reports for update
  using (tenant_id = public.my_tenant_id() and (owner_id = auth.uid() or public.is_school_admin()))
  with check (tenant_id = public.my_tenant_id());
drop policy if exists saved_reports_delete on public.saved_reports;
create policy saved_reports_delete on public.saved_reports for delete
  using (tenant_id = public.my_tenant_id() and (owner_id = auth.uid() or public.is_school_admin()));
grant all on public.saved_reports to service_role;

select public.attach_change_log();

-- ===== 20260101005200_open_api.sql =====
-- =====================================================================
--  Phase 13c: the open API, webhooks and the school website.
--
--  * API keys: admins create keys with chosen scopes for other systems
--    (a website, a data warehouse, a district office). Only a hash is kept;
--    the key is shown once.
--  * Webhooks: other systems are told when things happen (a student is
--    admitted, an application arrives, a payment is received, results are
--    published, news is posted). Events are queued by the database and sent,
--    signed, by the every-minute job, with retries.
--  * Website: news posts for the school's own site, and events marked to
--    show there, served as a JSON feed, RSS and an embeddable widget along
--    with the admissions and enquiry forms.
-- =====================================================================

create table if not exists public.api_keys (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  name          text not null check (length(trim(name)) between 1 and 80),
  prefix        text not null unique,                 -- first characters, to recognise the key
  key_hash      text not null unique,                 -- sha-256 of the full key
  scopes        text[] not null default '{}',
  created_by    uuid references public.users(id) on delete set null,
  created_at    timestamptz not null default now(),
  last_used_at  timestamptz,
  expires_at    timestamptz,
  revoked_at    timestamptz,
  check (scopes <@ array['students:read','classes:read','staff:read','attendance:read','results:read','fees:read','payments:read',
                         'applications:read','applications:write','events:read','news:read']::text[])
);
alter table public.api_keys enable row level security;
drop policy if exists api_keys_admin on public.api_keys;
create policy api_keys_admin on public.api_keys for all
  using (tenant_id = public.my_tenant_id() and public.is_school_admin())
  with check (tenant_id = public.my_tenant_id() and public.is_school_admin());
grant all on public.api_keys to service_role;

create table if not exists public.webhook_endpoints (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  url              text not null check (url ~ '^https://[^\s/$.?#].[^\s]*$' and length(url) <= 500),
  description      text,
  events           text[] not null default '{*}',
  secret           text not null default encode(gen_random_bytes(24), 'hex'),
  active           boolean not null default true,
  failures         int not null default 0,              -- in a row; turned off after 20
  last_status      int,
  last_delivered_at timestamptz,
  created_by       uuid references public.users(id) on delete set null,
  created_at       timestamptz not null default now(),
  check (events <@ array['*','student.created','student.updated','application.created','application.status_changed',
                         'payment.received','invoice.created','result.published','news.published']::text[] and cardinality(events) > 0)
);
alter table public.webhook_endpoints enable row level security;
drop policy if exists webhook_endpoints_admin on public.webhook_endpoints;
create policy webhook_endpoints_admin on public.webhook_endpoints for all
  using (tenant_id = public.my_tenant_id() and public.is_school_admin())
  with check (tenant_id = public.my_tenant_id() and public.is_school_admin());
grant all on public.webhook_endpoints to service_role;

create table if not exists public.webhook_deliveries (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  endpoint_id      uuid not null references public.webhook_endpoints(id) on delete cascade,
  event            text not null,
  payload          jsonb not null,
  status           text not null default 'queued' check (status in ('queued','sending','delivered','failed')),
  attempts         int not null default 0,
  next_attempt_at  timestamptz not null default now(),
  response_code    int,
  last_error       text,
  created_at       timestamptz not null default now(),
  delivered_at     timestamptz
);
create index if not exists webhook_deliveries_due on public.webhook_deliveries(next_attempt_at) where status = 'queued';
create index if not exists webhook_deliveries_endpoint on public.webhook_deliveries(endpoint_id, created_at desc);
alter table public.webhook_deliveries enable row level security;
drop policy if exists webhook_deliveries_read on public.webhook_deliveries;
create policy webhook_deliveries_read on public.webhook_deliveries for select
  using (tenant_id = public.my_tenant_id() and public.is_school_admin());
grant all on public.webhook_deliveries to service_role;

-- Queues an event for every active endpoint that wants it. Cheap when a school has none.
create or replace function public.queue_webhook(p_tenant uuid, p_event text, p_payload jsonb)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from public.webhook_endpoints where tenant_id = p_tenant and active) then return; end if;
  insert into public.webhook_deliveries (tenant_id, endpoint_id, event, payload)
  select p_tenant, e.id, p_event, jsonb_build_object('id', gen_random_uuid(), 'event', p_event, 'created_at', now(), 'data', p_payload)
  from public.webhook_endpoints e
  where e.tenant_id = p_tenant and e.active and (p_event = any(e.events) or '*' = any(e.events));
end $$;
revoke all on function public.queue_webhook(uuid, text, jsonb) from public, anon, authenticated;

create or replace function public.webhook_events() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_table_name = 'students' then
    if tg_op = 'INSERT' then
      perform public.queue_webhook(new.tenant_id, 'student.created', jsonb_build_object('student_id', new.id, 'admission_no', new.admission_no,
        'first_name', new.first_name, 'last_name', new.last_name, 'class_group_id', new.class_group_id, 'status', new.status));
    elsif new.status is distinct from old.status or new.class_group_id is distinct from old.class_group_id then
      perform public.queue_webhook(new.tenant_id, 'student.updated', jsonb_build_object('student_id', new.id, 'admission_no', new.admission_no,
        'class_group_id', new.class_group_id, 'status', new.status, 'previous_status', old.status));
    end if;
  elsif tg_table_name = 'applications' then
    if tg_op = 'INSERT' then
      perform public.queue_webhook(new.tenant_id, 'application.created', jsonb_build_object('application_id', new.id, 'application_no', new.application_no,
        'applying_for', new.applying_for, 'status', new.status, 'source', new.source));
    elsif new.status is distinct from old.status then
      perform public.queue_webhook(new.tenant_id, 'application.status_changed', jsonb_build_object('application_id', new.id, 'application_no', new.application_no,
        'status', new.status, 'previous_status', old.status));
    end if;
  elsif tg_table_name = 'fee_payments' then
    if new.status = 'success' and (tg_op = 'INSERT' or old.status is distinct from 'success') then
      perform public.queue_webhook(new.tenant_id, 'payment.received', jsonb_build_object('payment_id', new.id, 'invoice_id', new.invoice_id, 'student_id', new.student_id,
        'amount', new.amount, 'currency', new.currency, 'method', new.method, 'receipt_no', new.receipt_no, 'paid_at', coalesce(new.paid_at, new.created_at)));
    end if;
  elsif tg_table_name = 'fee_invoices' then
    perform public.queue_webhook(new.tenant_id, 'invoice.created', jsonb_build_object('invoice_id', new.id, 'invoice_no', new.invoice_no, 'student_id', new.student_id,
      'term_id', new.term_id, 'total', new.total, 'due_date', new.due_date));
  elsif tg_table_name = 'report_cards' then
    if new.status = 'published' and old.status is distinct from 'published' then
      perform public.queue_webhook(new.tenant_id, 'result.published', jsonb_build_object('report_card_id', new.id, 'student_id', new.student_id, 'term_id', new.term_id,
        'average', new.average, 'position', new.position));
    end if;
  elsif tg_table_name = 'news_posts' then
    if new.status = 'published' and (tg_op = 'INSERT' or old.status is distinct from 'published') then
      perform public.queue_webhook(new.tenant_id, 'news.published', jsonb_build_object('news_id', new.id, 'title', new.title, 'slug', new.slug, 'published_at', new.published_at));
    end if;
  end if;
  return null;
end $$;

-- ---------- News for the school website ----------
create table if not exists public.news_posts (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  title         text not null check (length(trim(title)) between 2 and 160),
  slug          text not null check (slug ~ '^[a-z0-9][a-z0-9-]{0,80}$'),
  summary       text check (length(summary) <= 400),
  body          text not null default '' check (length(body) <= 50000),
  image_url     text check (image_url is null or image_url ~ '^https://'),
  status        text not null default 'draft' check (status in ('draft','published')),
  published_at  timestamptz,
  author_id     uuid references public.users(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (tenant_id, slug)
);
create or replace function public.news_posts_stamp() returns trigger language plpgsql as $$
begin
  if new.status = 'published' and new.published_at is null then new.published_at := now(); end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists news_posts_stamp on public.news_posts;
create trigger news_posts_stamp before insert or update on public.news_posts for each row execute function public.news_posts_stamp();
alter table public.news_posts enable row level security;
drop policy if exists news_posts_read on public.news_posts;
create policy news_posts_read on public.news_posts for select using (tenant_id = public.my_tenant_id());
drop policy if exists news_posts_write on public.news_posts;
create policy news_posts_write on public.news_posts for all
  using (tenant_id = public.my_tenant_id() and (public.is_school_admin() or public.has_role(array['admissions_officer'])))
  with check (tenant_id = public.my_tenant_id() and (public.is_school_admin() or public.has_role(array['admissions_officer'])));
grant all on public.news_posts to service_role;

alter table public.school_events add column if not exists show_on_website boolean not null default false;

drop trigger if exists webhook_events on public.students;
create trigger webhook_events after insert or update on public.students for each row execute function public.webhook_events();
drop trigger if exists webhook_events on public.applications;
create trigger webhook_events after insert or update on public.applications for each row execute function public.webhook_events();
drop trigger if exists webhook_events on public.fee_payments;
create trigger webhook_events after insert or update on public.fee_payments for each row execute function public.webhook_events();
drop trigger if exists webhook_events on public.fee_invoices;
create trigger webhook_events after insert on public.fee_invoices for each row execute function public.webhook_events();
drop trigger if exists webhook_events on public.report_cards;
create trigger webhook_events after update on public.report_cards for each row execute function public.webhook_events();
drop trigger if exists webhook_events on public.news_posts;
create trigger webhook_events after insert or update on public.news_posts for each row execute function public.webhook_events();

-- Deliveries are a queue; keys and endpoints hold secrets. None of them belong in the change history.
create or replace function public.attach_change_log()
returns int language plpgsql security definer set search_path = public as $$
declare t text; n int := 0;
  skip text[] := array['data_changes','audit_logs','platform_audit_logs','message_outbox','exam_events','exam_attempts','practice_sessions',
        'browser_events','environment_events','screen_snapshots','student_presence','session_participants','raise_hands','rtc_rooms','rtc_peers','rtc_signals',
        'transport_live','push_subscriptions','doc_counters','lead_sequence_runs','access_grants','phone_login_codes','quiz_attempts','quiz_answers',
        'activity_responses','game_sessions','game_players','leaderboard_entries','conversation_messages','pickup_attempts','device_enrollments','devices',
        'teacher_commands','survey_invites','tenants',
        'learning_activity','content_attempts','xapi_statements','xapi_state','breakout_members','online_lesson_joins','tutor_messages','integration_secrets','online_lesson_hosts','admission_secrets',
        'calendar_feeds','notice_recipients','student_thread_messages',
        'sensitive_access_log','pastoral_referrals','counselling_cases','counselling_sessions','safeguarding_concerns','safeguarding_actions','wellbeing_checkins',
        'kpi_snapshots',
        'api_keys','webhook_endpoints','webhook_deliveries'];
begin
  for t in
    select c.table_name from information_schema.columns c
    join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name
    where c.table_schema = 'public' and c.column_name = 'tenant_id' and x.table_type = 'BASE TABLE'
  loop
    -- Re-running an older update re-attaches the trigger everywhere; this puts the exclusions back.
    execute format('drop trigger if exists zz_log_data_change on public.%I', t);
    if t = any(skip) then continue; end if;
    execute format('create trigger zz_log_data_change after insert or update or delete on public.%I for each row execute function public.log_data_change()', t);
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.attach_change_log() from public, anon, authenticated;
select public.attach_change_log();

-- ===== 20260101005300_lti.sql =====
-- =====================================================================
--  Phase 13d: LTI 1.3 (Learning Tools Interoperability).
--
--  The school system acts as the LTI platform: admins register outside
--  learning tools (Khan Academy, Labster, H5P.com, publisher content…);
--  teachers add a tool to a class (optionally tied to homework); students
--  open it signed in, with no extra password. Tools that support Assignment
--  and Grade Services send scores back; scores tied to homework become the
--  homework mark.
-- =====================================================================

-- The platform's signing keys (shared by every school; the private key never leaves the server).
create table if not exists public.lti_platform_keys (
  kid          text primary key,
  public_jwk   jsonb not null,
  private_pem  text not null,
  active       boolean not null default true,
  created_at   timestamptz not null default now()
);
alter table public.lti_platform_keys enable row level security;   -- server only
grant all on public.lti_platform_keys to service_role;

create table if not exists public.lti_tools (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  name             text not null check (length(trim(name)) between 1 and 120),
  description      text,
  client_id        text not null unique default replace(gen_random_uuid()::text, '-', ''),
  deployment_id    text not null default replace(gen_random_uuid()::text, '-', ''),
  oidc_login_url   text not null check (oidc_login_url ~ '^https://'),
  target_link_uri  text not null check (target_link_uri ~ '^https://'),
  redirect_uris    text[] not null default '{}',
  jwks_url         text check (jwks_url is null or jwks_url ~ '^https://'),
  public_key_pem   text,
  custom           jsonb not null default '{}'::jsonb,
  send_name        boolean not null default true,
  send_email       boolean not null default false,
  grades           boolean not null default true,
  active           boolean not null default true,
  created_by       uuid references public.users(id) on delete set null,
  created_at       timestamptz not null default now(),
  check (jwks_url is not null or public_key_pem is not null or not grades)
);
alter table public.lti_tools enable row level security;
drop policy if exists lti_tools_read on public.lti_tools;
create policy lti_tools_read on public.lti_tools for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists lti_tools_write on public.lti_tools;
create policy lti_tools_write on public.lti_tools for all
  using (tenant_id = public.my_tenant_id() and public.is_school_admin())
  with check (tenant_id = public.my_tenant_id() and public.is_school_admin());
grant all on public.lti_tools to service_role;

create table if not exists public.lti_links (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  tool_id         uuid not null references public.lti_tools(id) on delete cascade,
  title           text not null check (length(trim(title)) between 1 and 160),
  class_group_id  uuid references public.class_groups(id) on delete cascade,
  subject_id      uuid references public.subjects(id) on delete set null,
  homework_id     uuid references public.homework(id) on delete set null,
  target_link_uri text check (target_link_uri is null or target_link_uri ~ '^https://'),   -- a deep link inside the tool
  custom          jsonb not null default '{}'::jsonb,
  score_maximum   numeric check (score_maximum is null or score_maximum > 0),
  open_in         text not null default 'window' check (open_in in ('window','frame')),
  created_by      uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now()
);
create index if not exists lti_links_class on public.lti_links(class_group_id);

-- A student may see the tools added to their own class (or to everyone).
create or replace function public.in_my_class(p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select p_class is null or exists (select 1 from public.students s where s.user_id = auth.uid() and s.tenant_id = public.my_tenant_id() and s.class_group_id = p_class);
$$;
grant execute on function public.in_my_class(uuid) to authenticated;

alter table public.lti_links enable row level security;
drop policy if exists lti_links_read on public.lti_links;
create policy lti_links_read on public.lti_links for select using (tenant_id = public.my_tenant_id() and (public.is_staff() or public.in_my_class(class_group_id)));
drop policy if exists lti_links_write on public.lti_links;
create policy lti_links_write on public.lti_links for all
  using (tenant_id = public.my_tenant_id() and public.is_staff())
  with check (tenant_id = public.my_tenant_id() and public.is_staff()
    and exists (select 1 from public.lti_tools t where t.id = tool_id and t.tenant_id = public.my_tenant_id() and t.active));
grant all on public.lti_links to service_role;

-- One row per launch: the login hint is single-use and expires after five minutes.
create table if not exists public.lti_launches (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  link_id     uuid not null references public.lti_links(id) on delete cascade,
  user_id     uuid not null references public.users(id) on delete cascade,
  created_at  timestamptz not null default now(),
  used_at     timestamptz
);
alter table public.lti_launches enable row level security;   -- server only
grant all on public.lti_launches to service_role;

create table if not exists public.lti_scores (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null references public.tenants(id) on delete cascade,
  link_id            uuid not null references public.lti_links(id) on delete cascade,
  user_id            uuid not null references public.users(id) on delete cascade,
  score_given        numeric,
  score_maximum      numeric,
  activity_progress  text,
  grading_progress   text,
  comment            text,
  tool_timestamp     timestamptz,
  received_at        timestamptz not null default now(),
  unique (link_id, user_id)
);
alter table public.lti_scores enable row level security;
drop policy if exists lti_scores_read on public.lti_scores;
create policy lti_scores_read on public.lti_scores for select using (tenant_id = public.my_tenant_id() and (public.is_staff() or user_id = auth.uid()));
grant all on public.lti_scores to service_role;

-- Launch records are a short-lived log and keys are secrets: neither belongs in the change history.
create or replace function public.attach_change_log()
returns int language plpgsql security definer set search_path = public as $$
declare t text; n int := 0;
  skip text[] := array['data_changes','audit_logs','platform_audit_logs','message_outbox','exam_events','exam_attempts','practice_sessions',
        'browser_events','environment_events','screen_snapshots','student_presence','session_participants','raise_hands','rtc_rooms','rtc_peers','rtc_signals',
        'transport_live','push_subscriptions','doc_counters','lead_sequence_runs','access_grants','phone_login_codes','quiz_attempts','quiz_answers',
        'activity_responses','game_sessions','game_players','leaderboard_entries','conversation_messages','pickup_attempts','device_enrollments','devices',
        'teacher_commands','survey_invites','tenants',
        'learning_activity','content_attempts','xapi_statements','xapi_state','breakout_members','online_lesson_joins','tutor_messages','integration_secrets','online_lesson_hosts','admission_secrets',
        'calendar_feeds','notice_recipients','student_thread_messages',
        'sensitive_access_log','pastoral_referrals','counselling_cases','counselling_sessions','safeguarding_concerns','safeguarding_actions','wellbeing_checkins',
        'kpi_snapshots',
        'api_keys','webhook_endpoints','webhook_deliveries',
        'lti_launches','lti_platform_keys'];
begin
  for t in
    select c.table_name from information_schema.columns c
    join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name
    where c.table_schema = 'public' and c.column_name = 'tenant_id' and x.table_type = 'BASE TABLE'
  loop
    -- Re-running an older update re-attaches the trigger everywhere; this puts the exclusions back.
    execute format('drop trigger if exists zz_log_data_change on public.%I', t);
    if t = any(skip) then continue; end if;
    execute format('create trigger zz_log_data_change after insert or update or delete on public.%I for each row execute function public.log_data_change()', t);
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.attach_change_log() from public, anon, authenticated;
select public.attach_change_log();

-- ===== 20260101005400_classroom_sync.sql =====
-- =====================================================================
--  Phase 13e: Google Classroom and Microsoft Teams / OneNote.
--
--  * Each teacher connects their own Google or Microsoft school account
--    (tokens are kept on the server only).
--  * A class (and subject) is linked to a Classroom course or a Teams class.
--  * Homework is sent across as an assignment, and marks are brought back
--    into the homework, matched by email.
--  * Lesson notes can be sent to the teacher's OneNote.
-- =====================================================================

create table if not exists public.oauth_connections (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references public.tenants(id) on delete cascade,
  user_id        uuid not null references public.users(id) on delete cascade,
  provider       text not null check (provider in ('google','microsoft')),
  account_email  text,
  access_token   text not null,
  refresh_token  text,
  expires_at     timestamptz,
  scopes         text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  unique (user_id, provider)
);
alter table public.oauth_connections enable row level security;   -- server only: tokens never reach the browser
grant all on public.oauth_connections to service_role;

create table if not exists public.class_links (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  class_group_id  uuid not null references public.class_groups(id) on delete cascade,
  subject_id      uuid references public.subjects(id) on delete cascade,
  provider        text not null check (provider in ('google','microsoft')),
  external_id     text not null check (length(external_id) between 1 and 200),
  external_name   text,
  external_url    text,
  linked_by       uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now()
);
create unique index if not exists class_links_once on public.class_links(class_group_id, coalesce(subject_id, '00000000-0000-0000-0000-000000000000'::uuid), provider);
alter table public.class_links enable row level security;
drop policy if exists class_links_read on public.class_links;
create policy class_links_read on public.class_links for select using (tenant_id = public.my_tenant_id() and public.is_staff());
grant all on public.class_links to service_role;   -- written by the server after checking the teacher teaches the class

create table if not exists public.homework_external (
  homework_id     uuid not null references public.homework(id) on delete cascade,
  provider        text not null check (provider in ('google','microsoft')),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  class_link_id   uuid references public.class_links(id) on delete set null,
  external_id     text not null,
  external_url    text,
  pushed_by       uuid references public.users(id) on delete set null,
  pushed_at       timestamptz not null default now(),
  grades_pulled_at timestamptz,
  primary key (homework_id, provider)
);
alter table public.homework_external enable row level security;
drop policy if exists homework_external_read on public.homework_external;
create policy homework_external_read on public.homework_external for select using (tenant_id = public.my_tenant_id() and public.is_staff());
grant all on public.homework_external to service_role;

alter table public.lesson_notes add column if not exists onenote_url text;

-- Tokens are secrets: keep them out of the change history.
create or replace function public.attach_change_log()
returns int language plpgsql security definer set search_path = public as $$
declare t text; n int := 0;
  skip text[] := array['data_changes','audit_logs','platform_audit_logs','message_outbox','exam_events','exam_attempts','practice_sessions',
        'browser_events','environment_events','screen_snapshots','student_presence','session_participants','raise_hands','rtc_rooms','rtc_peers','rtc_signals',
        'transport_live','push_subscriptions','doc_counters','lead_sequence_runs','access_grants','phone_login_codes','quiz_attempts','quiz_answers',
        'activity_responses','game_sessions','game_players','leaderboard_entries','conversation_messages','pickup_attempts','device_enrollments','devices',
        'teacher_commands','survey_invites','tenants',
        'learning_activity','content_attempts','xapi_statements','xapi_state','breakout_members','online_lesson_joins','tutor_messages','integration_secrets','online_lesson_hosts','admission_secrets',
        'calendar_feeds','notice_recipients','student_thread_messages',
        'sensitive_access_log','pastoral_referrals','counselling_cases','counselling_sessions','safeguarding_concerns','safeguarding_actions','wellbeing_checkins',
        'kpi_snapshots',
        'api_keys','webhook_endpoints','webhook_deliveries',
        'lti_launches','lti_platform_keys',
        'oauth_connections'];
begin
  for t in
    select c.table_name from information_schema.columns c
    join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name
    where c.table_schema = 'public' and c.column_name = 'tenant_id' and x.table_type = 'BASE TABLE'
  loop
    -- Re-running an older update re-attaches the trigger everywhere; this puts the exclusions back.
    execute format('drop trigger if exists zz_log_data_change on public.%I', t);
    if t = any(skip) then continue; end if;
    execute format('create trigger zz_log_data_change after insert or update or delete on public.%I for each row execute function public.log_data_change()', t);
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function public.attach_change_log() from public, anon, authenticated;
select public.attach_change_log();

-- ===== 20260101005500_compliance_docs.sql =====
-- =====================================================================
--  Phase 13f: compliance documents and inspection readiness.
--
--  * A document library for policies, certificates, inspection files,
--    minutes and risk assessments: versions, approval, review dates for
--    policies, expiry dates for certificates, who may see each, and
--    policies staff must read and confirm.
--  * The single central record: pre-employment and safeguarding checks on
--    every member of staff (identity, right to work, qualifications,
--    references, police checks, medical fitness, training) with dates.
--  * Inspection readiness: progress on each requirement of the frameworks
--    the school follows (MoE/SUBEB minimum standards, BSO, COBIS,
--    Cambridge centre), with owners, notes and the documents that show it.
-- =====================================================================

insert into storage.buckets (id, name, public) values ('school-documents', 'school-documents', false) on conflict (id) do nothing;

create table if not exists public.school_documents (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  family_id       uuid not null default gen_random_uuid(),     -- every version of the same document shares this
  version         int not null default 1 check (version >= 1),
  title           text not null check (length(trim(title)) between 2 and 200),
  category        text not null check (category in ('policy','certificate','inspection','minutes','risk_assessment','procedure','report','plan','other')),
  description     text,
  path            text,                                         -- private storage path (null for a link-only record)
  mime            text,
  size_bytes      int,
  visibility      text not null default 'staff' check (visibility in ('leaders','staff','parents')),
  status          text not null default 'draft' check (status in ('draft','approved','superseded','archived')),
  approved_by     uuid references public.users(id) on delete set null,
  approved_at     timestamptz,
  review_due_on   date,                                         -- policies: next review
  expires_on      date,                                         -- certificates: when it runs out
  issued_by       text,                                         -- e.g. Lagos State Fire Service
  reference_no    text,
  tags            text[] not null default '{}',
  requires_ack    boolean not null default false,               -- staff must confirm they have read it
  reminded_at     timestamptz,
  owner_id        uuid references public.users(id) on delete set null,
  created_by      uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (family_id, version)
);
create index if not exists school_documents_tenant on public.school_documents(tenant_id, category, status);

-- Approving a new version retires the old one; approval is stamped.
create or replace function public.school_documents_stamp() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  new.updated_at := now();
  if new.status = 'approved' and (tg_op = 'INSERT' or old.status is distinct from 'approved') then
    new.approved_at := coalesce(new.approved_at, now());
    new.approved_by := coalesce(new.approved_by, auth.uid());
    update public.school_documents set status = 'superseded', updated_at = now()
      where family_id = new.family_id and id <> new.id and status = 'approved';
  end if;
  return new;
end $$;
drop trigger if exists school_documents_stamp on public.school_documents;
create trigger school_documents_stamp before insert or update on public.school_documents for each row execute function public.school_documents_stamp();

create or replace function public.can_see_document(p_visibility text, p_status text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_school_admin() or public.has_role(array['qa_officer','hr_manager'])
    or (p_status = 'approved' and (p_visibility = 'staff' and public.is_staff() or p_visibility = 'parents' and (public.is_staff() or public.has_role(array['parent']))));
$$;
grant execute on function public.can_see_document(text, text) to authenticated;

alter table public.school_documents enable row level security;
drop policy if exists school_documents_read on public.school_documents;
create policy school_documents_read on public.school_documents for select using (tenant_id = public.my_tenant_id() and public.can_see_document(visibility, status));
drop policy if exists school_documents_write on public.school_documents;
create policy school_documents_write on public.school_documents for all
  using (tenant_id = public.my_tenant_id() and (public.is_school_admin() or public.has_role(array['qa_officer','hr_manager'])))
  with check (tenant_id = public.my_tenant_id() and (public.is_school_admin() or public.has_role(array['qa_officer','hr_manager'])));
grant all on public.school_documents to service_role;

create table if not exists public.document_acknowledgements (
  document_id      uuid not null references public.school_documents(id) on delete cascade,
  user_id          uuid not null references public.users(id) on delete cascade,
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  acknowledged_at  timestamptz not null default now(),
  primary key (document_id, user_id)
);
alter table public.document_acknowledgements enable row level security;
drop policy if exists document_ack_read on public.document_acknowledgements;
create policy document_ack_read on public.document_acknowledgements for select
  using (tenant_id = public.my_tenant_id() and (user_id = auth.uid() or public.is_school_admin() or public.has_role(array['qa_officer','hr_manager'])));
drop policy if exists document_ack_insert on public.document_acknowledgements;
create policy document_ack_insert on public.document_acknowledgements for insert
  with check (tenant_id = public.my_tenant_id() and user_id = auth.uid() and public.is_staff()
    and exists (select 1 from public.school_documents d where d.id = document_id and d.tenant_id = public.my_tenant_id() and d.status = 'approved' and d.requires_ack));
grant all on public.document_acknowledgements to service_role;

-- ---------- Single central record ----------
create table if not exists public.staff_checks (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  staff_id      uuid not null references public.staff(id) on delete cascade,
  kind          text not null check (kind in ('identity','right_to_work','qualifications','references','police_check','overseas_police_check',
                                               'prohibition_check','medical_fitness','safeguarding_training','first_aid_training','other')),
  outcome       text not null default 'clear' check (outcome in ('clear','concern','pending','not_required')),
  checked_on    date,
  expires_on    date,
  reference_no  text,
  checked_by    uuid references public.users(id) on delete set null,
  document_id   uuid references public.staff_documents(id) on delete set null,
  notes         text,
  created_at    timestamptz not null default now(),
  check (outcome = 'pending' or outcome = 'not_required' or checked_on is not null)
);
create index if not exists staff_checks_staff on public.staff_checks(staff_id, kind);
alter table public.staff_checks enable row level security;
drop policy if exists staff_checks_rw on public.staff_checks;
create policy staff_checks_rw on public.staff_checks for all
  using (tenant_id = public.my_tenant_id() and public.is_hr())
  with check (tenant_id = public.my_tenant_id() and public.is_hr());
drop policy if exists staff_checks_own on public.staff_checks;
create policy staff_checks_own on public.staff_checks for select using (tenant_id = public.my_tenant_id() and staff_id = public.my_staff_id());
grant all on public.staff_checks to service_role;

-- ---------- Inspection readiness ----------
create table if not exists public.inspection_progress (
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  framework        text not null check (framework ~ '^[a-z_]{2,30}$'),
  requirement_key  text not null check (requirement_key ~ '^[a-z0-9_.]{2,60}$'),
  status           text not null default 'not_started' check (status in ('not_started','in_progress','met','not_applicable')),
  owner_id         uuid references public.users(id) on delete set null,
  notes            text,
  document_ids     uuid[] not null default '{}',
  review_on        date,
  updated_by       uuid references public.users(id) on delete set null,
  updated_at       timestamptz not null default now(),
  primary key (tenant_id, framework, requirement_key)
);
alter table public.inspection_progress enable row level security;
drop policy if exists inspection_progress_read on public.inspection_progress;
create policy inspection_progress_read on public.inspection_progress for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists inspection_progress_write on public.inspection_progress;
create policy inspection_progress_write on public.inspection_progress for all
  using (tenant_id = public.my_tenant_id() and (public.is_school_admin() or public.has_role(array['qa_officer']) or owner_id = auth.uid()))
  with check (tenant_id = public.my_tenant_id() and (public.is_school_admin() or public.has_role(array['qa_officer']) or owner_id = auth.uid()));
grant all on public.inspection_progress to service_role;

alter table public.tenant_settings add column if not exists inspection_frameworks text[] not null default '{}';

select public.attach_change_log();

-- ===== 20260101005600_esign.sql =====
-- =====================================================================
--  Phase 13g: e-signatures for forms and contracts.
--
--  * A signature request holds the text (and optionally a document from the
--    library) and the people who must sign: staff, parents (for a child) or
--    someone outside the school. Each signer gets a private single-use link.
--  * Signing records the typed name, an optional drawn signature, time,
--    IP address and browser, and a fingerprint (SHA-256) of exactly what was
--    signed. A signature cannot be changed afterwards.
--  * For parents' forms, one parent signing for a child is enough; the
--    request completes when every signer (or every child) is done.
--  * Signing a staff contract marks it accepted in HR.
-- =====================================================================

create table if not exists public.signature_requests (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null references public.tenants(id) on delete cascade,
  title              text not null check (length(trim(title)) between 2 and 200),
  kind               text not null default 'form' check (kind in ('form','contract','policy','consent','other')),
  body               text not null default '' check (length(body) <= 100000),
  document_id        uuid references public.school_documents(id) on delete set null,
  staff_contract_id  uuid references public.staff_contracts(id) on delete set null,
  rule               text not null default 'all' check (rule in ('all','any_per_child')),
  content_hash       text not null check (content_hash ~ '^[0-9a-f]{64}$'),
  due_on             date,
  status             text not null default 'open' check (status in ('open','completed','cancelled')),
  created_by         uuid references public.users(id) on delete set null,
  created_at         timestamptz not null default now(),
  completed_at       timestamptz,
  check (length(trim(body)) > 0 or document_id is not null)
);

create table if not exists public.signature_signers (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  request_id      uuid not null references public.signature_requests(id) on delete cascade,
  signer_type     text not null check (signer_type in ('staff','guardian','external')),
  user_id         uuid references public.users(id) on delete set null,
  guardian_id     uuid references public.guardians(id) on delete set null,
  student_id      uuid references public.students(id) on delete set null,
  name            text not null check (length(trim(name)) between 1 and 160),
  email           text,
  token           text not null unique default encode(gen_random_bytes(24), 'hex'),
  status          text not null default 'pending' check (status in ('pending','viewed','signed','declined','not_needed')),
  viewed_at       timestamptz,
  signed_at       timestamptz,
  typed_name      text,
  signature_png   text check (signature_png is null or (signature_png like 'data:image/png;base64,%' and length(signature_png) <= 400000)),
  decline_reason  text,
  signed_hash     text,
  ip              text,
  user_agent      text,
  created_at      timestamptz not null default now(),
  check (signer_type <> 'staff' or user_id is not null),
  check (signer_type <> 'guardian' or (guardian_id is not null and student_id is not null)),
  check (status <> 'signed' or (signed_at is not null and typed_name is not null and signed_hash is not null))
);
create index if not exists signature_signers_request on public.signature_signers(request_id);
create index if not exists signature_signers_user on public.signature_signers(user_id) where user_id is not null;

-- A signature, once given or declined, stays as it was; signatures must match what was sent.
create or replace function public.signature_signers_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare r public.signature_requests;
begin
  if tg_op = 'DELETE' then
    if old.status = 'signed' and auth.uid() is not null then raise exception 'a signature cannot be deleted'; end if;
    return old;
  end if;
  if old.status in ('signed','declined') and row(new.*) is distinct from row(old.*) then
    raise exception 'a signature cannot be changed';
  end if;
  if new.status = 'signed' and old.status <> 'signed' then
    select * into r from public.signature_requests where id = new.request_id;
    if r.status <> 'open' then raise exception 'this request is no longer open'; end if;
    if new.signed_hash is distinct from r.content_hash then raise exception 'the document changed since it was sent'; end if;
  end if;
  return new;
end $$;
drop trigger if exists signature_signers_guard on public.signature_signers;
create trigger signature_signers_guard before update or delete on public.signature_signers for each row execute function public.signature_signers_guard();

-- After each signature: other parents of the same child are not needed (any-per-child forms);
-- the request completes when nobody is left to sign; a signed contract is accepted.
create or replace function public.signature_progress() returns trigger
language plpgsql security definer set search_path = public as $$
declare r public.signature_requests;
begin
  if new.status not in ('signed','declined') or old.status = new.status then return null; end if;
  select * into r from public.signature_requests where id = new.request_id;
  if new.status = 'signed' and r.rule = 'any_per_child' and new.student_id is not null then
    update public.signature_signers set status = 'not_needed'
      where request_id = new.request_id and student_id = new.student_id and id <> new.id and status in ('pending','viewed');
  end if;
  if new.status = 'signed' and not exists (select 1 from public.signature_signers where request_id = new.request_id and status in ('pending','viewed','declined')) then
    update public.signature_requests set status = 'completed', completed_at = now() where id = new.request_id and status = 'open';
    if r.staff_contract_id is not null then
      update public.staff_contracts set accepted_at = coalesce(accepted_at, now()) where id = r.staff_contract_id;
    end if;
  end if;
  return null;
end $$;
drop trigger if exists signature_progress on public.signature_signers;
create trigger signature_progress after update on public.signature_signers for each row execute function public.signature_progress();

-- Requests with signatures on them are kept.
create or replace function public.signature_requests_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'DELETE' then
    if auth.uid() is not null and exists (select 1 from public.signature_signers where request_id = old.id and status = 'signed') then
      raise exception 'a request with signatures cannot be deleted; cancel it instead';
    end if;
    return old;
  end if;
  if auth.uid() is not null and (new.content_hash <> old.content_hash or new.body <> old.body or new.title <> old.title or new.document_id is distinct from old.document_id) then
    raise exception 'a sent request cannot be edited; cancel it and send a new one';
  end if;
  if old.status in ('completed','cancelled') and new.status <> old.status and auth.uid() is not null then
    raise exception 'this request is closed';
  end if;
  return new;
end $$;
drop trigger if exists signature_requests_guard on public.signature_requests;
create trigger signature_requests_guard before update or delete on public.signature_requests for each row execute function public.signature_requests_guard();

-- Helpers (security definer) so the two tables' policies do not query each other.
create or replace function public.can_manage_signatures(p_created_by uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_staff() and (public.is_school_admin() or public.is_hr() or p_created_by = auth.uid());
$$;
create or replace function public.manages_signature_request(p_request uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.signature_requests r where r.id = p_request and r.tenant_id = public.my_tenant_id() and public.can_manage_signatures(r.created_by));
$$;
create or replace function public.signs_request(p_request uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.signature_signers s where s.request_id = p_request and (s.user_id = auth.uid()
    or s.guardian_id in (select g.id from public.guardians g where g.user_id = auth.uid())));
$$;
grant execute on function public.can_manage_signatures(uuid), public.manages_signature_request(uuid), public.signs_request(uuid) to authenticated;

alter table public.signature_requests enable row level security;
drop policy if exists signature_requests_read on public.signature_requests;
create policy signature_requests_read on public.signature_requests for select
  using (tenant_id = public.my_tenant_id() and (public.can_manage_signatures(created_by) or public.signs_request(id)));
drop policy if exists signature_requests_cancel on public.signature_requests;
create policy signature_requests_cancel on public.signature_requests for update
  using (tenant_id = public.my_tenant_id() and public.can_manage_signatures(created_by))
  with check (tenant_id = public.my_tenant_id());
-- Requests and signers are created, and signatures recorded, by the server.
grant all on public.signature_requests to service_role;

alter table public.signature_signers enable row level security;
drop policy if exists signature_signers_read on public.signature_signers;
create policy signature_signers_read on public.signature_signers for select using (tenant_id = public.my_tenant_id() and (
  user_id = auth.uid() or guardian_id in (select g.id from public.guardians g where g.user_id = auth.uid()) or public.manages_signature_request(request_id)));
grant all on public.signature_signers to service_role;

select public.attach_change_log();

